window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210222-7","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"厚生委員会","time":"午前１０時００分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(8)から行います。 それでは、(8)第２３号議案 品川区手数料条例の一部を改正する条例","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(8)から行います。 それでは、(8)第２３号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"１個１個非常にややこしかったのですけれども、住民基本台帳法、これは法律で定められたということなのですが、デジタル化という背景があったということなのですけれども、単にそれだけなのでしょうか。規定整備ということなのですけれども、もしそれ以外の背景があるなら、お教え願えればと思います。戸籍のほうはその質問です。","respondent":"木村戸籍住民課長","answer":"今回のデジタル化の法改正の住民基本台帳法の改正の背景ですけれども、今まで保存期間が、実際にお亡くなりになって除票になってから、５年間という形で保存されておりまして、それを超えると、いわゆる焼却処分というか、もうこの世からなくなってしまうという形だったのですが。","voiceIndex":8,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"これ、２,０００m2以上だったものが３００m2以上と、数字だけからいうと非常に広がった感じがするのですけれども、やはりその趣旨をお伺いしたいということと、それからこれによってどのぐらいの建物が、かなり増えるような印象があるのですが、やはり実際にかなり増えるのでしょうか。それから、具体的にどのような建物が増えてくるとイメージすればいいのかということもお伺いしたいと思います。","respondent":"長尾建築課長","answer":"どのくらい増える、対象が拡大することでどのくらい建物として増える見込みかというところです。現状としまして、今回対象になる非住宅の３００m2以上のものというのは、届出として大体年間で４０件ほどあります。","voiceIndex":10,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それが今回定められたということですけれども、これはなぜ規定がなかったのか、それから３００円で対応していたものが８７０円になったという、大した額でないといえばないような気もするのですが、値上げといえば値上げですし、ここのところがどうしてこのようになったのかということがいま一つよく分からないのですけれども、もう少しご説明いただければと思ったのですが、よろしいでしょうか。","respondent":"鈴木生活衛生課長","answer":"食品衛生関係の手数料、今回値上げがないかですけれども、先ほど経過措置でご説明したように、新制度で金額が高くなる場合は旧制度の安いほうを適用ということにしておりますので、基本的に値上げはございません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"国が設定して、この８７０円でやれというように言ってきたということで理解すればよろしいのですか。","respondent":"鈴木生活衛生課長","answer":"国のほうで統一的な金額をという指示はございませんが、ただ２３区のほかの区を見ましても、国と同じ業務内容ということで証明書の額を合わせたというのが、大半の区での基本的な考え方です。","voiceIndex":14,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"端的に伺っていきたいと思います。一番右下に届出のことについても書いてあるのですけれども、これによって一体何が変わるのか。","respondent":"鈴木生活衛生課長","answer":"これに伴う、手数料の考え方と、それから保健所での対応の違いですけれども、基本的に許可業種については、現在ももう啓発や指導を行っておりますが、ＨＡＣＣＰに沿ったものに適用できるようなアドバイスや支援をするということになります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"ということは、保健所とすると、今までよりも業務が、確認の業務が増えるという認識でいいのか、それとも今までとそれほど変わらないというお話、新しい係、主査ですか、立てられた、たしかそのような記憶があるのですけれども、ということはそのような意味で捉えていいのかというところ、確認だけさせてください。","respondent":"鈴木生活衛生課長","answer":"再度ご質問の内容に関しましては、基本的に業務量として大きく変化はないかと思いますが、そのご相談の内容の適用業種によっては、これまでの許可、届出よりも必要書類が増えたり、そのご相談内容が増えたりする可能性はあるというふうに考えております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"付則の考え方で、コロナの影響を受けているので低いほうを適用するということなのですけれども、これはいつまで続くのか、これは手数料を見直すまで続くと考えていいのか、そして手数料を見直すというのはいつなのか、３年後なのか、そこのスケジュールを教えていただきたいということが１点です。","respondent":"鈴木生活衛生課長","answer":"付則による経過措置の期間や今後のスケジュールですが、基本的には先ほどご説明したように、新型コロナウイルスの状況、それから都や各区の動向などを見ながらということなので、何年後などというように定めているわけではありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"すみません。食品衛生のところで伺いたいのですが、今、粗々の話を聞いて分かったのですけれども、これ今まで対象ではなかったところが対象に加わるということがあり得るのかどうなのか。これ別に、どうせ税金を払うときに控除されるから、会社で払うのはいいとして、どのような説明を区内事業者に伝えていくのですか、これ。先ほどの質問で、経過措置はずっと経過措置なのでしょう、今の回答だったら。","respondent":"鈴木生活衛生課長","answer":"更新期になると、必ず３か月から半年前に更新時期が参りますというお知らせを個別に出しております。そのときにも制度の変更についてはお知らせしますので、その中で具体的に相談や申請にいらっしゃったときに、詳しく説明をするということで考えております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後にします。すみません。もう要望ですけれども、品川区は商店街が強いではないですか。商店街などを中心に少しお手伝いいただいて、この周知をして、なるべく届出してくださいというようなことも併せて進めていただきたいと思います。よろしくお願いします。すみません、長時間。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"}]},{"id":"topic-02","title":"第３０号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第３０号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"そのために去年の議事録も見させていただいたのですけれども、去年の議事録でも、うちの鈴木ひろ子副委員長が、基礎資料がここ二、三年きちんと出てきていないと言っているではないですか。それで課長がきちんと出しますと約束なさっているではないですか。要するにせめて国保運協と同じ資料を出していただきたいのですけれども、出せない理由でもあるのでしょうか。どうして出されなかったのでしょうか。","respondent":"池田国保医療年金課長","answer":"次回は色刷りにしたものを提出するようなことで、気をつけていきたいと思います。資料については、昨年と比べまして、昨年より細かなものにするというお約束をさせていただいたところで、今年はその意見の回答と同じようなことで、内容自体は充実させていただいたところです。","voiceIndex":39,"id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"昨年の議事録まで調べたり何だりして、あるいは別の本を読んだりして、やっと分かったり、まだまだ私分かっていないから、とんちんかんな質問をするかもしれません、今日も。国保運協で出された資料、例えば私が勉強させてもらったのはこれですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"このような資料を出していただきたいわけです。分厚い資料を出せと言っているわけでもないのですから。税制改正のところですけれども、本当に初心者の質問で申し訳ないですが、控除が３３万円から４３万円に上がって、１０万円掛ける給与または年金所得者マイナス１という式が加わっていますけれども、これがなぜ加わったのか、もう１回きちんとご説明いただきたいのですが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"３３万円から４３万円というところは、給与所得者等の基礎控除の部分が３３万円から４３万円に今年の１月から上がってありますので、それに合わせて上げるという形になっているところです。","voiceIndex":43,"id":"exchange-012"},{"speaker":"おくの委員","kind":"質問","question":"この式でなぜ現行と同じになるのですか。現行と同じになるのなら、今の式のままでいいのではないですか。","respondent":"池田国保医療年金課長","answer":"あくまでも私どもの考え方としては、給与所得者が２人以上いる家庭については、変化のない場合でも軽減措置に該当しなくなることがありますので、基礎控除相当額の基礎額を４３万円に引き上げるということと。","voiceIndex":45,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"はい、分かりました。次へ行きます。次の質問。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"よく分かりませんけれども、次のことへ行きます。だから国保運協の資料をいただきたいのですけれども、このようにして計算されて、計算式が変わったので、７割減額、５割減額、２割減額の方は、この計算式で出した結果、加入世帯の何％になるのでしょうか。それをお願いいたします。","respondent":"池田国保医療年金課長","answer":"この計算で出した場合ですけれども、これはまだ私どもで計算のほうをしておりませんので、これでやった場合何人というのはお答えできないところです。","voiceIndex":49,"id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"では個々の数があるのなら、個々の世帯数を教えてください。","respondent":"池田国保医療年金課長","answer":"個々の世帯数ですけれども、７割減額世帯が１万５,４６９世帯、５割減額世帯が５,６０３世帯、２割減額世帯が４,６６３世帯、合計で２万５,７３５世帯という形になります。なお、加入世帯につきましては５万３,１９１世帯です。","voiceIndex":57,"id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"この資料を見ますと、２３区全体の賦課総額が出ていますけれども、品川区の賦課総額が幾らなのかということが第１点。それから、この賦課総額は昨年度と比べて増えているのか、減っているのかということをお聞きしたい。それから昨年度の賦課総額も教えていただきたい。それから、その賦課総額が均等割では幾ら、所得割では幾らということも教えていただきたいのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"賦課額ということではなくて、納付金額ということになるかと思うのですけれども、今日おつけしております資料の５ページ目、こちらが特別区の保険料算定上の数値ということになってございまして、納付金の総額ということで基礎分、それと後期高齢者支援分。","voiceIndex":59,"id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"所得割対均等割というのは６１対３９で変わっていないのですけれども、これ均等割が８００円下がって、所得割が上がっているのはなぜでしょうか。国保料が。これもお伺いしたいと思います。これは一体なぜ上がったのかというところ、昨年度はもうこのように上がることはないだろうというような答弁もいただいたりしているのですが、今年上がったのはどう考えているのかということをお伺いしたいと思います。","respondent":"池田国保医療年金課長","answer":"その後、実際に納付金として幾ら必要かというところで計算を始めるときに、まず品川区の被保険者数、それと品川区の来年度見込みの所得を見ましたところで、実際にその割合に置き換えますと、所得割については６１、均等割については３９というような形の割合になるということで。","voiceIndex":63,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これがついていないのです。これを私はぜひつけていただきたいと。本当に複雑なので、毎回どうだったかなと思いながら見ているのですけれども、そのように毎回見ていてもなかなか難しいのです。なので、運協でこれだけの資料を作っているわけですから、だって運協で１５ページ作っているのです。カラーで出していただきたい、運協の資料を丸々出していただきたい。いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"去年と全く同じ意見で申し訳ございません。資料のほうは、来年度またさらに精査して、きれいな形にします。余計なものはつけませんけれども、きれいな形でより見やすいものをおつけしたいと思います。","voiceIndex":66,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の賦課総額、賦課総額というのは保険料で賄う総額ですから、国保の加入者に対して全部でどれだけ負担してもらいますよというものが賦課総額なので、この額はぜひ出していただきたいと思うのです。その分も含めた額がこの額だというように考えればいいのでしょうか。だから、賦課総額というのはこれの９６％として考えればいいのか、その点を教えていただきたいと思います。その点をお願いします。","respondent":"池田国保医療年金課長","answer":"令和２年度につきましては、基本的に補正をかけて、予定では８億９,５００万円というような形を今見込んでいるところです。令和３年度の、当初予算としては、今その他の一般会計繰入金のほうについておよそ１０億円ということを見込んでいる、ご審議いただくところです。","voiceIndex":68,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"賦課総額というのは保険料で賄う、結局国保の加入者の保険料で賄うのが賦課総額だと思いますので、この賦課総額はぜひ来年度の資料には出していただきたいと要望させていただきたいと思います。７９億円は出すというように言ったのですから、そこのところを求めるべきではないかと思うのですけれども、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"国のほうで激変緩和措置額について１９億６,０００万円を出すというような形で、国のほうからお金が出るので東京都のほうからは繰入金を出さないということについて、私どものほうからそれについてどのようなことを要請しているかですけれども。","voiceIndex":70,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それなのにこのような形で、国の支援金も減っているし、東京都も出すと言っていたものを出さないということにもかかわらず、区長会として求めないという、そのような姿勢だと私は国保料の引下げということはできないのではないかと思うのですけれども、その辺のところは、課長会の中でなぜそのように。","respondent":"池田国保医療年金課長","answer":"今の子どもの保険料につきまして、こちらのほうはこれまでも子どもの均等割について軽減するようにということを２３区の区長会に要望させていただいているところですし、先ほどの副委員長の話にありましたような国に対する国保への要望。","voiceIndex":74,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後です。本当に区長会でもずっと求めていると。私たちもずっと子どもの均等割の無料化ということを求めてきましたけれども、ぜひ来年度未就学児半額などという、これだけ縮小したものではなく、全額無料だったり、対象も子どもということで１８歳以下というようなところで、区としてもぜひ強力に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-023"},{"speaker":"おくの委員","kind":"意見","question":"反対です。コロナ禍でこれだけ大変なときに、いろいろ法定外繰入れなどを入れて引き下げるべきところを、負担が増えるような値上げということでは反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-024"}]},{"id":"topic-03","title":"第１６号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"第１６号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この貸付けを受けて通っている方というのがどのぐらいいらっしゃるのかということをお教えください。そのときに、何というか、いろいろな事情があるので、私の想像を超えたりするようなものもあると思うのですけれども、そのときにどのようにして返しますかという、割と柔軟に対応できているのか、その辺のところを少しお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"この延滞金が発生している２名につきましては、基本的に、まずどういった返済で返していただくかということをご本人と区のほうで話合いをして、その方たちの返済能力に応じた返済計画をそれぞれ個別に立てているです。","voiceIndex":89,"id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"そのように話合いをして返済計画を立てるというような状態になってしまうような方というのは、継続的に出てくるものなのでしょうか。従来、これまでに。","respondent":"宮尾高齢者福祉課長","answer":"というのは、まずそもそもご本人が、この制度をご利用いただくに当たって、例えば将来、介護職になるとはっきりと、確たる目標がちょっとまだないというような方はとりあえず借りないという、そのような選択肢もありますので、そのような方はそもそもこの制度で借りないで。","voiceIndex":91,"id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"今現在は無理のない形で返済は進んでいる状態と見ていいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"そうですね。杓子定規にこのような返し方をしてくださいということは設定していません。繰り返しになりますが、その方ご自身の返済能力に応じて、返済計画を話合いの上で決めさせていただいているところです。","voiceIndex":94,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"確認","question":"本当にいい制度だなと思うのですけれども、一応確認です。条例の新旧対照表を見ると、前は「年５％」とはっきり明示がしてあった。今回は「３％」とは書かずに「法定利率」という形で書いてあるということで、今回民法では変動制が導入されたということで、今後は変動制が導入されて、変動した場合は、特にもう条例の変更も要らない、このようなことでよろしいのですか。","respondent":"宮尾高齢者福祉課長","answer":"今回の改正によって変動制が導入されることによって、その文言によりまして、民法が改正されたときはそれに従うというような形になりますので、これからは利率が変更になったごとに条例改正ということはなくなるというような手続きに今後なっていきます。","voiceIndex":97,"id":"exchange-028"}]},{"id":"topic-04","title":"これより、(2)第１７号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","agenda":"これより、(2)第１７号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ショートステイの方を減らして特養ホームの方を増やすということですけれども、そのご趣旨を教えていただければと思います。ショートステイを減らすことで不都合はないのか、特養ホームを増やすということで、何かその辺のご趣旨をお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"今回の条例の趣旨は、こちらの資料にも書かせていただきましたが、まずは区立特養の入所者の受入れを増やす、これが大前提としています。そのために、ショートステイの枠を一部特養ホームのほうに振替えるという対応を取らせていただきたいというふうに考えております。","voiceIndex":111,"id":"exchange-029"},{"speaker":"おくの委員","kind":"質問・要望","question":"区民の要望という点から、ショートステイの利用者、利用要望が減っていて、特養ホームの要望が増えているというように理解してよろしいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"特にそのようなご要望を受けてということではなく、ちょっと繰り返しになりますが、あくまでも特養ホームの受入れを増やす、そのためにショートステイの枠を一部有効活用すると、このような趣旨です。","voiceIndex":113,"id":"exchange-030"}]},{"id":"topic-05","title":"第１８号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第１８号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"これは簡単なことかもしれませんけれども、よく分からないので聞きます。１０万円ずれているのが３段階だけ、８・９・１０段階だけで７段階から下の人は１０万円ずれていないというところはなぜなのか、ご説明ください。それをお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"こういったことも併せ考えますと、今回これまでそういった減額の対象になってこなかった層について、こういった措置が取られたというようにも推測されます。","voiceIndex":127,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"なので、そのまま引いてしまうと所得が増えてしまうという形になるので、全ての人に対して１０万円を、ここでは規定しないで引くという計算の仕方をするということなのでしょうか。それで、それはずっとこの先そのような形で続く、少なくとも第８期は続くと考えればいいのでしょうか。その点お願いします。","respondent":"宮尾高齢者福祉課長","answer":"こちらの改正内容につきましては、現時点では特に時限的なということではなく、少なくとも第８期に関してはこのままの体制でいくというふうに見込んでいるところです。","voiceIndex":130,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"合計所得金額ということなので、給与所得控除や公的年金控除を引いたところの額が合計所得金額ということになりますよね。そうすると、基礎控除でプラス１０万円というようなことでの税制改正ですけれども、基礎控除の部分というのは、この介護保険料を計算するに当たり基礎控除が１０万円プラスになるということは関係してくるのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"それをなくすために、今回さらに１０万円を上げて、この税制改正で所得が１０万円アップするという事態を避けるために、今回この改正をする、このような趣旨です。","voiceIndex":132,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もう一つは基金ですけれども、私が一般質問でお伺いしたときに、今年度末の基金の想定額は１２億円、第八期の取崩し額が８億円で、そうすると第八期が終わった段階では残額４億円ということでの答弁だったと思うのですが、２０２０年度というのは、コロナでかなり介護保険の利用も下がったのではないかと思うのですけれども、その辺の品川区の介護保険の利用の状況というものはどうだったのか。","respondent":"宮尾高齢者福祉課長","answer":"コロナ関係の利用状況の変化に応じた対策というのも、様々国のほうで講じておりますし、区のほうでもそれに合わせた補正予算等を組んで対応させていただいているところです。こういったことが影響していると思われますので、今のところ特に大きな変化はないという状況です。","voiceIndex":134,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もう一つお聞きしたいのは、多段階化についてですけれども、品川区は１４段階で、これも当初から比べたらどんどん、６段階から始まったと思いますので、そこから比べたらだんだん上がって段階も増えてきたと思うのですが、品川区は１４段階で、合計所得２,０００万円以上で２.８倍というのが一番最高になっていますけれども、私も改めて他区の状況を見たときに。","respondent":"宮尾高齢者福祉課長","answer":"これはその区によって所得層の、住んでいらっしゃる住民の方の所得の状況というのも、２３区あればそれぞれの状況がありますので、だからといって、すなわちすぐに品川区がこれよりさらに多段階化に踏み切るという考えは、現在のところはございません。","voiceIndex":136,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ほかのところもこのような形で、かなり高額の方にはそれなりの応能負担ですね。そのようなところでは、その動きというのはどうなっているのか、私はぜひそのようなものを改めて求めていただきたいと思うのですけれども、そのような２３区課長会ですとか、区長会ですとか、そのような方向にはなっていないのか、その辺のところの動きについてもお聞かせいただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"国に対する要望ですが、直近ですと２３区の課長会では、特にそのような話題というのは、テーマというものは出ていなかったというように記憶をしております。ただ、全国の知事会などで、一部要求が出ているということは聞いたことがあります。","voiceIndex":138,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"これは随分前から、このような形で国に対して自治体のほうから求めて、全国知事会、区長会や市町村長会などでも出していたと思うのです。２５％、まずは全ての自治体に、品川区も２５％丸々出ていませんよね。ぜひ国の割合を、調整金を除いて２５％、プラス調整金というようなところで、課長会などでもぜひ要望していただきたいと求めておきたいと思います。もし何かあれば、お願いします。","respondent":"宮尾高齢者福祉課長","answer":"介護保険全体というか、制度の根幹に関わる部分でもありますので、その点に関しては引き続き国の動向等をしっかり注視して、健全な制度運営に努めてまいりたいと考えています。","voiceIndex":140,"id":"exchange-037"},{"speaker":"おくの委員","kind":"質問・要望","question":"具体的なイメージとしてどのようなものなのかも、ご一緒に教えてくださればありがたいと思います。それからもう一つ、今ご説明いただいたところを読んでいてよく分からなかったのが、４ページの一番下の4)栄養ケアマネジメントの充実で、栄養管理を計画的に行うことを求めるとなっていますけれども、これが一体どのようなことなのかも一緒に教えていただければありがたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらの２つの条例のそれぞれ対象とするサービスですが、第１９号議案の指定地域密着型サービスと申しますのは、例えば具体例を挙げますと、小規模多機能型居宅介護ですとか、あるいは認知症対応型の通所介護、こういったものがこちらの条例の対象になってきます。","voiceIndex":153,"id":"exchange-038"},{"speaker":"おくの委員","kind":"質問","question":"もう少し具体的に言うと、どのようなことなのかなと思ったのですけれども、それを具体的に教えていただければということです。それともう一つ、いわゆる特養ホーム、要するに３０人以上のものですけれども、それはどのような条例なり、法律なりで規律される、同じような改正があるのだと思うのですが、それはどのレベルの法律なり、条例で規律されているのかということをお教えください。","respondent":"宮尾高齢者福祉課長","answer":"それから３０人以上の特養につきましては、これは指定権限が都道府県のほうになってまいりますので、都道府県で同様の改正を行っていくものと推察されます。","voiceIndex":155,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"確認","question":"ＢＣＰというのはコンサルタント、普通の事業者は民間のコンサルタントなどを入れて、はっきり言えばピンキリの計画を立てる、それに実行性があるかどうかというのは、誰が確認をするのか、それはいつどの時点で確認をするのか、これについては、まずそのＢＣＰの部分が一番、きちんとこれは実行性のあるＢＣＰなのかということを誰が確認するのかということと、それとほかの６か月に１回開催するとか。","respondent":"宮尾高齢者福祉課長","answer":"ただ、そうはいいましても、恐らく日本全国どこでも同じような改正がされるということになりますので、恐らく国のほうからも、もっと具体的に、例えばこのようなモデルケースですとか、サービスのつくり方のモデルですとか、このようなやり方でどうぞ。","voiceIndex":157,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ひな形のようなものが示されてくるのかなと思うのですけれども、いずれにしても、よく民間の事業者のＢＣＰ策定については、やはり区でお金を出したりとか、助成金を出したりとかというぐらい、コンサルタントを入れて結構大変なことがいろいろある中で、定型的なものがこのような施設であればあるのかもしれませんけれども、つくったはいいけれども魂入れずのようなものだとあれだと思いますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"感染防止から、虐待の問題から、そのようなＢＣＰ計画から、新たに様々やっていかなければいけないというようなことになるわけですけれども、このようなものは今の段階ではまだどこもできていないということなのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"今回の改正を受けて、やはりこれから、一部先ほどの答弁と重複してしまいますが、国のほうからも、いろいろな方針に基づいた具体的な内容を盛り込んだ通知等がどんどん出てくると思われます。","voiceIndex":161,"id":"exchange-042"},{"speaker":"おくの委員","kind":"質問","question":"先ほどと同じような質問ですけれども、この指定介護予防支援事業者というのは、いわゆる要支援の方のケアプランを作る事業者の方のことでしょうか。そうであれば、区内に何か所あるかお教えください。","respondent":"宮尾高齢者福祉課長","answer":"第２１号議案のほうですね。指定介護予防支援につきましては、すなわち地域包括支援センターとなりますので、品川区の場合は高齢者福祉課および在宅介護支援センターということになります。","voiceIndex":181,"id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからもう一つは、前回、３年前ですか、これと似たようなものが議案にかかったことがありましたけれども、そのときにも私申し上げたのですが、品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例というのがありますよね。その点についてはいかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"２点目のお尋ねですが、これまで再三答弁をしていますけれども、品川区につきましては、指定自体は１か所で指定を取っているというところになりまして、その機能を２０か所の在宅介護支援センターに分散しています。","voiceIndex":184,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"だから、私は毎回これを指摘しているとおり、品川区自らがこのように条例で定めているわけですから。在支は指定介護予防支援事業者にはならないということなのですか。そこのところに１人以上の保健師を置かなければならないというように書いてあるのにもかかわらず、なぜ在支が予防のケアプランを作っているのに保健師を配置しないのか。なぜなのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"保健師の資格を持った職員は本課、高齢者福祉課のほうに複数名在籍しております。必要に応じて、その辺は有機的に連携を取りながら、日々介護保険制度の健全運営に向けて努力をしています。","voiceIndex":186,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、在支は指定介護予防支援事業者にはならないということなのですか。指定介護予防支援事業者としては、在支は登録されていないで、登録されているのは高齢者福祉課で、そこの機能になっているというような形のサブセンターということで、指定介護予防支援事業者としてはなっていない、地域包括支援センターにもなっていないということなのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"先ほどの繰り返しになりますが、品川区は高齢者福祉課と２０の在宅介護支援センターとして、それで１つの、１か所の指定、地域包括の事業者として１か所の指定を受けているものです。","voiceIndex":188,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"地域包括はそれで分かりました。今までもさんざんそのように説明を受けていますから、それも不正常だと私は思いますけれども、今回は指定介護予防支援事業者としても在支は登録されていないで、高齢者福祉課が登録されていて、その１か所で、そのサブセンターというような形になっているのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"繰り返しになりますが、高齢者福祉課と在宅介護支援センター２０か所、これで１か所としての指定を受けているです。","voiceIndex":190,"id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これはこのままずっといくつもりなのでしょうか。品川区、これの改善が必要だというようには考えないのでしょうか。１か所で品川区の全員分の介護予防のケアプランを組むという、そのことそのものが異常な状況ではないかと思うのですけれども、これはこのままずっと問題ないということでいくのでしょうか。品川区だけ。改めて伺います。","respondent":"宮尾高齢者福祉課長","answer":"繰り返しになりますが、品川区は高齢者福祉課のほうに保健師の職員を配置しています。２０の在宅介護支援センターがサブセンターとして有機的に連携を取りながら、日々介護予防支援を行っているところです。","voiceIndex":192,"id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点では、改めて保健師、社会福祉士、この配置をしっかりと、在支のところに配置していただきたいと、改めて申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-049"}]},{"id":"topic-06","title":"第２９号議案 指定管理者の指定","agenda":"第２９号議案 指定管理者の指定","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"ただ、出発点そのもの、なぜこの公募を行うのかというところで、非常に私としては納得がいかないのですが、まず確認したいのは、今回の指定管理者選定は現事業者に何か問題があったわけではない、ただ、建物全体の管理を含めた、総合的かつ一体的な施設全体の管理運営を行うことが必要だからという理由での公募だったと。その点の説明を求めます。これが第２点です。以上、質問します。","respondent":"築山障害者施策推進担当課長","answer":"１つ目のご質問ですが、今回の公募につきましては、建物管理を含む総合的・一体的な管理運営を行っていただくために実施したということが理由となっております。２つ目です。","voiceIndex":214,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問・要望","question":"誰も納得しないと私は思うのですけれども、それでは説明として成り立たないでしょうと思います。それから利用者の方のお声ですけれども、どこに反映されたのかと私は伺っているので、総合的に満足度として考慮しましたというだけでは、反映したかという私の質問に答えたことにはならないと思います。どこに反映されているのかと私はお伺いしたのであって、その点お答えいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"資料１で選考基準の方をつけしていますが、２点目の質問の回答にもなりますけれども、この中で利用者満足度ですとか、ご利用者のご意見等を踏まえて、満足度が高いということもある中での審査をしています。","voiceIndex":216,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうしないでくれという要望なのです。だから、それに対して現事業者ではなく別の事業者を選定することは、意思に反する、今の利用者の方の意思に反する、真正面から、１００％意思に反する決定を行っていることだと私は思うのです。ですから、その意思が反映されているのか、反映されていないのか、そのお気持ちが。ご要望が。そう思いますけれども、いかがでしょうか。お伺いいたします。","respondent":"築山障害者施策推進担当課長","answer":"ただし、選定につきましては、公募の趣旨と施設の設置目的から、指定管理者として最も優れている団体を総合的に判断して選定をしたです。","voiceIndex":218,"id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"今のお話を聞いていてなのですが、もし併せて伺えれば教えてほしいのですけれども、その利用者の方のご意見というのは当然大事なのですが、利用者のご意見というよりも、障害をお持ちの方々の意見というのを広く聞いて反映していただかなければならないと僕は思うのです。そういった場合、ほかの方の一般質問で、なかなか利用したくても利用できないという質問も、この間上がっていたのは事実です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-053"},{"speaker":"おくの委員","kind":"質問・要望","question":"全体のではなくて、今利用されている方から具体的な要望が出ているわけです。その方に対して、きちんと説明できるだけの公平さ、公正さを示さなければ、公平公正に判断したとは言えないのではないかということを私は申し上げているわけです。今のやり取りの中で私が聞いている限りは。だから、それでは説明になっていないのではないですかと私は思うのですけれども、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"事業者の選定に当たりましては、また同じ回答になりますけれども、別紙１の選考基準を定めまして、それぞれの委員に審査、選定をしていただきまして、総合的に判断したものです。","voiceIndex":226,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"提案","question":"今回の指定管理者の選定に当たりまして、私ども公明党は何度も全員で確認をしてまいりました。その上で幾つか確認させてください。というよりは、今利用されている方のお声、また、現指定管理者にもご意見を伺いました。この点について、最も優れた提案をされたのが福栄会だったということは理解しました。どのような評価をされたのか、これは私たちも利用者にお伝えする責任があるので、教えてください。","respondent":"築山障害者施策推進担当課長","answer":"ですので、冒頭にその基本的なスタンスとして、表明のような形で出されてしまいますと、やはり委員の人も不安に思ってしまうというところがあったというふうに認識しております。","voiceIndex":228,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"確認","question":"第４回定例会の一般質問の通告の直前でしたから、これはもう会派で緊急の会議を開いて、私も徹夜で原稿を書き直して、書き直してあのような感じになったのですけれども、書き直してもあのような感じだったのですが、一部差し替えをしたぐらいだったのですけれども、今回の本定例会のほかの議員の一般質問の中でのご答弁にもありましたとおり、報道の内容については、これは係争中ですから。","respondent":"築山障害者施策推進担当課長","answer":"運営事業者のほうの回答といたしまして、現場には影響ないという答えをいただいてはいたのですけれども、やはり審査、選定の中で、弁護士の先生や外部の有識者の方もいらっしゃって、ご意見もいただいたのですが、やはり係争を抱えている。","voiceIndex":230,"id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここからは先ほど伺った皆さんのご意見から、要望も含めて伺いたいと思うのですけれども、資料３ページの１０．選定理由のところに、今回福栄会が選定された理由の筆頭には、基本方針として「利用者を中心とした施設運営」を掲げている、実施しているということが書いてあります。そのような中で、利用者の求めるサービスイコール、利用している方ですね、ちょっと難しいですけれども、言葉遣いが。","respondent":"築山障害者施策推進担当課長","answer":"質の担保ですが、こちらにつきましては、審査、選定の中で福栄会のほうにも確認をさせていただきました。福栄会のほうも、現事業者が非常に頑張って取組まれていて、利用者満足度が高いということも十分に認識しておりました。","voiceIndex":232,"id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３問ぐらいなので、すみません。その中で、今回のお話の中に、今回の陳情にも入っているのですけれど、いわゆる団体の皆様のお声というもの、区はご答弁で、各種会議とか、いろいろなところでそのような声は聴いているということをおっしゃるのですが、今回の陳情でも代表的な団体、５団体ですか、その中でも多くの団体が要望を上げてこられている。","respondent":"築山障害者施策推進担当課長","answer":"区といたしましても、これまで障害福祉計画の策定等では団体ヒアリングやアンケート等を取りながら実施をしてきたのですけれども、確かにまだ意見を聴いていただいていないというお声があるというところも聞いておりますので、今後ご利用者。","voiceIndex":234,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員長、最後になります。今回この指定管理者が、現指定管理者が決まった２０１４年、２０１５年ですか、そのときに私もすごい大きな期待とともに、やはり不安もありました。元気のいい団体、言い方をよく言えば元気のいい団体ですし、そのとき質問しました。ですから、本当に「この子らを世の光に」と、この理念をぜひ今後品川区の障害者福祉に際して言っていただきたい。長くなりました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-059"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"本当に。実際に。それで改めて伺いたいのは、私の一般質問の中でも、選定に当たっては公正公平に審査を行い、応募のあった団体のうち、公募の趣旨と施設の設置目的から指定管理者として最も優れている団体を選定したというような答弁だったのです。私はその点数もしっかり公表することが必要なのではないかと思うのですけれども、いかがでしょうか。この外部委員の方の名前と肩書を教えてください。","respondent":"築山障害者施策推進担当課長","answer":"それから外部委員につきましては、名前の公表については現時点で特に行っておりませんけれども、人数につきましては、当初私が説明させていただいたときに、審査会、選定委員会で複数名を予定しているということでご回答させていただいたかと思います。","voiceIndex":238,"id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"外部委員の名前というのは、情報公開で取れば出てくると思いますし、それから前のときは初めから名前を言われて、この方が外部委員に入りますというようなことで、厚生委員会の中で報告があるのです。そのような点では、外部委員の名前を公表できないということはないと思いますので、ぜひそれはお答えいただきたいと思うのですけれども、いかがでしょうか。その点についてはいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"外部委員のお名前につきましてですが、こちらは先ほども言いましたけれども、特に現時点でお名前を公表するということは考えておりません。","voiceIndex":240,"id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"しかも外部委員も公表できないとは、なぜなのですかということなのです。だってこれ、私たちは今日ここで問われるわけですから。指定管理者を決定するのはこの議会で決定するわけですから、品川区が選んだものを議会で決定するのに、どう判断したらいいか分からない。何の情報もないので分からないではないですか。そのところでなぜ福栄会でいいのではないかと選ぶことができるのですか。","respondent":"築山障害者施策推進担当課長","answer":"今回もお名前を出すことによって、外部委員の方に迷惑をかけてしまうということも考えられますので、その点慎重にしたいと思っているところです。それから、公正公平な判断ですが、こちらも選定された事業者については、先ほどご説明したとおり、選定理由をお答えいたしました。","voiceIndex":242,"id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"例えば、質を重視したい、量を求められるけれども、質を大事に担保しながら量を増やしていきたい、そこのところは絶対譲れないということでやるというものなのか、そしてそのようなことであれば、区と事業者が対等な立場で協議をする中でクリアできていく部分というのが必ずあるのではないかと私は思うのですけれども、そして福祉というのは、そのように事業者、それから品川区、そして当事者。","respondent":"築山障害者施策推進担当課長","answer":"ただ、委員がおっしゃいますとおり、指定管理においては、指定管理者と区が協議をしながら、施設運営の在り方を考えながらサービスの向上を図っていくということは大事な視点でありますので、決して運営事業者と意見が合わないから、それが駄目だと言っているわけではなくて。","voiceIndex":244,"id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だって本当に障害者福祉を前進させたい、よりよい質を求めたい、本当に当事者のために頑張っていきたいというようなところでお互いにやっているわけですから、そのような点では、そこのところをどこがどうなのかという辺りを率直に話し合っていく、対等な立場で話し合っていく、そのようなことで詰めていくという姿勢が、区のほうにも必要だし、事業者のほうにも必要だし。","respondent":"築山障害者施策推進担当課長","answer":"指定管理者と区が協議を行いながら施設運営を行っていくことは、大事なことだと考えております。それから、今回の報道に関することにつきましては、これは影響はかなりございました。","voiceIndex":246,"id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"現場でどれだけ一生懸命やっても、そのようにトップの人がハラスメントを起こしたというようなことが理由で選定から外されると、そのようなことも影響を与えたという、そのような意味で確認されるでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"今回の訴訟の中身に関しましては、区のほうで何かコメントできる立場にはありませんので、ハラスメントがあった、なかったということではなく、共同事業体の中で訴えている、訴えられているというような関係性がある中で。","voiceIndex":248,"id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"このような形で品川区が現事業者ではないところを、福栄会を選ぶという形になったわけですけれども、これから指定管理者が品川区の福栄会という形で、もしも議会で選ばれたとしたら、１年半くらいあるわけです。その中でどのようにこの事業者のことに対して、この選定に対して、当事者や団体の皆さんに説明をしていくのか、その点について伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"利用者に対しましてはなるべく早い段階でお知らせをしまして、説明会、個別相談等でお一人お一人、ご利用者の心身の状態や家庭の事情、ご利用者の意向を踏まえながら、丁寧に対応していく考えです。","voiceIndex":250,"id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一言だけ言わせてください。先ほどのもう１回確認です。サービスの質の担保をしていただきたいということ、向上していただきたいということ、それと利用者との定期的な意見聴取の場を構築してほしいということ、やはり利用者中心のサービスをこれからもさらに向上していってほしいということ、これをお願いして賛成をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"今まで１４年ですか、１５年ですか、議員をやらせていただいて、この議員としての仕事で指定管理者の指定というものがあるのだけれども、初めてですか、委員会で細かい理由まで踏み込むような説明をいただいて決めなければいけなくなったと。２０１５年から。その場にいたわけではないから、どのような言い方をされたのかも分からないのだけれども、ちょっと考え方の乖離があったのでしょうか。震えが来ます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-068"},{"speaker":"おくの委員","kind":"質問・要望","question":"利用者の方々の継続を求める声、やはりそれを無視して決めたと言わざるを得ないと私は思います。利用者の声をしっかりと聴くべきだったと思います。事業者の選定自体に反対です。指定管理者の選定自体に反対です。議案に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-069"}]},{"id":"topic-07","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"令和２年陳情第５９号と令和３年陳情第４号、第９号に関しては、先ほど、委員会での結果が出ましたので、もう態度的にも私たちは決まっているのですが、令和３年陳情第１号の協定締結、今説明にもあったのですが、このようなものというのは、そもそも指定管理やほかの高齢者施設にしてもそうなのですが、各々に対して細かい協定というのは普通締結するものなのですか。","respondent":"築山障害者施策推進担当課長","answer":"現在の指定管理者との契約につきましては、全施設個別に協定の方を結んでいるところです。","voiceIndex":266,"id":"exchange-070"},{"speaker":"渡部委員","kind":"確認","question":"その確認だけなので、どのようなものなのかと思って。すみませんでした。いいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点確認をさせてください。今のところが悪いというわけではないけれども増やしてほしい、このお気持ちはすごく切実なものがあって、そこについて、今回のことで「あつものに懲りて」ではないですけれども、今回もいろいろなことがありましたが、そこはぜひ前向きに、積極的に捉えていただきたいなと思うのですけれども、この２点お伺いしたいと思います。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"区といたしましても、やはり運営法人、それから今働いている職員の皆様を尊重しながら、丁寧な対応が必要だと考えていますので、こちらにつきましては現運営法人、次期指定管理者とまずは話をさせていただき。今後もその他のサービス、あるいは施設等につきましても、積極的に充実を図ってまいりたいと考えております。","voiceIndex":270,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう終わりにします。特に全体の部分については区も中に入って、先ほども入っていただけるというお話があったと思いますけれども、ここは積極的にコーディネートをお願いしたいと思っています。これは要望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"事業所を。選んでグローというようなことになっていると思うのですけれども、そのグローがあそこの総合支援施設でなくなってしまうというようなことになった場合、例えばグローが別の場所で、あそこの総合支援施設から出て別の場所で引き継いで、あそこに入るまでは別の場所でやっていたではないですか。品川区がこれからも指定特定相談支援事業所を公募する場合、グローが応募することはできるのでしょうか。","respondent":"松山障害者福祉課長","answer":"今回は、相談支援事業所の今後の見通しということでのご質問だと思うのですが、今後につきまして、在宅介護支援センターの併設型につきましては、来年度２か所ということで増設をする予定です。","voiceIndex":275,"id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなところで、もし公募が行われた場合に、ゆうゆうに応募してやっていただきたいという、多分多くの方が思っている部分というのもあると思うのですけれども、そのような可能性というのはあるのでしょうか。その点についてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"現事業者がこれからも事業を継続される、あるいは２点目の公募に応募するといったようなことにつきましては、現事業者の意向もありますし、公募ですから、どなたでも全国的に広く募るです。","voiceIndex":277,"id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。新しい指定管理者の下、引き継ぎが無事遂行するように見届けていただきたいということと、場合によっては区からもサポートをしていただきたいと思います。利用者の皆さんに改めて期待を持って安心していただけるように施設運営をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すということで、不採択です。一言添えると、先ほども申し上げましたが、前段の指定管理者としての方向性は、まだ本会議の議決は出ていませんけれども、方向性が見えた段階ですので、現在より減らすことがないということに関しては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":286,"id":"exchange-077"},{"speaker":"渡部委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。もう先ほど決定しているとおりですので、また別の機会に要望等もさせていただければと思います。今回は不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-078"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。継続への要望は本当に熱意あるもので、大事にしなければいけないと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":288,"id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけ言うと、先ほどご説明がありましたけれども、引継ぎを丁寧にしていくという、先ほどの議案のときに、選定された新たな法人がおっしゃっているということですので、その点をきちんと法人にお願いするとともに、区として、指導というと言い方が上からになってしまいますけれども、ぜひ協力して一緒に一体となって施設の運営を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":289,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出す、不採択です。一言添えます。先ほども渡部委員等との質疑がありましたけれども、協定締結というのはそもそも全ての事業者とやっているとのことですので、重ねてここでまた、こちらで議決をする必要はないのかなというところです。お気持ちはよく分かります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":294,"id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"昨年の１１月９日、この陳情の中にある施設整備を区に求める陳情が出されて、このときに基準はこの施設、満たしているのですけれども、安全対策をより高くということで採択を主張しました。しかし、今回のこの陳情は選定事業者との間で協定締結を求めるもので、ご存じのとおり、共産党は現事業者を継続すべきで、選定すべきではないということを表明したばかりですから、この陳情には不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-082"},{"speaker":"あくつ委員","kind":"質問","question":"本日結論を出すで、不採択です。一言添えます。それとグローと愛成会は大きな法人ですが、ゆうゆうは小さな法人です。現地採用もかなりされていると伺っています。そこについては、利用者を第一に考えていただくこと、やはりそういったことも考慮に入れていただいて、区が、やはり第三者が間に入っていただいて、利用者にとって不利益のない引継ぎをぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-083"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。最後にこの施設の件で様々なお話をずっとさせていただいた中で、やはりもう細かい話というよりも、引継ぎの部分と、区内の障害をお持ちの方々が利用しやすい施設にということで、併せて申し述べさせていただいて終わりにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":311,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":79518,"voices":318}},{"id":"r03-20210222-8","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"建設委員会","time":"午前１０時００分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を107件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第２４号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第２４号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"田中委員","kind":"意見","question":"今はまだ２つのお部屋に入居されているということなのですけれども、その入居者の方たちに対して、これからいつまでに出ていってというか、退室をお願いするとか、そのようなことはないのかどうか、その辺の説明もお願いいたします。","respondent":"森住宅課長","answer":"今、２世帯の方が住まわれておりますけれども、今後ともお住まいになっていただくことは可能です。ですので、これから退去を促すとか、そういうことはございません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて副委員長","kind":"質問","question":"今回の条例は、段階的になくされてきた家賃助成の規定を削除するものになっています。そこで伺いたいのですけれども、フラット型助成をしてきた３棟のファミーユ下神明、ファミーユ西五反田の東館と西館の入居率、助成があったときと、なくなった現在の入居率を伺います。","respondent":"森住宅課長","answer":"ファミーユ西五反田・西館につきましては８６.８％だったところが８３.７％、東館は９５.８％だったところが９４.８％になってあります。","voiceIndex":10,"id":"exchange-002"},{"speaker":"のだて副委員長","kind":"質問","question":"以前の答弁でも、区も全国的にそういう傾向があるということもおっしゃっていますので、やはり家賃助成をしていくことが区民住宅として重要だと思いますので、復活こそすべきだと考えますけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"実際、２年前に比べて下がっているところは事実ですけれども、例えば平成３０年度にあり方検討をしたときの周りの不動産相場と比べたときに、まだファミーユ下神明、ファミーユ西五反田・東館、西館とも、ほかの民間賃貸住宅と比べて大分低い状況ではあります。","voiceIndex":12,"id":"exchange-003"},{"speaker":"のだて副委員長","kind":"質問","question":"国の制度は終了したということですけれども、区独自に助成をしていくことは可能だというふうに思いますので、そういったことこそやっていくべきだというふうに思います。申し込んでもなかなか入れないという状況が続いていますけれども、直近の区営住宅の募集戸数と申込数、募集倍率を伺います。","respondent":"森住宅課長","answer":"区営住宅の倍率について、直近、令和２年度につきましては、１１戸の募集をいたしまして、倍率としては６０倍という形になってあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"のだて副委員長","kind":"質問","question":"６０倍ということで、とても高い倍率になっています。やはりこうした区の住宅政策としては、区民住宅をほかの用途に転用するのではなくて、高倍率になっている区営住宅へ転用すべきではないかと考えますが、いかがでしょうか。","respondent":"森住宅課長","answer":"区営住宅への転用というお話です。区といたしましては、民間賃貸住宅の供給が充足していることから、倍率としては高い状況は続いておりますけれども、民間賃貸住宅への入居を居住支援協議会などを通じて勧めていきたいというふうに考えてあります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"民間住宅があるということですけれども、やはり区営住宅に入りたいという方も６０倍いるわけですから、やはり区としても低所得の方たちにもよい住宅を提供していくということが必要だと思います。やはり区営住宅を増設することを強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"子ども・若者支援機能のところで、お答えできる範囲で構わないのですが、１階から４階までの８戸を利用できるということなのですけれども、「フリースペース、学習支援等の場として活用」の「等」に当たるものは何なのかというところと、あと、今、中延にあるフリースペースがこちらに移るということなのですけれども、その中延を利用されていた方たちへの周知がどのようになっているのかといったところや。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認をいたします。先ほどの東日本大震災の被災者の住宅、ほかのところを合わせると１８戸使用されていたということなのですけれども、今、退去されたということで、どういう理由で退去されたのでしょうか。避難解除がなされたので、帰ることになったのか。それから、居室ですけれども、介護人材用住居の中に、この入居者２戸が入っているという理解でよろしいですか。","respondent":"森住宅課長","answer":"そういった中で、区として様々な活用を検討した中で、各所管課が実際に動けるというところで区の内部決定をとりまして、今回のご提案につながったという形です。","voiceIndex":24,"id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"被災者については分かりました。心配していたのは、もう期限が切れたから出ていってくださいと言われたら嫌だなという思いがあったので、それはないとは思っていましたけれども、ちょっと確認をさせていただきました。例えば、シェアハウス。ですので、これ、中身を相当改造しないと使えないのだろうなと。どういうことをイメージされてシェアハウスと言ってきたのかと、知る限りでいいので教えてください。","respondent":"森住宅課長","answer":"シェアハウスについてですけれども、３ＤＫの部屋に２人入居を予定しております。こちらにつきましては、今は住居という建築の用途になってありますけれども、シェアハウスになると寄宿舎という用途になります。","voiceIndex":26,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"基本的には賛成ですが、１つだけ要望だけしておきます。空き部屋の活用は、これからはいろいろなところもあると思いますが、ぜひそれは積極的に考えていただきたいと考えています。それから、入居者の方が２世帯いらっしゃる、２部屋にいらっしゃるということなので、外国人の職員の方のシェアハウスということなので、そこら辺は配慮をぜひしていただきたい。それだけお願いをしておきます。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"要望で、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"賛成をします。賛成はしますけれども、シェアハウスのところで、やっぱり介護人材の方は比較的皆さん、お若い方が多い。さらに、言語とか文化の違いでいろいろな問題とは言わないのですけれども、後々、いろいろなことが起きてくると思いますので、そこのところは近隣と、あと住民たちの中のうまく意思疎通あるいは交通整理がきちんとできるような対応を徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"},{"speaker":"のだて副委員長","kind":"意見","question":"今回の区民住宅の家賃助成は続けてほしいという声が上がる中で廃止されて、今回の条例改正で完全に家賃助成の規定をなくすものです。ただでさえ弱い区の住宅政策を、区民住宅を廃止してさらに後退させるのではなく、例えば募集倍率が６０倍にもなっている区営住宅への転用や、若者世帯へ家賃助成を行う住宅への転用など、住宅政策の拡充に活用すべきです。したがって、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"今ほどもいろいろご意見が出ましたけれども、外国の方もいらっしゃる、それから転住の方もいらっしゃる、若い方の出入りが多いということでは、いろいろな方が出入りしてしまう、居住空間の中にいろいろ出入りがあるということは、それだけのセキュリティの問題も出てくることがありますので、それをやはり関連する部署の方々としっかり協議をして、問題がないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-02","title":"令和３年陳情第８号、戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の住民説明会とパブリックコメント実施を求める陳情","agenda":"令和３年陳情第８号、戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の住民説明会とパブリックコメント実施を求める陳情","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"この陳情を求めることはごもっともだなということを思っていて、区としても、戸越公園駅周辺のまちづくりがこれから変わっていくことについて、地域住民をはじめとした区民の方には理解をしていただいた上で進めていきたいことだと思うのです。品川区では、この公聴会等によるものとして、この説明会の実施なのか、そこら辺を確認させていただきたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"この中で「都市計画の案を策定しようとする場合において必要があると認めるときは、公聴会の開催等住民の意見を反映」と記載があります。品川区におきましては、公聴会の代わりに、今、説明会を実施して都市計画事業を進めてあります。","voiceIndex":42,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"その公聴会と説明会だと、やはり全然違うではないですか。説明会の実施もいいのですけれども、公聴会の機能を失わないように行ってほしいと思うのです。ですので、今、区として行っている公聴会に代わる説明会について、今回の戸越公園駅周辺まちづくりビジョン駅前広場計画編でも、やはり意見聴取をどうするかというところは検討が必要なのかなと思うのですが、伺います。","respondent":"鈴木都市計画課長","answer":"そうした意味では、基本的には名前は説明会というふうになっておりますが、意見をいただいてお答えをする、その場に来ていただいてご発言いただく方も手を挙げてご発言いただくという。","voiceIndex":44,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"地域限定に特化して説明をしていきたいといった、前回の（委員会での）報告のときにそういったご説明があったのですけれども、そうではなくて、やはり今のご説明にあったとおり、区民の方たちが参加できる形での説明会の実施というのを求めますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"駅前広場は都市計画事業として進めていきますので、今、お話のございました都市計画法第１６条または第１７条という段階で地域への説明会は開催していきます。","voiceIndex":46,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"今のご答弁だと、素案の段階での説明会は実施しないということですか。それを素案の段階で、地域住民を含め、区民全体、住民の方たちへの説明会を実施してほしい、そしてパブリックコメントも実施してほしいというのが今回の陳情ですので、そこのところのご答弁をいただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"駅前広場計画編をまとめるに際しても、この２年間で、会合やホームページ、回覧等、いろいろ地域の意見を聞いてあります。延べ回数にして２０回程度やっているというところで、地域の意見は聞いてきて積み重ねているという認識です。","voiceIndex":48,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、もともとの基本計画編から駅前広場計画編にしたもっと狭めた範囲の計画編だから、初めの基本計画のときにパブリックコメント等を行っているので実施しないというのは、ちょっと違うのではないのかと思います。ですので、区としても、地域の方たちをはじめ区民の方たちに納得していただいて事業を進めることが求められると思うので、ぜひ実施をしていただきたいと求めますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画事業の素案としての説明会は実施してまいります。今回の駅前広場計画編は、駅前広場の限定した、また内容もここで何か物事がすべて決まるような内容ではなく、一定程度、駅前広場とはどういったものかといったことを示しているものです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"田中委員","kind":"確認","question":"ごめんなさい、私も詳しくないのでちょっとお伺いしたいのですけれども。今、事務事業概要にある「品川区都市計画審議会に付議」という、ここの部分を差しているのか。その前の段階の「意見書の提出」、「案の公告及び縦覧」、ここの時点と、区として案を出しているときに、区民が意見を反映できる場、区に対して意見を言えるときというのがどこに当たるのか、確認させていただいてもよろしいですか。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画事業が進みましたら、まず都市計画事業の素案といたしまして、（都市計画法の）第１６条の公聴会に代わる説明会を実施いたします。第１７条のときには、都市計画法のほうには「説明会等」という記載はございませんが、そこでまた再度説明会をいたします。","voiceIndex":52,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、私の理解が悪いのか、策定した内容を今後ホームページ等で周知していくということだったのですけれども、策定する段階の素案の段階での周知といった部分をどのように考えているのかということと、今回の陳情では、素案の住民説明会とパブリックコメントの実施を求めていますので、策定されてからのことではなくて、今の素案のときにどうするのかというのを伺いたいというのが１点と、あと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"ですので、この陳情は、区が定める都市計画の決定手続きの「公聴会等による住民意見反映」をもっとしてほしいといった話ではないですか。","respondent":"中道まちづくり立体化担当課長","answer":"はそれらの意見を今回の駅前広場計画編の中でまとめまして、繰り返しになりますが、広報しながわやホームページにアップして、その際に地域の方たち、また区民全体に意見を聞いていきたいというふうに考えてあります。","voiceIndex":57,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"区にとっての公聴会等というものが説明会に当たるといったご説明は先ほどあったのですけれども、今より、より住民の方たちへの意見を聞く場を設けてほしいというのは強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"地域の方たちというのが、町会長や協議会の方々、商店街ということでした。その２年の間、回覧等々でお知らせをしてきたということなのですけれども、やはりまだ地域住民の方たちの中からも、計画のことは全然知らなかったといった声が聞かれてきます。ですので、ぜひ説明会、公聴会、そして周知をお願いしたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"今の議論を聞いていると、駅前広場計画編の説明は、素案の段階でホームページ上でも（説明）しますということでしょうか。多分段階が不明瞭なのだろうと思うのです。だから、そうとられないようなことを、いや、実はやっているのですということなのか、そこをはっきり示していただいたほうが分かりやすいのではないかと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"ですが、今までの積み重ねといいますか、基本計画編からこの２年間は、先ほどの繰り返しになりますけれども、２０回以上いろいろ意見交換をしてきた中で進めていることですので、ここで区民の方の意見は区としてもいただいているといった認識ですので。","voiceIndex":64,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"気になるのが、この（陳情の）理由の中に、４行目ですか、「実施されない予定と聞きました」ということを書かれてしまって、理由の中に挙げられているのですけれども、だから、区としてはこういう方法を使って意見はいただいていますということを言えるわけではないですか。１つの方法ではありますが、これをしたからといって住民の気持ちが全部網羅できているとは思えないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"のだて副委員長","kind":"質問","question":"住民説明会はパブリックコメントとセットで実施すると、より効果があるのかなと思います。やはり計画ですと、急に出されて、すぐに意見を言えないという人が多いと思いますので、こういう計画ですと説明して住民の意見を聞くようにすれば、いろいろな方が意見を出しやすくなりますし、聞きやすいというふうに思いますけれども、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"そうした中で案件ごとに、個々に対象となるかどうかといった判断でパブリックコメントを実施しています。パブリックコメントを行う際に説明会をですが、それはまた案件ごとに検討していくものですので、その場面、場面で違うのかというふうに考えてあります。","voiceIndex":68,"id":"exchange-027"},{"speaker":"のだて副委員長","kind":"質問","question":"私が伺ったのは、パブリックコメントという方法が、区民が区政に参加する、意見を出す、よい機会だと、よい手法だということで陳情にも書いてあるので、そこのところを区がどのように考えているのかということで伺いましたので、そこをお答えいただければと思います。","respondent":"中道まちづくり立体化担当課長","answer":"その対象となる案件については、先ほどご説明したとおりですので、区全域に関わるのか、または限定的ものなのか、そういった形でパブリックコメントをするしない、すべきかどうかといった判断があるというふうに考えてあります。","voiceIndex":70,"id":"exchange-028"},{"speaker":"のだて副委員長","kind":"質問","question":"こういった陳情が出てきているということは、知らない方がいらっしゃるということで、まちづくりというのは、やはり住民合意で進めていくべきものだというふうに思いますので、それを知った中で、先ほどいろいろな手法があるという話もありましたけれども、知らない人がいないという形で進めていく、合意を図っていくということがまちづくりの前提だというふうに思いますけれども、区はいかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"今回、駅前広場を進めるにあたって、また、先ほどの繰り返しになりますけれども、やはり駅前広場計画編の中にどのような形で地域の方たちが携われるのかといったことは、１ページ設けて、そこに丁寧に説明していきたいというふうに考えてあります。","voiceIndex":72,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今の質疑の中で、パブリックコメントの対象になる事案についての説明がありました。この陳情にも書かれていますが、様々対象になる事案の説明があります。それで、今回、この素案がその対象にならなかった理由をお知らせいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"パブリックコメントですが、区民全体に意見を聞くものというところで、今回、戸越公園駅周辺まちづくりですが、基本計画編のときにパブリックコメントを実施しています。","voiceIndex":75,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"その基本計画編のときにやっているし、また今回の場合は、限った場所での素案ということになるのでパブリックコメントは行わないということだったのですけれども、やはり先ほどから何度も言っているのですが、事務事業概要に書かれている「原案の作成」からの流れからしても、やはり「公聴会等による住民意見反映」の場は確保されるべきだと思うので、ぜひそういったことをもっと率先して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確認だけさせてください。そこの中で基本計画編のときの素案で、今、パブリックコメントできちんと区民の方から４２５件ご意見をいただいて、そういうことを踏まえた中で、それで、そのときにも、この駅前広場のご意見もあったのだと思う。そこら辺を明確にしていただきたいというところだけ確認をしたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"品川区で行いますまちづくりですが、まちづくりを進めていく上で、住民の方たちの意見というのはしっかり聞いて行ってきてあります。今回、駅前広場計画編を作るにあたっても、基本計画編からの流れで住民の方の意見は聞いて作ってきているです。","voiceIndex":79,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、１つ確認し忘れていたのでお伺いします。","respondent":"中道まちづくり立体化担当課長","answer":"駅前広場についてのパブリックコメントの数ですが、３６件の意見をいただいてあります。","voiceIndex":82,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"ありがとうございました。ですので、ぜひ今から説明会等の実施をしていくこと、区民の方たちがこの計画を知るような機会を設けていただきたいと強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問","question":"陳情の趣旨の中で「実施してください」とありますが、これ、主体はどこなのか、教えてください。","respondent":"中道まちづくり立体化担当課長","answer":"実施は区です。","voiceIndex":88,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"陳情ですから、陳情者の考えと、その対応について書いてあるわけですけれども、ここのところで「実施してください」と、陳情ですから議会に来ているわけなのですけれども、議会がパブリックコメントを実施してくださいというような陳情の趣旨で書いてありますけれども、議会でそれは可能なのですか。","respondent":"中道まちづくり立体化担当課長","answer":"パブリックコメントの実施は区のほうで行ってありますので、議会等で行うことはできないというふうな認識です。","voiceIndex":90,"id":"exchange-036"},{"speaker":"大沢委員","kind":"質問・要望","question":"この４段目には、「区に求めてください」と書いてある。これ、求めることは議会は仕事としてはできますけれども、陳情の趣旨の中で、理由もそうですけれども、主立って陳情の趣旨について審議すると、私は陳情審査の場合には考えておりますので、パブリックコメントを実施するということは議会ではできないということでいいわけですね。すみません、もう１回、答弁を。","respondent":"中道まちづくり立体化担当課長","answer":"議会でパブリックコメントを実施することはできません。","voiceIndex":92,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を出してください。不採択でお願いします。先ほど来、これまで基本計画編も含めて、素案も含めて、品川区が今まで進めてきているのは、区民の多くの方から意見を聞いてまちづくりを進めているというふうに私も理解をしていますし、こういうやり方で私は結構だと思いますし、都市計画事業でも、またしっかり意見を聞いていく場もあると考えていますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-038"},{"speaker":"若林委員","kind":"質問","question":"結論を出すで、不採択でお願いします。説明が十分になされるということは目指しますけれども、あくまでもそこは目指しますけれども、こういったお声もあるというところで、これまでどおりというか、これまで以上に一般住民、区民に対してご説明を継続していただければいいかなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"本日結論を出して、不採択でお願いします。議会の中でも、今、各委員がお話をさせていただいたように、住民意思を汲み取るべき手続き、あるいは公募の仕方なども様々な工夫を凝らしながら取り扱っていただいているということで、既にやっていることですので、この陳情についてはその必要はないと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-040"},{"speaker":"のだて副委員長","kind":"意見","question":"結論を出すということで、採択を主張します。まちづくりの基本は、住民合意で実施するということが重要です。そうした中で、まちづくりというのはやはり多くの住民に影響を及ぼすものですので、パブリックコメントや住民説明会などを行って、できるだけ多くの方に知ってもらい、意見を聞き、合意形成を図っていくということが大切だというふうに思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"結論を出すで、採択を求めたいと思います。この戸越公園駅周辺まちづくりビジョン駅前広場計画編以外にも、品川区内ではやはりこういった住民説明会やパブリックコメント、意見聴取の場を求める声が多数上がっていますので、ぜひ区としてきちんと都市計画の決定手続きをもう一度きちんと考えていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、不採択をお願いします。ただ、それが皆に知られているかというと、そうではないと、知らなかったという部分もあるかと思うので、それは十分に周知していただきたいということ。そういう意味でいうと、ホームページ上でもこういう意見聴取をして、こうなっていますみたいな説明は、できる限りしていただければ、ご理解も深まるかと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-043"}]},{"id":"topic-03","title":"コミュニティバス導入に向けた検討状況","agenda":"コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今後、この３ルートで実証実験が行われるということですか。３ルートではなかったですか。求めたいのは、バスルートを利用者が少なかったからすぐやめてしまうとか、そういったことではなく対応してほしいということを要望したいのですけれども、その辺に対していかがでしょうか。ですので、ルートをとにかく柔軟にしてほしいということを思うのですけれども、そこのところのご意見をいただけたらと思います。","respondent":"鈴木都市計画課長","answer":"当然ながら、近傍で寄れる、あるいは寄る必要のある公共施設については、しっかり検討の中にも入れておりますが、今進めようとしているルートについては、資料でお示ししている３案で考えていきたい、その中で大井ルートでまず試行運行を行っていきたいというものです。","voiceIndex":108,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"計算式を教えてほしいのですけれども、（別紙２の）８ページの中で、まず１つは、想定乗車人数というのが、この数値はどういうふうな数値なのでしょうかというのが１つと、それから、先ほどの９ページで、判断基準の中で、収支率５０％以上となると、荏原ルートの試算だと２２０円で８８％、大井ルートは５９.６％なので、もう既に赤字。","respondent":"鈴木都市計画課長","answer":"やはり地域ごとで、最終的にはバス事業者の方もやってみないと分からないというところが、我々もいろいろ検討している中では、そういう印象を持ってあります。","voiceIndex":113,"id":"exchange-045"},{"speaker":"西本委員","kind":"確認","question":"具体的に試行して５０％以上というのが判断基準だということも分かりました。交通上の問題、それから、現実的にバス会社の立場として、かなり無理があるという、かなり無理があるのにプロポーザルをやっても、手を挙げる方がいらっしゃらなかったら、この計画案がなくなってしまうので、そこら辺の見立てとかというのは、ある程度あるのでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした中で、最終的には、しっかり手を挙げていただけるような明解で分かりやすい仕様書にして、ご検討いただけるような仕様書作りを、今まさにやっているところですが、区としましては、手を挙げていただけるというところで、今、一生懸命やっているところです。","voiceIndex":115,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"交通の状況をどういうふうに考えているかという、大森駅とかは本当に気をつけていただきたくて、そこの対策をきっちりされている方であれば、多分プラスアルファのお金が要求されるだろうし、逆に言うと、区のほうもそれだけの余裕を持った形での予算立て、随意契約になるのか、どういう契約になるか分かりませんけれども。","respondent":"鈴木都市計画課長","answer":"当然ながら、警察との協議の中で、事業者のほうでの交通誘導員の提案も考えられますが、事業認可を取っていく中での警察との協議の中で、ここはしっかり交通の安全対策をとる必要があるというご指摘、指導もいただくでしょうから、そうした中で総合的にそれを。","voiceIndex":117,"id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"最後に、事業認可が下りないということはないですよね。警察の方も（地域公共交通会議に）いらっしゃっているので、ある程度、見立てを立てながら計画されていると思うのですが、まさか警察のほうで調べてもらったら、ここが駄目などというようなことはないですよね。そこだけ確認します。","respondent":"鈴木都市計画課長","answer":"ワークショップの中でも非常に声として大きいということで、今回、この最終的な修正したルート案でいきたいですが、警察との協議は行っておりますが、最終的に警察としても、これでＯＫですというところは、事業認可前に、あるいは手続きを進めていく中で正式な回答というのは。","voiceIndex":119,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"この大井ルートの中での赤い線になったところ、これは要望があるのは分かります。小型バスですから、大型バスではないので、可能なことは可能なのでしょうけれども、非常に危険が伴う。法令がどうのこうの以前に、それも必要なのですけれども、やっぱり安全性を第一に考えたルート、下手をすると、あまり危険性が高いと、元のルート案に変わる可能性もあるわけです。それは仕方がない。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"利用者の声を聞いたりとか、バス停を設置される地域の方の声とかも、この評価に入るのかといったところをお知らせいただきたいのと、もしこの大井ルートがうまくいって、次のルートも試行運行を始めてみようといったときには、荏原ルートが先になるのか、大崎ルートが先になるのか、それとも同時に始めてしまうのかなどといったスケジュール感もお知らせいただきたいのと。","respondent":"鈴木都市計画課長","answer":"評価にあたっては、当然ながら、指標としては収支率５０％という区民の方にも分かりやすい指標でお示ししていますが、そのほか、当然ながら、利用についてのアンケートをとったり、利用者の声をお聞きするということも考えられますし、それから。","voiceIndex":123,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"荏原ルートと大崎ルートに関しては、２０２５年度のときに判断、どうなるかといったことが報告されるということでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的にはそのような形で考えておりますが、ただ、例えばコロナ禍が収束し経済が好転するとか、それは状況によって、大井ルートの試行結果が非常に好スタートを切って。","voiceIndex":125,"id":"exchange-051"},{"speaker":"のだて副委員長","kind":"質問","question":"大井ルートが原踏切のほうを通るルートになっておりますけれども、交番の横のガードのほうを通ってほしいという声もありまして、ここのガードのところは通れないのかどうか。今、東急のバスですか、通っていますので、コミュニティバスも通れるのではないかというふうに思っているのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"利用率についてですが、先ほど、私の説明がちょっと不足していて申し訳ございません。基本的に他区でコミュニティバスを実施している区が利用率を公表しているということはございません。","voiceIndex":128,"id":"exchange-052"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"利用率のところは、そうすると、何％というのは答えていただけたら答えていただきたいと思います。推定している数字です。","respondent":"鈴木都市計画課長","answer":"他区の利用率ということでしょうか。","voiceIndex":130,"id":"exchange-053"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"分かりました。好スタートを切って早期にやるほうがいいとなればやっていくということでいいのかという確認なのですが、そうすると、大崎ルート、荏原ルートは、早くても４年後からの試行になってしまうということになって、やはり皆さん、コミュニティバスの実施を待ち望んでいるというところがあるので、ぜひほかのルートでも試行運行をしていただきたいと思っているのですが、いかがでしょうかということ。","respondent":"鈴木都市計画課長","answer":"それはそのときに適時適切にしっかり判断していきたいです。それから、そのときの評価指標につきましては、やはりそれぞれの試算した結果がまずベースとしてありますので、ほかの２ルートについても５０％で行うということは基本的にはないかと考えています。","voiceIndex":134,"id":"exchange-054"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"その有効性を収支率のみで判断するということ自体がやはり間違っているというふうに思うのですけれども、移動が不自由な方々が、高齢者の方とか、ベビーカーの方とか、そういった方々が移動できているかというような視点が移動の権利の保障というところで必要だと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"コミュニティバスについては、品川区地域公共交通基本方針の中で、基本的には、鉄道や路線バスを補完する交通手段ということで位置づけしています。","voiceIndex":136,"id":"exchange-055"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"運賃について伺いたいのですけれども、今回、運賃は２２０円に設定されておりますが、事前の調査では、１００円がいいというのが５７％ということになっておりますけれども、この２２０円にしたのはなぜかということと、あと、シルバーパスの利用、あと、（第２回品川区地域公共交通会議の）主な発言の中にもありますけれども、障害者割引とか、子ども運賃の設定はするのかということでありますが。","respondent":"鈴木都市計画課長","answer":"運賃の２２０円の設定ですが、基本的には、先ほどご説明したとおり、事前のアンケートといいますか、意見記入シートの中では、ご紹介いただいたパーセンテージとして、１００円の方が要望としては多かったですが、率直な所管課としての受け止めとしては。","voiceIndex":138,"id":"exchange-056"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そこでもう１点、乗換券というのは考えていらっしゃるのかというところで、大井ルートが西大井駅と大森駅をつなぐルートになっておりますが、やはり、大井町に行きたいという声も出ておりまして、そのもとでバス停で今あるルートで乗換えをしていくということができるようになると、さらに使われるのではないかというふうに思うのですけれども、乗換券などを考えていらっしゃるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"乗換券のご質問につきましては、これから行うプロポーザルの条件に必須として区がそれを限定としてつけるということは、今は考えてございませんが、その乗換券も含めた乗車向上につながる様々な提案を事業者のほうから積極的に行っていただきたいというふうに考えてあります。","voiceIndex":142,"id":"exchange-057"},{"speaker":"西本委員","kind":"確認","question":"数字の確認だけです。別紙２の８ページと、それから別紙３の３５ページのところの大崎ルート案の２２０円の場合の年間運行収支の数字が違うのです。これ、（別紙３では）収支率６７％になっていて、この別紙２は４９.６％なので、この数字が違うのはなぜでしょうか。大崎ルートの一番右側の運賃２２０円の場合の収支の数値が全然違うのです。","respondent":"鈴木都市計画課長","answer":"失礼いたしました。ご指摘のとおり、（別紙３の）３５ページと（別紙２の）８ページで違いがありますので、戻りまして至急確認をしますが、正しくは……。違いについては改めて確認します。失礼いたしました。","voiceIndex":145,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、１点だけ。コロナ感染症が広がっている中だと、利用者が少ないとか、人が集まってはいけないとか、今は緊急事態宣言発令中なので不要不急の外出を避けることが求められるため、ほかの大井ルート以外のルート案についてはまだ進まないといったことなのか、そこら辺のコロナ禍の状況の区の考え方を知りたくて、お伺いできればと思います。","respondent":"鈴木都市計画課長","answer":"これまで３ルート候補案をお示しして、この３ルート案について試行運行を行っていきたいということで検討を進めてきている中で、今回、事業者をプロポーザルで決めるにあたって、３ルートをそのまま提示して提案してもらうのか、１ルート。","voiceIndex":148,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"提案","question":"何点か伺いたいのですが、資料の別紙３の３８ページ、試行運行開始までの進め方というところをずっと見ていくと、あとのほう、プロポーザルをやってというところで、あとはいろいろ提案に対するということをやっていくのだけれども、最後の４２ページのところで、これも併せて決まっていくと思うのだけれども、事業者に提案してもらうのか、どこでやるのかというのを教えてほしいのだけれども。","respondent":"鈴木都市計画課長","answer":"愛称もラッピングにつきましても、基本的には来年度末の試行運行開始に間に合わせたいというふうに考えてありますので、そういう形で今、検討を進めているところです。","voiceIndex":151,"id":"exchange-060"},{"speaker":"若林委員","kind":"質問・要望","question":"その下の残り２ルートについて、今回、プロポーザルはしないということで、これまで議会、また地域、ワークショップも含めて、様々住民、議会に説明をされていると思うのですが、私の理解の中では、さっきも説明がありましたけれども、３ルートをまずは一度にプロポーザルにかけるというところで、地域の皆さんも、令和４年度から試行運行が始まるということで、プロポーザルの結果次第ですけれども。","respondent":"鈴木都市計画課長","answer":"その後、必ず区内の１３地域を回って、その検討状況についてご説明している中で、資料のほうには明確にうたってございませんが、やはり一気にやるのですか、あるいは１本なのですかというご質問に対して、プロポーザルの中で提案していただいて。","voiceIndex":154,"id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、荏原ルートも取りあえず試行はスタートしないということなので、２６号線、品川区の最大の交通の課題であった東西の道路が開通するというところの、以前は路線バス等も含めてしっかり対応していきましょうと、また、現にもう既にバス会社には要望していますという経緯があったのですが、ここについて、２６号線のコミュニティバス、路線バスとも、そういう交通の利便性の向上について。","respondent":"鈴木都市計画課長","answer":"理想でいけば、その開通後に、今ご指摘いただいたとおり、区としては、民間バス事業者に路線バスの実施については以前から要望しておりますので、その路線バスの実現に向けて、働きかけといいますか、それを今後しっかり進めていかなければいけないという認識です。","voiceIndex":156,"id":"exchange-062"},{"speaker":"のだて副委員長","kind":"提案","question":"すみません、最後に、今回、プロポーザルの条件というか前提としては、大井ルートの提案を求めるということですが、ほかの２ルートについても提案をしていくという積極的な姿勢、提案というのはできるのかどうか。そこだけ伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的には、区として大井ルートをまず試行運行していきたいという形でお示ししますので、それ以外の提案について、積極的な姿勢ととるのか、条件に逸脱したものとしてとるのか、いろいろあるとは思いますが。","voiceIndex":159,"id":"exchange-063"}]},{"id":"topic-04","title":"立会川・勝島地区都市再生整備計画について ～（仮称）勝島人道橋等の整備検討～","agenda":"立会川・勝島地区都市再生整備計画について ～（仮称）勝島人道橋等の整備検討～","exchanges":[{"speaker":"のだて副委員長","kind":"質問・要望","question":"最初から決まっていることではないかもしれませんが、今この人道橋だけ突出をしているという状況ですが、そこの考え方を伺いたいと思います。この人道橋について、住民からの要望というのは、どういった形でどういう声が上がっているのか、住民の要望によってこの計画をつくっているのかということも含めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"初めに、都市再生整備計画を策定する上での利点といいますか、メリットですが、基本的には、この計画をつくって国のほうに提出をして、先ほどご説明したように、事業費の４割、橋を架ける工事費の４割を上限に国の助成を受けられる。","voiceIndex":166,"id":"exchange-064"},{"speaker":"のだて副委員長","kind":"質問","question":"１点だけ、防災性の向上についてもあるということでしたが、この人道橋が防災性の向上になるというところの理由を伺いたい。","respondent":"鈴木都市計画課長","answer":"一方、立会川エリアについては、木造の密集したところもありますので、そうした意味では、この勝島のどこかに反対側に渡れるような人道橋があることで、やはり地域の方々が避難をしていく上で、いろいろ方向性に選択肢が増えるということでは。","voiceIndex":168,"id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"すみません、１点だけ確認させてください。地域住民の利便性の向上の部分で、具体的にどういったところが、この橋が整備されることによって利便性が向上するのかというところをお知らせいただければと思うのですが。","respondent":"鈴木都市計画課長","answer":"勝島一丁目の地区の方々、特に今、従前の倉庫、物流施設から共同住宅等の居住機能に更新が大きく進んでいるということで、この方々が立会川駅に向かうにあたって、今までは１つのルートで、この下のほうの橋で「区民斎場」という記載がありますが。","voiceIndex":171,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"１つだけ。ほかの２つの基幹事業というのは、これはやはりまた人道橋みたいなものなのでしょうか。別の橋を作るという意味なのでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には橋は人道橋を今１か所、さらに２か所、３か所という考えはございませんので、それ以外の、例えば修景整備、あるいは先ほどご答弁申し上げたとおり、このエリア内の公園の改修工事等にこの事業を活用していきたいと。その残りの２つについては、今現在、検討中だです。","voiceIndex":176,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"多分、この立会川・勝島まちづくりビジョンをベースにした形でここら辺は開発が進んでいくのかなという感じなのですけれども、既存のしながわ花海道もあれば、ここはいろいろと地域住民の方々との交渉も入っていると思うし、しながわ水族館であれ、しながわ区民公園とかということでの総合的な開発にもつながっていくことなのかなと思うのですが、その辺の関係性はいかがですか。ここ全体の。","respondent":"鈴木都市計画課長","answer":"基本的には、平成３１年１月に策定しました立会川・勝島地区まちづくりビジョンで定めたエリア内について課題を抽出していますし、その課題解決のために今後どういう取組を進めていくかということを検討しながら進めていきますが、そこで。","voiceIndex":178,"id":"exchange-068"},{"speaker":"西本委員","kind":"意見","question":"そういったときに、その地域の特性を活かしながらつくっていくということは当然なのですけれども、やはりそこでの調和というものが同時に出てくると思うので、最終的には品川区はどのようなまちなのかとかという、１つの大きな特徴に出てくるといいなと、その中での地域ごとの特徴が出てくると、またさらにいいのかなと考えていますので、また報告があるかと思いますが、楽しみにしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-069"},{"speaker":"石田（秀）委員","kind":"意見","question":"この人道橋ができるときに、お願いしたいのは、勝島運河はやはりあそこへ行って、しながわ花海道のほうはいいけれども、住所で言うと勝島のほうが、やっぱりそんなに整備がされているわけではないし、高速道路もあるしということもあったりするので、非常に寂しい感じがするなと思っていて、やはりそこには今言ったように、住んでいらっしゃる方はすごく増えているから人道橋があったほうがいいと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-070"},{"speaker":"若林委員","kind":"確認","question":"ちょっと感触を確認といいますか。これは大きく３つ、まちづくりの目標が掲げられていて、今回の人道橋というのは、ここに当てはめていくと、恐らく最初の水とか緑、歴史も含めてなのかどうなのかというところに入ってくるのかと。","respondent":"鈴木都市計画課長","answer":"ただ、そうは言っても、例えば先ほども委員からご指摘いただきましたが、歴史というところでは、旧東海道という歴史的な資源もありますし、あとは、立会川地区については、地域の課題として防災性、細街路が非常に多いというところもありますので。","voiceIndex":184,"id":"exchange-071"},{"speaker":"若林委員","kind":"質問・要望","question":"すみません、数字などと言ってしまって。いずれにしても、計画を立てるにしても、橋を架けるにしても、しっかりと地域の方とここまでまちづくりビジョンも一緒に作り上げてきたわけですので、当然そういう姿勢だと思いますけれども、地域の方の満足度が本当に１００％になるようなというところは確認をさせていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"事業を進めるにあたっての地域との関わり方、進め方ですが、細かいところで言いますと、人道橋を架ける位置ですとか、先ほどご指摘いただいた幅ですとか、そうしたところ、特に位置については。","voiceIndex":186,"id":"exchange-072"}]},{"id":"topic-05","title":"東中延1・2丁目、中延2・3丁目地区の防災まちづくり","agenda":"東中延1・2丁目、中延2・3丁目地区の防災まちづくり","exchanges":[{"speaker":"田中委員","kind":"確認","question":"原案の説明会の予定についてですけれども、感染症の対応ということで、事前申込制の第１回は１５名、第２回は３０名ということでした。その原案の説明会が予定されているのは、３月１３日と３月１７日で、緊急事態宣言が３月７日までですけれども、そこら辺の感染症対策の考え方というところで、緊急事態宣言が解除されても、事前申込制でこの予定数で行うのかというところを、まず１点確認させてください。","respondent":"佐藤木密整備推進課長","answer":"開催する場合も、ご説明しました事前予約制のほか、会場での消毒、換気、体温の測定ですとか、体調が優れない場合は出席を控えていただくようにご案内するなど、開催する場合は、感染防止対策をとって開催したいと考えております。","voiceIndex":192,"id":"exchange-073"},{"speaker":"田中委員","kind":"確認","question":"緊急事態宣言が解除されても、今、原案説明会として予定として書かれているもの等は変わらないといったことですか。それとも出席者の予定数をもうちょっと増やすとか、予約制はなしにするといったことは考えられているのか。ごめんなさい、もう１回確認させてください。","respondent":"佐藤木密整備推進課長","answer":"緊急事態宣言が解除された場合ということですけれども、引き続き、感染予防対策には十分注意する必要があるというふうに考えておりまして、このような対策をとっておりますので、それに関しては、ここに書いておりますとおり、また、今申し上げたとおり。","voiceIndex":194,"id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、今回の原案説明会はこの２回ということなのですけれども、説明資料は、ホームページでも公開はされる、そして、原案の縦覧、意見書の提出については行うということなのですけれども、そのことについての周知は、この地域の方たちにもされるのかということと、あと、縦覧期間中の縦覧場所が木密整備推進課で、内容については「区ホームページでもご覧になれます」ということなのですけれども。","respondent":"佐藤木密整備推進課長","answer":"は説明会の周知のお尋ねですけれども、本件につきましては、対象地域にポスティングを行うほか、土地建物を所有していらっしゃる権利者の方のうち、対象地域以外にお住まいの方については郵送でご案内いたします。","voiceIndex":196,"id":"exchange-075"},{"speaker":"田中委員","kind":"確認","question":"貸出はないということでよろしいですか。スライド４０の高度地区の変更についてなのですけれども、私もちょっと知識不足で分からないのですけれども、今まで高度地区が第２種高度地区と第３種高度地区だったところが、変更後、１９ｍ、３１ｍとなるということだったのですけれども、１９ｍや３１ｍとなるということは、高さが高くなるということでよろしいですか。","respondent":"佐藤木密整備推進課長","answer":"先ほどの縦覧といいますか、お尋ねがあった場合ですけれども、今回ご案内しました説明会の資料につきましては、説明会終了後も、ご希望があればお渡しするというご案内を考えておりますので、必要な分についてはご提供できるような形で準備いたします。","voiceIndex":198,"id":"exchange-076"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい、本当に詳しくないので、もしかしたら間違ったことを聞いてしまうかもしれないのですけれども、区のホームページで高度地区を調べたときに、第２種高度地区だと１５ｍ、第３種高度地区だと２０ｍとあって、この区域の場合だと２０ｍから３１ｍとなると、すごく大きくなるのかと思ってしまったのですけれども。","respondent":"佐藤木密整備推進課長","answer":"ですので、今の建物よりもずっと高いものが建つということは想定しておりませんで、委員のご指摘については、極端に高いものは建たないというふうにご理解いただければよろしいのではないかと考えます。","voiceIndex":200,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問","question":"中延や荏原中延の地域では、高いマンションが建ったことによって、地域の方たちからも、これ以上高いマンション等は建てないでほしいといった声が多く聞かれているので伺いました。でも、極端に高いものが建つような変更ではないということを伺ったので、そういった説明がきちんとされるように、理解されるようにしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-078"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今回、セットバックが中延２丁目Ａ地区のところでいきますと、道路中心から２.５ｍ後退をしなければいけないということで、今、既に敷地が薄いといいますか、道路に面して細くなっている場合、既に細いのがさらに削られてしまって、むしろ建替えができなくなってしまうというような状況が生まれてしまうのではないかと思うのですが、そこのところをどのように考えているのか、伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"導入にあたっては、資料のスライドの５のところで、これまでの検討の経過をご紹介しましたけれども、この地域で特に懇談会等もやって、かつ、戸別訪問等も行って進めてきてはいますので、一定の説明とご理解はいただいているのかというふうには考えておりますけれども。","voiceIndex":204,"id":"exchange-079"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それと、素案の説明会のときに質疑があったと思うのですが、その質疑の内容、どういった質疑があったのか、伺いたいと思います。そもそもなのですが、今回、斜線制限の緩和ですとか、容積率の緩和をするということで、こういった制限がされている理由、そもそものところなのですが、そこを伺いたいと。","respondent":"佐藤木密整備推進課長","answer":"３点お尋ねいただいております。１つ目の素案説明会の際のお尋ねいただいた内容ということですけれども、基本的には修正のご意見はなかったというのは先ほど申したとおりでして、内容についてのお尋ねが多かった状況です。","voiceIndex":206,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"いつですかと言われたときに、建替えのときですという話になっていると思うのです。もちろんメリットもあるわけです。それを今後どのように。今、そのルールで密集市街地のところも整備されつつあるなというように思うのですが、理解度なども、やってみて、どういう感じで進めることが可能なのか、ご理解は求められるのかというのは、ほかの地域から考えて、計画があるかどうか、お願いします。","respondent":"佐藤木密整備推進課長","answer":"実務的には、不動産関係の方であれば、地区計画に適合しているかどうかという届出が必要になりますので、十分ご存じであるというところもありますので、それに限らず、いろいろな場面で周知していくということが大事かなと考えておりますので。","voiceIndex":209,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"ほかの地域においても説明会は終わったからもう大丈夫というわけではなくて、やはりルール作りというものについて、品川区はこういうふうに進めていて、この地域はこうなりましたというのは、もちろんホームページとかニュースでお知らせはしているのでしょうが、やはりそれは継続的にしておく必要があるのかなというふうに思いますので、今回限りではなくて、今後。","respondent":"佐藤木密整備推進課長","answer":"まさに委員ご指摘のとおりかと思います。相続等で所有者が変わるということも非常にたくさんあるわけですので。今現在とっている手段のほかにも、どういったものがあるかということを研究しながら、今後も周知に努めていきたいと考えております。","voiceIndex":211,"id":"exchange-082"},{"speaker":"田中委員","kind":"確認","question":"１点だけ確認させてください。スライドの４４の意見書の提出についてのところで、「（区域内に土地や建物の権利をお持ちの方）」と書かれているのですけれども、これ、対象者を限る感じですか。","respondent":"佐藤木密整備推進課長","answer":"ここに書いてあるとおりでして、所有者の方、あるいは賃借人の方、そういったここの地域に権利を有する方が対象になっております。","voiceIndex":214,"id":"exchange-083"},{"speaker":"田中委員","kind":"質問","question":"都市計画法の中では、区内というか、対象地域全域ですよね。これはまた都市計画法とは外れるものになるということですか。ですので、地域を限定するということなのでしょうか。その法的な根拠をお知らせいただければと思うのですけれども。","respondent":"佐藤木密整備推進課長","answer":"規定上、このような形で権利を有する方という形になっておりますので、大きい意味での都市計画であれば全域に対して適用されますけれども、今回の場合は地区計画ということで、地域を限定した形で、こちらの土地建物についての制限という形になりますので。","voiceIndex":216,"id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"都市計画法の第１６条か第１７条か、どちらか忘れてしまったのですけれども、私、一般質問でもやっているのですけれども、たしか区域に限っていなくて、関係自治体の中での意見書提出が可能ですよね。区域に区切ることはないと書かれていたと思うのですけれども、そこのところをお知らせいただけますか。","respondent":"佐藤木密整備推進課長","answer":"地区計画については、都市計画の中の地区計画ということに規定されておりますけれども、こちらが限定されておりまして、第１６条の２項、先ほど、抜粋して述べましたのであれでしたけれども、「都市計画に定める地区計画等の案は。","voiceIndex":220,"id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほどのお話でも、相続というお話があったりしたときに、それに対しての意見も都市計画審議会でもあったけれども、私もその業界の方からも様々意見をいただいているのだけれども、６０m2と決まることは、ここは我々がどうというのではなくて、そのときも言ったのだけれども、これからこういう話があるときに、メリット、デメリット、それを必ず言ってほしいと。それだけ考えがあれば教えてもらいたい。","respondent":"佐藤木密整備推進課長","answer":"委員ご指摘のルールの中の最低限度の面積のお話につきましては、これまでも議会のほうでご議論いただいているところであることは十分認識しております。","voiceIndex":223,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、そういうことも含めて、ぜひそういうのは出していただくのもいいのだけれども、１回そういうことをしゃべらせてもらう機会が、地域の中の方でも必ずいるはずなので、業界の人たちはみんなよく分かっているから、そこら辺のそういう説明は１回するということも、もしできればやっていただきたいということだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-087"}]},{"id":"topic-06","title":"建築物の省エネ性能に関わる認定・判定申請手数料の見直し","agenda":"建築物の省エネ性能に関わる認定・判定申請手数料の見直し","exchanges":[{"speaker":"のだて副委員長","kind":"質問","question":"今回、法改正に伴って手数料を見直すということで、この法律改正の背景を伺いたいと思います。それと併せて、手数料の面積区分を細分化するということで、実際には手数料というのはどうなるのかということと、あと、（２）の評価方法の追加がされるということで、これは手数料がほかのものとは異なるのか、幾らなのかというところで伺いたいと思います。","respondent":"長尾建築課長","answer":"面積区分の細分化の部分ですけれども、現在、手数料として設定されていますのが、例えば低炭素建築物の認定申請ですと、共同住宅であったり、その他の建築物というところで、３００m2から２,０００m2という面積区分が設定されております。","voiceIndex":230,"id":"exchange-088"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、細分化のところは、段階的に手数料が、面積が小さいほうが手数料が低いのですかね。そういった形になっているのかどうかという具体的なところで、先ほどの例でいいのですけれども、幾らになるのかというところです。それと、背景のところは、省エネ性能を強化するということは分かるのですが、そこに至った、その法律改正をした背景を、社会的情勢とかもあると思うのですが、そこを伺いたい。","respondent":"長尾建築課長","answer":"それによって建物が原因で発生するＣＯ２であるとか、エネルギー自体の効率的な活用がより一層推進されるというところを目指して法改正がなされたところです。","voiceIndex":232,"id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"質問","question":"これはこれで、今言ったＣＯ２の排出量の話があって、こういうふうになるのはいいのですが、私もよく分からないのですが、ＢＥＳＴ省エネツールを使用した評価方法が追加されたとか、いろいろ今、ＺＥＢ認証とか、いろいろなものがあるではないですか。これから建物とかそういうものがあったときとか、例えばそういうときに何をやるのが一番効果的なのですか。これだったらどうと。","respondent":"長尾建築課長","answer":"今お話の中で出ましたＺＥＢであるとか、あと、今回手数料を見直した低炭素建築物であるとか、そういったところにつきましては、基本的には大きく２つの項目で性能を強化していきましょうというところになっております。","voiceIndex":235,"id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問","question":"大変いいことだと思っています。例えばこれは環境課がやるのかどうか分からないけれども、ぜひこういうものは、せっかくこういう申請もしなさい、こういうこともしなさいとなるのであれば、こういうことをしたらこうなる、こういうこともある、今言ったように、私も電気とか断熱ぐらいは分かったけれども、そういうのは、大体今、皆さん分かっているから、こういうことがあればというのがあるではないですか。","respondent":"長尾建築課長","answer":"そういった冊子の活用であるとか、あと、建物の建て替えを検討されているような方に、こういった省エネの取組というところを分かりやすく周知・啓発できるような部分については、関連する所管課とも協力しながら進めてまいりたいと考えております。","voiceIndex":237,"id":"exchange-091"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて副委員長","kind":"質問","question":"それぞれ目標達成ができていない原因は何なのか、伺います。住宅のところは、木造住宅の状況も伺いたいと思います。そして、この間、戸別訪問もされてきたということで、そこではどういった意見があったのか。昨年度は戸別訪問を７０１件行った中で、耐震診断が３件、耐震化改修が１件、除却が３３件ということで結びついているところもありますけれども、そういった状況を伺えたらと思います。","respondent":"長尾建築課長","answer":"戸別訪問の中で伺っているお話といたしましては、訪問する際にアンケート調査もしているのですけれども、耐震改修が実施できない主な理由というところで、やはり多くの方が費用負担の部分を挙げられております。","voiceIndex":244,"id":"exchange-092"},{"speaker":"のだて副委員長","kind":"質問","question":"都市防災不燃化促進事業のほうでは１１０件やられているということで、結構進んでいるというふうに私は見ているのですけれども、やはりそうしたところで対象範囲を全区に拡大していくということが、さらに進めていくためにも必要だというふうに思うのですけれども、いかがでしょうかというところです。やはり建替えをしていく支援が重要かと思います。","respondent":"長尾建築課長、佐藤木密整備推進課長","answer":"費用負担を軽減するための助成制度にはなっていると考えておりますので、その制度自体をまだご存じない方が費用の負担感の部分を抱えてとどまっているような状態も一定程度あるのかと考えておりますので、制度の周知については。ですので、全地域にというご意見ではありますけれども、区としては、まだまだ重点的に取り組むべきだというふうに考えておりますので、引き続き、必要なところに重点的に取り組んでいきたいと考えております。","voiceIndex":246,"id":"exchange-093"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"同様にこの対象範囲を拡大していくべきだというふうに思いますが、いかがでしょうか。今、地区内では２％ということなので、区の考えとして、２％をどのように捉えていらっしゃるのか。地震が発生して通電火災が起きないようにしていくということも被害拡大を抑えていくということで重要な取組みだと思いますが、その２％でよいのかどうか、伺いたいと思います。","respondent":"佐藤木密整備推進課長、中島防災課長","answer":"地震が起きたときに、もちろん区内で重点的に取り組まなければいけないところにだけ（地震が）起きるわけではないというのはもちろんそうですけれども、それに伴って起こる火災。感震ブレーカーについてお尋ねがございまして、ご存じのとおり、感震ブレーカーの設置補助につきましては、不燃化推進特定整備地区において行わせていただいているところでございまして、今回。","voiceIndex":249,"id":"exchange-094"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"どちらも対象拡大しないということですが、ぜひそこをしていただきたいと思うのです。それと、耐震化のところですが、熊本地震では新耐震基準以降の建物も被害を受けたということで、そういったところへ、新耐震基準以降の１９８１年から２０００年までに建てられた住宅についても耐震診断と補強工事の助成対象にすべきだというふうに思うのですが、いかがでしょうか。","respondent":"長尾建築課長","answer":"そこの部分については、今の法律の中ではしっかりと位置づけがされておりますので、そういったところの基準が変わった部分については、事業者であるとか、あとは建てられようとしている方たちに対しては、今の法律に基づく計画がもう既にされているところですけれども。","voiceIndex":252,"id":"exchange-095"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"は旧耐震基準の住宅を対象にということですが、やはりいつ地震が来るかというのは分からない、すぐに来てもおかしくないという状況ですので、そうした被害を未然に防いでいくためにも、新耐震基準以降の２０００年までのところでも、ぜひ助成対象にしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"かつて１９６４年、東京オリンピックがあったときに、東京の改造ということで、あらゆるいろいろな部分の都市の変更が図られたという経緯があって、この耐震化・不燃化においても、３・１１から始まって、オリンピックに始まって、最終的な目標は２０２０年ということで、あらゆるところで語尾として聞いているわけですけれども、このコロナ禍。","respondent":"長尾建築課長","answer":"ですので、全体的に見ますと、オリンピックがあるから、それに向けてというようなところは感じておりませんけれども、もともと事業を進めていく中でご相談があった方の生活の部分であったり、あと、こういうところで困っているのだという、耐震に限らず。","voiceIndex":256,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"私にちょっと認識がなかったところがあったので教えてください。緊急輸送道路沿道とありますが、緊急輸送道路というのは、第一京浜、第二京浜と、何か所ぐらいあるのでしょうか。","respondent":"長尾建築課長","answer":"区内の緊急輸送道路としましては、１３本ございまして、目黒通りであるとか、中原街道、あと第二京浜、桜田通りといったような幹線道路のほかに、あとは高速道路です。首都高の１号線、２号線であるとか、湾岸線であるとか、そういったものも含まれております。","voiceIndex":259,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"現在、８４％というふうになっているのですけれども、これは例えば、大分前になりますか、第一京浜だったか、第二京浜だったか、沿道の耐震化をしていないところを公表するとか、それとは関係はないのですか。これはどこまでどういうふうな進み具合というか、何を指標にして進んでいるとか、できていますみたいに言っていいのか、ちょっと分からなくなっているのですけれども、教えてください。","respondent":"長尾建築課長、佐藤木密整備推進課長","answer":"平成３０年にその公表がなされております。公表の内容としましては、沿道の建物で耐震診断をしているかしていないか。した場合に、どういった水準の耐震性能というか、状況だったかというところが公表されております。結果として複雑になってしまうのは申し訳ないのですけれども、できるところをうまく使って、今後とも進めていきたいです。","voiceIndex":261,"id":"exchange-099"},{"speaker":"西本委員","kind":"意見","question":"これは１つの表現の方法だと思うのですけれども。例えば密集住宅市街地ではどういう助成があるのかとか、何が恩恵を被るのか、何がいいのかみたいな、そういう状況で、なかなか自分に置き替えて考えられない部分があるので、そういう違う方面からの見方で地図に落としていただくと、非常に分かりやすくなるかもしれないと思ったので、余力があればということなのですけれども、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":264,"id":"exchange-100"},{"speaker":"若林委員","kind":"質問","question":"でも、地域の人は、いろいろなチラシをポスティングされたり、うちはここなのだけれども耐震が心配なのでと窓口へ行くと、あなたの住所にはこういうメニューがありますよという理解なのですけれども、それでいいのですよねというのが１つ。それは住民の方に有益になるかどうかは分からないけれども、そういう考え方はどうなのですか。","respondent":"佐藤木密整備推進課長","answer":"重々理解して進めていきたいと考えております。個別具体的なご相談があれば、例えば個人の方ですと、建替えについてというご相談が一番多いですけれども、そういった場合は、その方の地域をお聞きして、そこで使える制度のパンフレットを示しながらご説明する。","voiceIndex":266,"id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"今の質問とかぶるのだけれども、きちんと建て分けて重複してはいないのかという数字上の確認が１つと。一緒に不燃化のほうは、これはやっぱり不燃領域率が７０％でしたか、そこが１つのゴール、目標なので、ここにはそこまでは載っていないのですけれども、今の不燃化領域率の最新の状況はどこまでいっているのですかという確認をさせていただきたい。","respondent":"長尾建築課長、佐藤木密整備推進課長","answer":"こちらの木造住宅に関しては、やはり耐震化の事業の効果だけではなくて、同時に行っています不燃化特区などの木密整備推進課の事業の効果も併せて出ているものであるというふうに感じておりまして、普段の窓口、電話相談を受ける際にも。令和３年度以降も事業を延伸されたというところもありますけれども、引き続き、取組みが必要だというふうに考えておりますので、取り組んでまいりたいと考えます。","voiceIndex":268,"id":"exchange-102"},{"speaker":"若林委員","kind":"確認","question":"それを数字上で確認すると、この２つの耐震化・不燃化の表で、どの数字を見たら、その両課の連携がもうちょっと見える化できるのかなと。ちょっと無理ですか。ありがたいと思いながら、言っても、いわゆる除却は１,０００件とか、２,０００件以上あるのか、除却は両方合わせると二千数百件ぐらいまでいくのですか。でも、区内のいわゆる木造とか不燃化に必要な棟数から言うと、一部と言えば一部だと。","respondent":"長尾建築課長","answer":"これに関しては、トータルで３００件近くありますけれども、基本的にどちらの窓口に来ていただいても、案内に齟齬がないように、案内できるように連携を図っておりますので、捉え方としては。","voiceIndex":271,"id":"exchange-103"},{"speaker":"若林委員","kind":"意見","question":"それは災害に強いまちを目指すのだというところで、そことこういったいろいろなメニュー、当然、脆弱化を見るときにマトリクスを作ってと、これから始まるとは思うのですけれども、その計画の結果によって何かまた変わるのか、この耐震化と不燃化について強靱化計画の活用の仕方、そこら辺の受け止め方とか、逆に期待していること、もっと後押ししてほしいのだとかという、そこら辺、何か感想があれば。","respondent":"中島防災課長","answer":"来年度実施を計画しております強靱化地域計画の内容について、防災課が所管する予定ですので、答弁します。こちらにつきましては、やはり地域の強靱化のために目指すべき姿でありますとか、目標をしっかりと分析して、それに対する脆弱性を含めた評価を行っていく予定です。","voiceIndex":273,"id":"exchange-104"},{"speaker":"石田（秀）委員","kind":"質問","question":"今みたいな話が出たから１点だけ。もう記憶にないので忘れてしまっているけれども、ワースト１０町丁目があって、我々の品川区が４つか６つくらい入ってしまって、結構道路を抜かなくてはいけないとか、何をやらなくてはいけないと結構大騒ぎしたではないですか。","respondent":"佐藤木密整備推進課長","answer":"こちらでは、その前の第７回のときよりもいずれも改善しているという全体評価になろうかと思います。ただ、地域によっては、危険な地域は当然残っておりますので、引き続き、区の関係する事業を適切に進めて、今後とも地域の安全性が向上するように努めてまいります。","voiceIndex":276,"id":"exchange-105"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、ワースト１０に入っているところはどこだというのは言えないものですか。もし８回目で入っているところがあったなら、教えてほしい。","respondent":"佐藤木密整備推進課長","answer":"第８回の総合危険度で言いますと、１０位以内という地区には品川区は入っておりません。公表されているベースでいきますと、４７位に西大井三丁目が入っているというのが、区では一番高いというか低いというか、そういった町丁目になります。","voiceIndex":278,"id":"exchange-106"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"最後に１点だけ。区有施設のところで、耐震化が９９％になっているのですが、（耐震化に）なっていない残りのところはどこなのか、ぜひ進めていただきたいと思うのですが、いかがかということでお願いします。","respondent":"長尾建築課長","answer":"こちらの区有施設の中で９９％となっておりますけれども、残り１棟になります。こちらは単独の区有建築物ではなくて、区分所有というか、幾つかの権利者の方がいる建物になっておりまして、場所が水神児童センターの入っている建物になっております。","voiceIndex":281,"id":"exchange-107"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":85203,"voices":286}},{"id":"r03-20210222-9","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"文教委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"２月１９日の藤原議員の質問に関連いたしまして、教育だけじゃなくて保育のほうも今の時間でいいんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":2,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"保育園の入園申込者の一次不承諾者数および年齢別の不承諾数、そしてその方々の今後の見通しなどについて質問をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"}]},{"id":"topic-02","title":"第２５号議案、学校教育職員の旅費に関する条例の一部を改正する条例","agenda":"第２５号議案、学校教育職員の旅費に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点なのですけれども、そもそも交通費はまた別に支給しているのかを改めて確認したいのが１点です。それと、公務のために特に要した経費の実費額は何が想定されているのでしょうか。本改正後、この規定に基づいて支給されるケースはどれぐらいの頻度を想定しておられるのか。３点になってしまったのですけれども、お尋ねします。","respondent":"工藤指導課長","answer":"今回の改正でもありますように、いわゆる公務のために特に要した経費の実費額に想定するもの、想定は何かというお尋ねでございましたけれども、それについては特段、現状でいうと想定できるものは、あくまでも例えば天災その他やむを得ない事情などがあって。","voiceIndex":10,"id":"exchange-003"}]},{"id":"topic-03","title":"令和３年請願第２号、区立小学校における「３５人学級」の実現についての請願","agenda":"令和３年請願第２号、区立小学校における「３５人学級」の実現についての請願","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"教員のほうは手当てがあると思うのですが、教室不足については、具体的にどの程度の不足がそれぞれの年で起こって、あるいは教室以外にはどのような環境が不足すると教育委員会では試算されていますでしょうか。","respondent":"篠田学務課長","answer":"ただ、どうしても、特に改築の済んでしまっているような学校におきましては、なかなか教室の増というのは相当工夫しなければ難しいと考えていますので、そういった学校について、何らか手当てが必要になってくるのかなと捉えているところです。","voiceIndex":26,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"いろいろな不足の中で、教室不足が一番、解決困難なものだとは思っているのですけれども、基本的には学校選択ですとか、あるいは一次的に学区を流動的にするですとか、そうしたソフト面での対応を考えていらっしゃるのか、それともプレハブ校舎、あるいはその他近隣の建物も使ってというハード面の対応を考えていらっしゃるのか、その辺りのお考えはどうでしょうか。","respondent":"篠田学務課長","answer":"これらの問題への対応ですけれども、１つは今、委員がご指摘になったようなソフト面での対応が確かに考えられるところではあるのですけれども、学事制度の変更を最近したばかりということで、いわゆる通学区域の見直しを全部かけてしまったという状況があります。","voiceIndex":28,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"いずれにせよ、実施することはもう決まっていることですので、環境整備、区だけではなくて、国や都に求めていくというのは妥当な内容だと考えています。この請願について１件だけ。その辺は請願で紹介議員もいらっしゃるところなので、よく吟味していただければよかったのかなとはちょっと感じているところです。私からは以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"それと、代表質問でも取り上げさせていただいたのですが、この動きを歓迎されるのですかということに対して、歓迎する表明は慎重にしたいという非常に後ろ向きな答弁が残念だったのですけれども、今の説明でも、教育の質の向上に対しては様々な見方があるという話がありましたが、そこについても学力だけではなくても、学力が上がるかどうかというのは確かにいろいろな検証が必要かもしれないのですけれども。","respondent":"篠田学務課長","answer":"今回の国の方針に対する都の考え方ですけれども、基本的に学級編制は都道府県の学級編制基準がございまして、それにのっとってやるですけれども、今の時点では東京都から考え方が示されていないという状況ですので、前倒しのご提案ではありますが。","voiceIndex":31,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"でもやはり国は１学年ずつということなので、既に小２までやっていますので、小３で始めるのは自然だと思いますし、そのように求めていっていただきたいですし、そのような措置はしていただきたいと思います。今の教室の現状なのですけれども、主に１点目に関わっているかもしれないのですが、今の教室の状態を教育委員会としてはどれぐらいつかんでおられるのかを伺いたいと思います。","respondent":"篠田学務課長","answer":"したがいまして、今のようなお話も、委員からお話があったとおり、壁がない形での改築が済んでいる学校であれば、少しオープンにできますので、そういった部分を有効に活用しながら対応しているのだろうと考えておりますので。","voiceIndex":33,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"知っていたんですかということを聞いたので、改めてお伺いしたいのと、あとそれはどれぐらいあるのかをつかんでいらっしゃるのか、併せて伺いたいと思います。そうなりますと、現在小学校２年生では３５人編制なのですけれども、来年４０人になってしまったら、クラスが増えてしまうという学校は幾つくらいあるのか、分かっていたらそれもお伺いします。","respondent":"篠田学務課長","answer":"学年が上がることによって、学級の対応がどうなるかですけれども、現状、今の時期は、ちょうど来年度の学級編制に向けて、特にこの３月末から４月にかけては転入・転出がかなり出てきますので、今の時点でどうなるかは。","voiceIndex":35,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今の時点ではということですけれども、当然、少なくとも３５人でやるということは国がもう方針を出しているわけですから、やはり今の時点で一定、現状の学年の子どもがそのまま上がった場合にどうなるかは当然、シミュレーションをするべきだと思いますし、しているのではないかと思うのですが、あえてそれをしていないと言うのであれば、していないのでしょうということなのでしょうけれども。","respondent":"篠田学務課長","answer":"４月からの３５人学級の実現に関してですけれども、あくまでも私どもは法や都の基準にのっとった形で対応していくのが基本になると考えているところです。","voiceIndex":37,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一点は、全国市町村教育委員会連合会は、３０人学級の早期実現は緊急かつ重要事項と意見を出しているのです。それが影響して３５人にということも１つはあると思うのですけれども、品川区の教育委員会は、この全国市町村教育委員会連合会に所属していらっしゃるのでしょうか。所属しているかどうかということと、あと区として国に対しては何か要望を出しておられるのか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"要望という面でいえば、東京都とかそういったところに今回の３５人学級の実現ですとか、そういったところはまとめて意見を出すという機会がありますので、そういったところが例えば２３区の意見というふうな形で東京都に出したりとか、そういった場面はあるです。","voiceIndex":39,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"加入しているということなので、となると品川区教委の態度と、３０人学級の早期実現は緊急かつ最重要事項というこの要望とちょっと矛盾するなと。そこに加盟して合同で要求を出しておきながら、自らはそのような態度に立たないというのはちょっと矛盾なので、ぜひ区も加盟しているところで出している要望を踏まえて態度を改めていただきたいと思いますけれども、いかがでしょうか。","respondent":"有馬庶務課長","answer":"要望はいろいろな項目であると思いますけれども、我々がそれを運用していく上では、今のところ法とか基準にのっとって運用していくというようなことで進めていくというものです。","voiceIndex":41,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは私の意見です。ぜひ子どもを第一に考えていただきたいということでは、そのような態度も改めていただきたいと再三申し上げたいと思います。最後ですけれども、この請願の１つ目のところに関わるのですが、「児童・生徒の教室内での距離をできるだけ広げ、３密を回避することが求められています」とあります。だから一刻も早く解消すべきだと思います。ぜひ、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-013"},{"speaker":"芹澤副委員長","kind":"提案","question":"今、様々お話しいただきましたが、我々の会派としては、国と都の提案が変わっていく、３５人学級になっていくというのを実現してほしいと。その実現に対して環境整備をしてほしいということで、紹介議員とさせていただいています。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-014"},{"speaker":"たけうち委員","kind":"意見","question":"それで、それを品川区が単独でやったときに、財源の当てがどれだけ来るのかも考えていかないといけないわけだから、前から言っているけれども、３０人だ、２０人だ、いろいろと出てきているけれども、それは理想かもしれないけれども、それを今できるところからやっていくという中で、３５人が国で決まったので、それをしっかり、まずはそこをしっかりと着実にやってよという請願だと思いますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-015"},{"speaker":"せお委員","kind":"意見","question":"こちらには急いでということは書いていないですし、今お話がありましたように、できるところから少しずつ少人数を実現していったほうが、急いでやることで子どもたちや教職員の負担になっては本末転倒だと思いますので、できるところから、時間はかけていっていただいて、検証などをしていって実現するのが現実的かなと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"国のほうでも３５人学級をやっていくという方向性はもう決まっているので、そのようになっていくのかなと思いますし、そのための環境整備をしっかりと、きっちり質も確保した上で進めていただきたいと考えておりますけれども、５年をかけるということで、品川区として、その５年後にきっちりと３５人学級が実現できるおおよその見通しは立っているのでしょうか。","respondent":"篠田学務課長","answer":"したがいまして、できるだけそれが実現できるような形で、何らかの工夫ができるのか、逆に５年間のお時間をいただているところでもありますので、その間、きちんと今、具体的に考えているところです。","voiceIndex":48,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日、結論を出すで、採択です。早めに拡充と前倒しというのをぜひ努力していただきたいとも思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"陳情・請願も完全に１００％合致するということではなくても、やはり求めるものに合っていれば、それは採択するという考え方です。一方で、教育委員会の、今から３５人学級は無理かもしれないと、その場合にはちょっと認めてもらおうみたいな形で取り組むのではなくて、やはり５年間で３５人学級を完全に実施するのだという決意で、この件は向かっていただきたいという意見を添えまして、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。学級編制は、新たな法の規定と国や都の基準にのっとって対応していただく必要があると考えますので、新しい時代の学びを支える指導体制や、必要な施設を計画的に整備していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-020"}]},{"id":"topic-04","title":"専決処分の報告について（報告第１号）","agenda":"専決処分の報告について（報告第１号）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"十分な安全確認のほうは、今後ともさらに注意していただくよう、よろしくお願いいたします。関連して、今回、鮫浜小の敷地を改めて資料で拝見したのですが、学校の敷地の中に京急の高架線が入っているということでよろしいのでしょうか。なかなか珍しいとは思うのですけれども、教育環境上、騒音対策などの工夫なども、どのようになされているのかも併せてお伺いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"すみません、図書館のときにも少しお伺いしたのですけれども、これは職員の方が仕事で行かれていて、この方は運転に慣れている方なのですか。運転をされる方は十分に部署内にいらっしゃるのか、その辺の状況を教えてください。","respondent":"有馬庶務課長","answer":"課の全体での保有人数、今、正確に何人というのはあれですけれども、運転できる人間は何人かいて、現場には庁有車を庶務課で２台持っていますので、そこで工事があれば頻繁に、週１回程度は必ず現場に確認に行ったりしますので、運転自体はまれに行ったということではありません。","voiceIndex":69,"id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"業務の一環として車を運転すると。運転する方に、その運転上のある意味、リスクもかかってくるという状況だと思います。それで、この庁有車は例えばバックの状況を画面で確認する、あれは何という名前でしたっけ、リア何とか、名前がありますよね。そのようなものがついていたり、あるいは接触で警告音が鳴るというような、今の安全装置というのはついているものなのでしょうか。","respondent":"小林学校施設担当課長","answer":"今のご質問にお答えしますけれども、そのようなものは現在の車にはついておりません。","voiceIndex":71,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"職員の方が業務の一環として車を運転する場合に、やはりその方に運転上のリスクがかかってくると思うのです。となると、やはりそこにはできる限りの安全装置、今ある安全装置がついたものを用意するというのが職場としてできることなのではないかなと思うので、そこはぜひ前向きに、教育委員会に限らず検討していただきたいと思うのですけれども、いかがですか。","respondent":"有馬庶務課長","answer":"そこで急ブレーキとかを踏んだりすると、ピピっと警告音が鳴ったりするということで、安全運転を心がけましょうということになっていますので、場合によってはもうバックカメラがついている庁有車もあるかもしれませんけれども、今そういったものも出てきていますので。","voiceIndex":73,"id":"exchange-024"},{"speaker":"あべ委員","kind":"意見","question":"ドライブレコーダーはどちらかというと事故の責任を明確にするのが主な目的かなと思いますけれども、やはり基本としての安全がより確保できる、これは誰の責任というだけではなくて、区の車がより事故を起こしにくくするのはとても大切なことだと思うので、ぜひ前向きに検討してください。相手方、ごめんなさい、これは物損でいいのですよね。人身事故ではないですよね。","respondent":"有馬庶務課長","answer":"停止していた無人の車に接触したということで、物損です。","voiceIndex":75,"id":"exchange-025"}]},{"id":"topic-05","title":"令和３年請願第３号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"令和３年請願第３号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"所管質問でも出ていることなのですが、聞いてしまいますけれども、今年４月の保育園の応募の一次応募人数と、承諾数と不承諾数と、あと二次募集に応募した方の人数を伺いたいと思います。どのようにつかんでいらっしゃるのかを伺いたいと思います。","respondent":"立木保育課長","answer":"４月の一次申込みの結果ですが、入園の申込み者が３,９１５名、そのうち内定が２,６２９名。それから不承諾のほうが１,２８６名ということになってあります。二次の応募状況ですが、ただいま集計中です。","voiceIndex":83,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"不承諾が１,２８６名ということで、最終的には二次が減ってということもあると思うのですけれども、待機児童をなくしてくださいという１の項目にかかわって質問すると、本会議でのやりとりでも、来年４月の待機児童の状況について質疑があったと思うのですが、来年も基本的に充足できますというような趣旨の答弁があって、これまでのように待機児童は基本的に解消みたいな。","respondent":"若生保育支援課長","answer":"こちらについては、区としてもこちらにのっとって見込みを立てているところでございまして、４月の見込み数、待機児童というところに関しましては、昨年同様、十分に供給できると考えているところです。","voiceIndex":85,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"つかんだ上で、それに対する対応をしていただきたいと改めて要望します。それと、項目２にかかわってですが、私立保育園が増えたことで人員的、時間的な負担が大変なことと思いますという部分がありましたけれども、私立保育園が増えたことでの区の業務的な負担はどのような実態なのか、漠とした質問で申し訳ないのですが、伺います。","respondent":"若生保育支援課長、立木保育課長","answer":"私立保育園が増えたところによる実質的、量的な負担というお話でしたけれども、これは私ども職員のほうでの負担ということで解釈させていただければと思うのですが、そういった意味で申し上げますと。ただし、その２０％も全てが使えるわけではなく、施設の面積等、こちらの中で基準に合致する部分に関してまでは拡大はしてもいいということになっておりますので、その範囲内、１割から２割の範囲の中で例年。","voiceIndex":87,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"それと、弾力化のところは面積基準に合致する中で２０％までということですが、伺ったのは、具体的にどのような考え方、例えばただ単に２０％までというのがその考え方なのか、そこら辺、もう少し伺いたいと。それを伺いたいと思います。子どもたちの成長に直接かかわるからです。それで質問なのですけれども、先日、コロナにかかわって保育士への従事者応援給付金を出したではないですか。伺います。","respondent":"若生保育支援課長、立木保育課長","answer":"私立保育園を所管している部門の人数です。保育支援課の私立支援担当というところで実際にやっておりますが、職員は現在９名です。こちらのほうは公務員という立場、全体の奉仕者という立場というものもございまして、まずは私立の職員のほうに重点を置いて支給をしたという考え方で。","voiceIndex":90,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"問題にしました。共産党でも質問したと思います。なので、やはり今のそういったやり方までして２０％の上限にして、さらに定員を弾力化していくのは、いよいよ子どもたちの育ちや健康にとってもよくないのではないかと思うのですけれども、今言ったようなそもそも面積を測る上でのことに関して、実態はどうなっているのか、もし反論などがありましたら聞かせていただきたいと思いまして、質問を終わります。","respondent":"立木保育課長","answer":"弾力化に使える面積は、保育室として使える面積ですので、当然、収納の部分ですとかそういったものは除外して計算しています。","voiceIndex":93,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのようなことであるならば、途中で改善したのか分かりませんけれども、しっかりと実態をもう少し調査して、そのようなことが本当にないのかどうかもつかんでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"私からは、３つの分野で質問をしたいと思います。待機児童なのですけれども、先ほど申込み数と不承諾について答弁があったのですが、それぞれ申込みと不承諾、年齢別に数字を教えていただけますでしょうか。年齢的な偏りが大きいというか、問題をクリアにするには必要だと思いますので、よろしくお願いいたします。","respondent":"立木保育課長","answer":"３歳児です。申込み者が４１１名、内定者が２６８名、不承諾者が１４３名です。４歳児です。申込み者が１２７名、内定者が６８名、不承諾者が５９名です。それから、５歳児です。申込み者が６５名、内定者が３７名、不承諾者が２８名です。","voiceIndex":96,"id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"やはり今年も１歳、２歳の不承諾が非常に多いなと感じます。全体としては、不承諾は昨年より２００人程度少なくなったということではありますけれども、一昨年と比べればまだ多い状態ですので、非常に高い水準だと思います。今、二次の選考中ですけれども、この不承諾になった方々の行き先、枠のパイがどの程度あるかは試算されていますでしょうか。","respondent":"若生保育支援課長","answer":"昨年度、不承諾になった方で認証のほうに不承諾のほうから除かれた数でいいますと、２７３名ですので、今年の４月に関しましても同数程度の枠は見込んでいるところです。","voiceIndex":98,"id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"ほぼ同程度と考えていいのでしょうか。そうすると、先ほどから、あるいは一般質問でもご答弁があったような、ほぼニーズを満たしているという認識で本当にいいのかということ。これはもう待機児童問題が品川区ではほぼ解決したという前提の下に立って３園ということになっているのか、現状では３園だけれども、まだ今の数字を基にもう少し増やしていく余地があるのか、その見通しについて教えてください。","respondent":"若生保育支援課長","answer":"ニーズに対しての供給というところで、見込みどおりいくのかですけれども、昨年度と同等のレベルで、先ほども説明で申し上げましたとおり、需要のところでいくと若干、見込みよりも下がっているということは計画上の数値から出ておりますので、そういったところから、一定。","voiceIndex":100,"id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"５月、６月、７月と子どもはどの月にも生まれるわけですから、やはり年度途中に保育ニーズは常に増える一方になっていくということは私が言うまでもないことでして、それを勘案したときに、やはり保育ニーズが今、満たされているという言い方をしてしまうと、昨年、結局保育園に入れなくて仕事を諦めたお母さんたち、今、入る当てがない人たちが、いない存在になってしまうのです。","respondent":"若生保育支援課長、立木保育課長","answer":"ニーズの捉え方を見直したほうがいいのではですが、こちらにつきましても、子ども・子育て支援事業計画、こちらのほうは考え方としては乳幼児人口を基に。入園不承諾の言葉の使い方の部分ですが、こちらはやはり受け取る方によって、いろいろと捉え方、お気持ちがあると思いますので、様々なご意見をいただきながら考えたいと思います。","voiceIndex":102,"id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"言いたいことは伝わっているとは思うのですけれども、ただ、やはりフルタイムでも入れないということがどのようなことかは、ぜひ考えていただきたいということ。それから、民営化については、今のところ品川区としては５園の民営化以上のところまでは踏み込んでいないということでよいのでしたっけ。ちょっと確認させてください。","respondent":"吉田保育施設調整担当課長","answer":"保育園の民営化につきましては、昨年の４月に民営化基準ガイドラインをつくりまして、現在５園、年間１園ずつ、今年の４月より令和７年まで５年間をかけまして５園の予定で今、進めているところです。","voiceIndex":105,"id":"exchange-036"},{"speaker":"あべ委員","kind":"意見","question":"保育園の民営化については、基本的に私は賛成はしていないです。ただ、諸般の事情において一部民営化を図るということを現在しているということについては、これはひっくり返さなければいけないというところまでは考えていないので、これについては請願内容とは少し違うところですが、意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"すみません、それを言おうと思って忘れていました。もともと所管質問でお願いした内容は、今、全て伺いましたので、明日の所管質問は取り下げということで結構です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-038"},{"speaker":"せお委員","kind":"確認","question":"１点だけ確認なのですけれども、先ほどこれから５園、公立保育園の民営化が予定されているというお話だったのですけれども、それは民営化、運営業務委託をしても認可保育園のままということでよろしいでしょうか。それが変わるということはあるのでしょうかというところだけ確認で、すみません。","respondent":"吉田保育施設調整担当課長","answer":"現在の例えばこの４月から民営化するところは、三ツ木保育園というところがありますけれども、こちらも認可保育園のまま、運営母体がライクアカデミーという会社に変わることになりますけれども、認可保育園であることについては変更はございません。","voiceIndex":111,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問・要望","question":"事実と区のご認識を確認させていただきたいのですけれども、そもそも、先ほど民間活力の導入というようなご答弁がありましたが、なぜ民営化を進める必要があるのか、それをいま一度、お知らせください。","respondent":"吉田保育施設調整担当課長","answer":"なぜ民営化を進めるかですけれども、国のほうの方針としましても、民でできるところは民で進めようというところがあります。区のほうといたしましても、まずは業務委託というところで民営化を進めるところです。","voiceIndex":113,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"民間委託したところ、もしくは私立保育園で実際、民営化および私立だからという理由で何か問題が発生したということはあるのでしょうか。この請願書にお書きのとおり、「民間委託のための時間を割くのではなく」というような文言がありますけれども、民間委託のため、この作業に区行政の負担がかかっているというような事実はあるのでしょうか。その２点、お願いします。","respondent":"吉田保育施設調整担当課長","answer":"現在、公設民営保育園という意味では、ひろまち保育園を皮切りに３園を進めてきたところです。今現在までに３園あります。","voiceIndex":115,"id":"exchange-041"},{"speaker":"たけうち委員","kind":"確認","question":"１点確認で、今、公設公営とかで区立でやっている場合には、国等からの補助金は一切ないと。それが１園５,０００万円ぐらいでしたか。その確認と、それがいわゆる今年の４月から始まる三ツ木のところから入るのか、それともその先の、これはまだ今はそこまで踏み込むかどうか分からないけれども、民間委託から民営化というのか、そこになった段階で入ってくるのか、そこを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"以前、平成２８年ぐらいのときに委員会のほうへご報告している際に、国からの補助金で一定程度の区の一般財源の割合が減るというのは、完全に民設民営になった段階で、現在、４月から進めている例えば三ツ木保育園とか。","voiceIndex":117,"id":"exchange-042"},{"speaker":"芹澤副委員長","kind":"意見","question":"本日、結論を出すで、不採択でお願いします。内容として、ちょっと認識が違うものもありますけれども、既に区がやっているところもあると思いますので、それは引き続き協力して待機児童対策やコロナ対策等に取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。理由としては、１番については、やはり認可保育園だけで待機児童をなくすのは現実問題としてなかなか難しい中で、認証だとかいろいろなものも増やしていくのがやはり大事だと思っています。それから３番については、今、区独自の手厚い人員配置ということでやっているという中で、この求めているところとは相入れないのかなというところで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-044"},{"speaker":"せお委員","kind":"意見","question":"私も保育ニーズを満たしているかと考えたら、ちょっとそこには課題があるとは思いますが、こちらの請願に関してお話ししますと、民営化しても、先ほどお話がありました認可保育園のままですし、あと保育士の増員のところがありますが、私が見聞しているところですと、例えば配慮が必要なお子さんとかにつく加配なども、苦労されて配置されていますし、区独自で配置している部分もありますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"本日、結論を出すで、採択です。理由は、待機児童はやはり解消されていないということで、解消していく必要があると。それと、今ある公立園は民営化すべきではないと思います。それと、子どもの健やかな育ち、成長発展の保障へ、弾力化ではなく、戦後すぐからずっと変わっていない基準ですよね。環境のさらなる改善こそ必要だと思いますので、採択すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-046"},{"speaker":"筒井委員","kind":"質問・要望","question":"将来の人口動向を踏まえて需給バランスも考慮した上で、この待機児童解消ということを進めていっていただきたいですし、コロナの感染拡大防止策もできる限りやっていただきたいですけれども、項目の２番目で、民間委託に問題があるかのようなご指摘ですけれども、民間委託でも特段の問題もなく、また、しかも私立にしたところでも認可保育園のままということなので、この請願項目２について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"ただ、先ほどの請願第２号のときもそうでしたけれども、全てが一致しなければその願意を認めないということではなく、どの会派の皆様も多少違うところがあっても、やはり目的といいますか、主たる請願内容に同意されるのであれば賛同するというようなことがつい先ほども行われたわけで、私もそのような考えから、若干違うところはありますけれども、ここで言っている保育園の整備ということについて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"結論を出すで、不採択でお願いします。既に機動的な新型コロナウイルス感染防止対策が講じられているかと思いますが、引き続き日々更新される情報を注視していただいて、状況の変化に合わせてスピード感を持って適切な対策を講じていただくことで、子どもたち、保育士などの保育の現場を取り巻く方々にとって適切な環境づくりへの努力をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5024#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":31044,"voices":130}},{"id":"r03-20210222-5","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"総務委員会","time":"午前１０時００分～午後 ０時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０号議案、品川区組織条例の一部を改正する条例","agenda":"第１０号議案、品川区組織条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ご説明ありがとうございました。２点伺いたいのですけれども、まず職員の人数、新と旧で職員の人数がどうなるのかというのが１点です。つまり、今、市町村交流担当の職に就いている方がいて、それが自治体連携担当と統合すると、人数はどのように変わるのか。そこを伺いたいと思います。もう１点は、協働・国際担当が廃止になってしまうのですけれども、その理由もあわせて伺いたいと思います。","respondent":"黒田人事課長、佐藤企画調整課長","answer":"新しい組織で想定しておりますのは、市町村交流担当は自治体連携担当へ統合いたしますので、市町村交流担当のほうのポストを廃止する、そういった意味で２名の係長が１名になるといったことです。冒頭ご説明したとおり、このたび新長期基本計画のほうで新しく施策の体系を組み替えまして、これまで土台をつくってきた部分に関しまして、組織を一つにし、より一体的に。","voiceIndex":15,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"統合されるのはいいかと思います。あちらこちらにあるよりも、一体で進めるという意味ではいいと思うのですけれども、地域振興部でやっていることは割と地域の中で、ある意味地域の現場でいろいろな事業、活動が行われてきたと思うのですけれども、今後、現場で行われてきた事業は、総務部の中で続けていくということなのでしょうか。お答えお願いします。","respondent":"佐藤企画調整課長","answer":"自治体連携担当に関しましては、これまで総務課で行っているとおり、高知県であったり坂井市との連携事業を今後も引き続き進めていくというところと、これまで地域活動課で行っていました山北町、早川町との連携も併せて、スケールメリットを出して一体的に。","voiceIndex":18,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"賛成しますが、毎回言うのですけれども、こういうふうに組織が変わったときには、やはり品川区内において各団体が活動しているのですが、なぜ急に、どうして変わったのかとか、そういう疑問がありますので、そうした伝達、説明はしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"賛成しますが、先ほども質問したとおり、今まで地域振興部のもと、地域でそれぞれ具体的に行われてきた事業は、継続して行われることを要望して、賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-004"}]},{"id":"topic-02","title":"第１１号議案、品川区職員定数条例の一部を改正する条例","agenda":"第１１号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、保育士ですけれども、民営化に伴って１３名のマイナスというご説明がありましたけれども、ここで働いていた保育士自体は、保育園の現場を離れて事務職に変わるのか、それとも別の保育園で専門性を生かすことになるのか、定数上の振り替えの説明は先ほどありましたけれども、実際、そこで働いていた保育士はどのような対応になるのか、お伺いしたいと思います。","respondent":"黒田人事課長","answer":"保育園の保育士につきましては、今回定数を１３名減としますが、基本的には他の保育園で引き続き勤務いただく形になりまして、これから一時保護所の開設に向けて、職員を確保していく中で、区の中では保育園等に勤務いたしますし、あるいは児童センターやすまいるスクールなど。","voiceIndex":32,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、保育園用務と小中学校用務ですけれども、以前から民営化をやめて専門性が生かされるように区の職員で行うようにと求めてきましたが、現状、区の職員は何人ぐらいいらっしゃるのか、その人数だけ伺いたいのと、民営化をやめて直営にしていただきたいと思いますが、あわせていかがでしょうか。","respondent":"黒田人事課長","answer":"現在、保育園用務と学校用務を合わせまして４０名ほどおりまして、年代もまだ若い方が、５０代ぐらいの方もいらっしゃいますので、引き続き保育園、学校等で勤務いただきますけれども、基本的には退職不補充という考え方をとりまして。","voiceIndex":34,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"今の用務の方ですが、生活者ネットワークとしても用務の作業はとても重要だと思っていて、今、新型コロナウイルス感染症の影響で、教員への負担がとても増えているということは、いろいろなニュースでも取り上げられています。その点について、どのような見解で退職不補充を、今は新型コロナウイルス感染症が拡大している中でも、このまま進められるということについて、お考えを伺いたいと思います。","respondent":"黒田人事課長","answer":"退職不補充の考え方ですけれども、基本的に今申し上げたとおり、民間活力を活用すると、そういった様々な業務の範囲でありますとか、業務量の増にも対応できるというところもありますので、そういう意味では今後も、そういった民間活力を活用しながら。","voiceIndex":36,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"民間事業者にとっては、その契約が根拠ですから、そこで急に、柔軟にというのは私は逆だと思います。それで事業を成り立たせなければなりませんから。そこで行政のほうから、これ、どうにかしてよ、などと言うのは、私は、それはできないかと思います。そういう意味でも、やはりここはきちんと、品川区として特に今のこの状況なので、きちんと人員を配置すべきだと思いますが、お考えを伺いたいと思います。","respondent":"榎本総務部長","answer":"それを柔軟に対応しないと、昨年の４月、５月の緊急事態宣言のとき、窓口を閉じたりいろいろ、契約内容が履行できなかったものもありますので、その部分については一部契約変更で対応して、そこを柔軟にしないと対応ができなくなるので。","voiceIndex":38,"id":"exchange-008"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今回３８名が増員されるということで、それぞれ検討されたとは思うのですけれど、やはり新型コロナウイルス感染症に伴い保健所業務が激増していることとか、各申請とか手続き、そういった業務がやはり増えていることもありますので、職員に過度な負担がかかりませんように、各課と連携しながら、今後も必要に応じて人員の確保はしていただきたいと、これは要望として出しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-009"},{"speaker":"須貝委員","kind":"提案","question":"私も同様の意見なのですが、今、新型コロナウイルス感染症の問題で様々な事業に大きな影響が出ていると思います。今回こういうふうに提案されたわけですが、私はいろいろ不測の事態もあると思うのです。そういうことも考えた上で、今回もということでしょうか、定数を一方は増やして、一方は減らしたということで、よろしいのですか。","respondent":"黒田人事課長","answer":"退職不補充という考え方を示しているところもありますので、そういった意味で全体的な職員数については、必要な人数を、今回ご提案申し上げているところです。","voiceIndex":42,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"保健予防課の増員など、新型コロナワクチンの接種ということは承知しております。今後運営が大変になるだろうから、定数が増えると認識しております。学務課はプラス１ということで、子どもたち１人にタブレットが配られ、２万５,０００台ものタブレットが配られました。学務課との話し合いというのはどうだったのでしょうか。","respondent":"黒田人事課長","answer":"ご指摘があったような問い合わせ対応等については、内容を細かく承知しておりませんが、例えばいわゆるヘルプデスクのようなところを置き所管のほうで対応しているというようなことで、そこも含めて民間活力の活用というところもありますので。","voiceIndex":44,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。ここの体制も強化された、人数が配置されていることと思うのですが、実際にこれからワクチン接種が始まっていく中で、何か不測の事態ですとか、人数が足りないとか、そういうケースの場合、運営の具体的なことは所管が違うかもしれませんが、ワクチン接種に対して人が足りないというときのお考えをお聞かせいただきたいと思います。","respondent":"黒田人事課長","answer":"今回ご提案申し上げているのは、いわゆるワクチン接種において、今、国が進めているところの市町村の役割の部分でございまして、今後進めてまいりますと所管のほうでも、医師会と連携して行う部分とかかりつけ医。","voiceIndex":46,"id":"exchange-012"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"現在、少し新型コロナウイルスの感染が収まってきている状況ではありますが、保健所の負担というのはかなりのものであります。その中で、ワクチン接種という新たな業務が増えてまいりますので、職員の負担等も考慮いただきながら、進めていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"児童相談所の開設準備や、保健所における保健師や一般事務も含め、定数の改善は進んでいるものの、まだまだ強化していかなければならないと思っています。一方で、保育園の民営化、また保育園、小中学校の用務の民営化を進めるという条例になっておりますので、反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"理由は、先ほどの質問では用務のところを取り上げましたが、保健師も、新型コロナウイルス感染症の影響だけでなく、例えば新生児とか乳幼児の検診の時もとても待たされる、ずっと赤ちゃんを抱っこしたまま待っているような状況のため、せめて番号札を配ってくれないかと。それで数を増やしてほしいというふうに、いつも言ってきたと思います。ぜひその辺は考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-015"}]},{"id":"topic-03","title":"第１２号議案、職員の服務の宣誓に関する条例の一部を改正する条例","agenda":"第１２号議案、職員の服務の宣誓に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"１点、もう少しご説明をという意味でお伺いしたいのですけれども、まず条例の定めによって、服務の宣誓をしなければならないと規定している理由は何かということと、押印がなくても署名で足りるというご説明がありましたが、本人の意思をそれで確認できるということでよろしいのか、もう少し説明をいただけたらと思います。","respondent":"黒田人事課長","answer":"服務宣誓の理由ですが、先ほどご説明申し上げたとおり、地方公務員法の中で「条例の定めるところにより、服務の宣誓をしなければならない」となっておりまして、この意義ですが、職員の倫理的自覚を促すことを目的とした規定だというふうに、されているところです。","voiceIndex":61,"id":"exchange-016"},{"speaker":"中塚委員","kind":"確認","question":"自分の名前を自分で書くわけですから、それで意思を確認することは、私も可能かと思います。条例改正に関わって、最後に１点伺いたいのですけれども、全庁的にはんこの合理性について、今後議論が進められていくべきかと思っています。どこの所管がどう旗をふるかはよく分かりませんけれども、区の姿勢として押印の必要性について、私は全部が必要ないとは全く思っていません。お伺いしたいと思います。","respondent":"立川総務課長","answer":"押印の見直しについては、現在準備を進めているところです。大まかなスケジュールといたしましては、今年度中に各所管のほうに通知等を出しまして、来年度、取りまとめる、そういった大まかなスケジュールになっております。","voiceIndex":63,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"あの方は口と足で何でもなされる方だったので、もしかしたらサインもきれいにされたのかなと思いますけれども、例えば視覚障害者の団体からは、視覚障害者の雇用を進めてほしいというご要望も出ていると思います。ぜひその辺については進めていただきたいというのが、生活者ネットワークとしての願いなのですけれども、それについてはどうなのでしょうか。お考えを伺います。","respondent":"黒田人事課長","answer":"趣旨といたしましてはご指摘いただいたとおり、職員の倫理的自覚を促すことを目的としておりますから、それは署名でなくても、形として宣誓したということが何かで残るところが合理的配慮の中でできれば、それで目的は達せられるのかと考えているところです。","voiceIndex":65,"id":"exchange-018"}]},{"id":"topic-04","title":"第１３号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第１３号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ただ、条例をつくるとき、政令を根拠にすべきなのか、そもそものウイルスを根拠にすべきなのか、今回、まさかこういう形になるとは誰も当初想定できませんでしたから、そうなのかもしれませんけれども、特に感染症の場合は、今後も政令を根拠とせずに、ウイルス名というのでしょうか、それで対応していくという考えなのか、かなり特殊な事例なので、今から明確にすべきものだとも思わないのですけれど。","respondent":"黒田人事課長","answer":"基本的には公務員のいわゆる手当ですので、国家公務員の規定に準じるところだろうと思いますが、そういったところも鑑みながら対応してまいりたいと考えています。","voiceIndex":79,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"設計段階においてどういった専門的な知見や、他自治体の事例などが反映されているのか、その点を伺いたいと思います。冒頭、委員長からもご説明がありましたが、資料の６ページ、一時保護所のレイアウトが伏せられている理由を率直にお伺いしたいと思います。いわゆる１人１部屋の居室なのか、病院で言う多床室なのか、そこだけは確認させていただきたいので、ご説明いただきたいと思います。","respondent":"小林施設整備課長、加島児童相談所移管担当課長","answer":"一時保護所、相談所、職員用と用途に分けて入口を設置したり、扉につきましても電子的な錠を用いてのセキュリティー管理を行うということで、そういったところはプライバシーあるいは保護のための対策として、進めてきたところです。３つ目の子どもの居室の部分ですけれども、原則個室を計画しております。ただ、きょうだいで保護した場合に備えて、２人以上でもきちんと過ごせるような空間としております。","voiceIndex":93,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"立面図だとベランダというかバルコニーというか、そういうものがあるように見えるのですけれど、それでよろしいでしょうか。その点についても伺いたいと思います。","respondent":"小林施設整備課長、加島児童相談所移管担当課長","answer":"私のほうから、２方向避難の関係とバルコニーの関係についてご説明いたします。階段ですが、お手元の資料のとおり、１階から３階の部分につきましては、右側に階段が２か所、図面の左上のほうに１か所、３つの階段が設置されてあります。ただ、災害時の避難経路として避難ハッチを設置しておりますので、階段が使えない場合に備えてそちらを利用する計画をしております。","voiceIndex":96,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺についても、一時保護所は上階ですし、エレベーターの使い方などでそれが配慮されているというのは、先ほどの御答弁で分かりましたし、港区の児童相談所の設計の実績があるということなので、大丈夫かなと思うのですけれど、いろいろな議論をされていると思いますけれども、確認しておられるようでしたら、お答えいただきたいと思います。","respondent":"小林施設整備課長","answer":"先ほどのプライバシーの話とか、あるいは人とすれ違わないような工夫といった観点ですが、ご指摘のとおり、やはりすれ違うことによって何か見られては困るようなこともあろうかとございまして、例えば３階の相談室ですが、平面図の右側辺りに５部屋ほど並んでいるかと思います。","voiceIndex":99,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。工事のほうも聞いていいのですか。一括で質問してよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"それに関してはどうなのでしょうか。例えば１３ページの電気設備工事のところに、自家発電設備とあるのですけれども、何かその辺で太陽光なり使われているのか、中水利用は全然今回は駄目だったということでしょうか。検討はされたのかなと思うのですけれども、その辺のことについてもお答えいただければと思います。","respondent":"小林施設整備課長","answer":"当初、設計の中では設置を進めてございましたが、シミュレーションを実施したところ、近隣にあります集合住宅に対しまして反射光の影響が発生するということが分かってあります。様々な角度、位置など調整を図ったのですが、解決に至らず、設置できなかったです。","voiceIndex":103,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"太陽光を使わないとか、中水利用がないというのは残念な気がするのですけれども、そういったいろいろな条件もあることですので、やむを得ないと思います。引き続き、品川区の建物ですので、品川区の環境方針にのっとったもので進められることを、これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"この入札ですけれど、何かいつも特定の会社が、落札しているのですが、入札に参加される品川区内の業者はこうやってほぼ決まってしまうのですか。それから、この建物はそれほど大規模でなく、小中規模の建物の割に、入札金額、見積金額、予定価格の設定が高いように思うのですが、こういうわけでこういう値段が出てきたのだという根拠があるのでしょうか。教えてください。","respondent":"東野経理課長、小林施設整備課長","answer":"ＪＶの要件といたしましては、第１グループ、第２グループとも区内業者ということで絞って公募をかけておりまして、その中でＪＶを組んでいただいたです。引き続き、そういった単価とか見積もりの状況をしっかり踏まえながら、適切な単価設定について進めてまいりたいと思ってあります。","voiceIndex":106,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"入札される業者に関しては、品川区は本当に支払いもいいし、建設会社にとっては優良なお客様だと思いますので、四、五件でなく、１０件、２０件ぐらい入札に来ていただけるような仕組みを、つくっていただきたいと思います。何かあったとき、助けを求めるとか、応援を求めるとき、少し対応が悪いのではという気もしたのですが、こういうわけで対応できますというような、何か理由があるのでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"ご質問いただきました相談室の運用についてですが、他自治体の事例を参考に、例えばですが、壁ですとか、机の下などに緊急用のブザーを設置いたしまして、職員が身の危険を感じた時には、そういった通報が執務室に届きます。","voiceIndex":109,"id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ほかにも工事はいろいろ行うと思うのですけれど、そういったことが含まれているのかどうかということが１点です。もう１点は、３階平面図ですけれど、下にあるエレベーターの北側に心理検査室が２室と心理療法室が２室ずつ、この４室があるのか、これは確認としてお聞きしたいと思います。これは本当にプライバシーのことなので、配置を考えてやっていただきたいと思います。これは要望です。","respondent":"小林施設整備課長、加島児童相談所移管担当課長","answer":"私のほうから、地中障害、設計のとき何をメインに考えたかということについて、お答えいたします。私からは、部屋の数についてお答えいたします。心理検査室ですけれども、分かりにくくて申し訳ございません、こちらは５室あります。心理療法室ですが、こちらは１室となっております。","voiceIndex":112,"id":"exchange-028"}]},{"id":"topic-05","title":"令和３年請願第１号、設計監理入札制度に関する請願","agenda":"令和３年請願第１号、設計監理入札制度に関する請願","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"この請願に関しましては、我々の会派にも同様の内容の要望が来たりしておりますので、我が会派からもお願いしたいと考えていますが、品川区のほうにもこういった内容の問い合わせというのはありますでしょうか。最低制限価格制度の導入につきましては、２３区中たしか１９区において導入されていると思いますので、品川区においてもぜひ導入すべきだと考えております。","respondent":"東野経理課長","answer":"こういった他区の状況を鑑みながらという部分はあるのですけれども、どういった形で導入に踏み切ったかですとか、その後の効果検証をどうしていったかという部分も含めまして、検討をしていきたいと考えています。","voiceIndex":145,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"この設計監理業務委託に関して、最低制限価格制度を導入することの効果について、この陳情にも書かれているとおり、建物の質、また価格、適正な競争、様々ご議論はありますけれども、品川区自身はその導入の効果についてどのように考えられているのか、ご説明いただきたいと思います。","respondent":"東野経理課長","answer":"ただ、安いから悪いということではなく、きちんと履行されればという観点で、これまでも進めてきたところですが、場合によっては品質の確保という部分から、少しどうなのかなという部分が今後も考えられるところですので、そういったところをより適正にという部分では。","voiceIndex":148,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"もしかして重なってしまうかもしれないですが、なぜ導入してこなかったのだろうというのがあり、今のご答弁の中に、質が確保できれば問題ないからということかなと思うのですけれども、そういう理解でよろしいのでしょうか。","respondent":"東野経理課長","answer":"ただ、それをかなり下回るというようなところにつきましては、会社として採算がとれるかという部分になってくるかと思いますので、そういったところをきちんとヒアリングなどもしながら、検討を重ねてまいりたいと考えております。","voiceIndex":150,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"だから、この価格が低くても今までは特段、質的に問題はなかったけれども、今後はそうとも限らないということと、要はそれでも質が確保できるということは、この陳情の2)のほうにも関係してくると思うのですけれど、一定規模の事業者であればそれができるけれども、小さい規模で事業をやっている事業者だと、人の配置もぎりぎりだから、それが難しい、という感じで理解してよいのでしょうか。","respondent":"東野経理課長","answer":"しかしながら、小さな業務につきましても、きちんと区としては適正に発注業務を行っておりますので、その中で最低制限価格を今後も受けていくという部分では、中小事業者にとっても悪い話ではないのかなと捉えております。","voiceIndex":152,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"それで品川区もそれに準ずるのかどうか。そうすると一概に、設計と建設を分離するのではなく、やはり建物を造るにあたってお互いに理解できるような、お互いの知識が合うような、そういった事業者でないとうまくいかないのかなという気が少ししたもので、その辺はどうなのでしょうか。","respondent":"東野経理課長","answer":"予定価格につきましては、一般競争入札の際に明記して提示している、事前公表しているという部分がありますけれども、最低制限価格につきましては、入札という関係からは特に明記するものではございません。非公表としているものです。","voiceIndex":154,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"私の質問が悪かったのかもしれません。建築とかには、都単価があるではないですか。こういった単価で、それで品川区は入札のときに最低制限価格を決めるわけですけれど、ただ、設計とか監理に関しては、もちろん行っていないのですけれど、都のほうで設計・監理の費用は、こういう積算で区として算出しなさい、というものがあるのでしょうか。","respondent":"東野経理課長","answer":"国の設計基準ですとか、都のガイドライン等を参考にしながら、品川区のほうも算出しているというものはあります。","voiceIndex":156,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということで、態度については採択を求めたいと思います。一言。既に２３区で１９の自治体で、設計監理業務委託に関して、最低制限価格制度が導入されております。ぜひ品川区でも早期に導入を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-035"},{"speaker":"須貝委員","kind":"質問・要望","question":"これをもし区として導入するならば、やはりそれぞれ他区の事例などを研究されて、私は慎重に進めていただきたいと思います。もちろん建設業者の話もよく聞いた上で、私は進めていただきたいと思います。今まで何もこういう問題が、起きていないということが、一つの過去の事例だったので、今回こういうふうに指摘されたということも意義があると思いますが、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明で、現庁舎跡については、新庁舎の進捗状況と、広町地区のまちづくりの進捗状況を見ながら、にぎわい施設の調査、検討をしたいというご説明だったと思います。伺いたいのは、まず、なぜにぎわい施設なのかということと、既に行財政改革特別委員会で、アリーナ等という言葉が出ておりますが、現庁舎跡になぜアリーナを造ろうと思っているのか、ご説明いただきたいと思います。","respondent":"佐藤企画調整課長","answer":"２点目ですが、具体的にアリーナというお話が出ておりますが、区といたしましては、先ほど説明がありましたとおり、新庁舎のほうの広さも決まっておりませんので、アリーナなど具体的な施設の検討を進めているものではございません。","voiceIndex":173,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、区民が望んでいる施設は何か、特養ホームや障害者施設、区営住宅、様々な公的施設が求められているときに、なぜ品川区はにぎわい施設を造らなければいけないのか、分かりません。改めて、広町地区開発ににぎわい施設を造ることが、大井町駅周辺のまちづくりにおいて、どのような位置づけなのか、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"広大な土地が出てくるということで、地元の方ともいろいろ話しながら、集客が図れるようなにぎわい施設をこの中でも設けるということで、具体的な内容については今後検討するという内容で、今、進めているものです。","voiceIndex":175,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"大井町駅周辺の再開発を進めるために、なぜ現庁舎の跡をにぎわい施設にするのか、どういう位置づけなのか、そこを改めて伺いたいと思います。改めて、にぎわい施設をここにつくることが、なぜ大井町駅周辺の再開発を加速させていく位置づけになるのか、お伺いしたいと思います。そもそも新庁舎を建てること自体、白紙に戻して、情報公開と住民参加で一からやり直すべきだと思いますが、いかがでしょうか。","respondent":"多並都市開発課長、濱中庁舎計画担当課長","answer":"この位置づけをもとに、今回、令和２年にまちづくり方針ということで、もう少し具体的な内容を定めさせていただきまして、この中でにぎわい施設ということで、ゾーンとして位置づけしていますが。新庁舎の検討ですが、現在、防災ですとかバリアフリーの課題等ございまして、また区民のサービス向上のためにも、新庁舎の整備の検討は着実に進めていきたいと考えています。","voiceIndex":177,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"代表質問の繰り返しになりますので、この場では省略しますが、改めて、なぜここににぎわい施設が必要なのか、またこうした東京一極集中を加速させる再開発は、根本から見直しをするべきだと思いますけれども、最後にいかがでしょうか。","respondent":"多並都市開発課長","answer":"この成果をもとに、これまでも方針策定の際には、地元にご意見を伺いながら進めてきたということがありますので、区としましては、このまちの課題の解決、また魅力の向上に向けて、広町のまちづくりについて進めてまいりたいという考えでいるものです。","voiceIndex":180,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"去年の決算特別委員会で、私たちは理解が悪いものですから、土地を交換するということについて、土地の価値を同等とするということで、換地、交換を進めていくというふうに聞いているのですけれども、この点線で示されている新庁舎建設候補地は、既にこの面積だというふうに決定したところまで、もう話しが行ってしまっているのでしょうか。その点について伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"つまり、面積はまだ決まっていないのですか。それが確認したかったのです。しかも要望するアリーナの内容が、かなり大規模ですよね。ですから、この段階では広さが固まっていないということを確認したかったのです。それで、まだ固まっていないよねということが今確認できたので、確認していいのですよね。まだ広さとか、決まっていないのですよね。","respondent":"多並都市開発課長","answer":"数字が決まっているかは、先ほども言いましたけれど、何平米ということが決まっているということはないです。ただ、ＪＲ東日本と品川区の区分を、このようにしていくということは、委員会の中でもずっと報告させていただいていますけれども、方向性は決まっていると。","voiceIndex":185,"id":"exchange-042"},{"speaker":"吉田委員","kind":"確認","question":"それが確認したかったのです。先ほど中塚委員のご質問に対する答弁では、今の本庁舎跡にアリーナを造るということは、まだ決定していないということでした。なので、まだ品川区としてもその辺までは考えていないということです。そういうふうに理解しているのですけれど。なので、最初と最後には不動産鑑定士を入れてきちんと計算をしていくというふうに理解しているのですけれど、それでよろしいでしょうか。","respondent":"多並都市開発課長","answer":"おおむね今の委員のご説明のとおりとなります。土地区画整理事業の場合、もう少し専門的に判定するものがありますので、もっと公平性がある形で審議されて、その上で事業認可の内容、要するに土地が担保されるというふうにご理解いただければと思います。","voiceIndex":189,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"理事者に対して回答を求めるとなると、質問としてはその辺までになってしまうのかと思うのですけれども、このアリーナ新設を求める方の陳情内容を見ると、今の品川区が進めている議論を踏み越えた内容が含まれているかというふうに思っております。それをこの場で、陳情審査ということで総務委員会だけで決めてしまうのは、どうかなと思うのが、生活者ネットワークとしての考え方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-044"},{"speaker":"須貝委員","kind":"提案","question":"アリーナはアリーナで、品川区総合体育館とかがありますから、それはそれでまた場所があったら造るでしょうが、今回は区民の大勢の皆さん、スポーツをする人だけでなく、大勢の皆さんのために新庁舎を造るのですから、私はこの陳情に関してはおかしいと思います。今回、なぜこういうふうにスポーツ団体の方が出してきたのか、よく事情を知らないで提案したのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-045"},{"speaker":"湯澤委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。理由といたしましては、陳情書にある反対理由を見る限り、コロナ禍における危険性等をもとに反対されているところであります。ただし、アリーナ建設を行う場合には、もちろん透明性のある審議、検討はしていくべきですし、今はコロナ対策その他優先すべきものがありますので、そういったものは引き続き行っていくべきだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":194,"id":"exchange-046"},{"speaker":"新妻副委員長","kind":"意見","question":"本日結論を出す。それで不採択です。第５号と第７号を一緒に説明をいただきまして、関連するものと思いますが、まだ区のほうもアリーナ建設について決定しているものではないというご説明もございました。第７号でも理由を申し上げたいと思いますが、まだ決まっていないということでもありますので、今回のこの陳情に関しましては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本日結論を出す、でお願いします。不採択でお願いいたします。理由としては、基本構想・基本計画策定委員会が行われる、またアリーナをどうするか否かという議論も、これから先も見ていかなければいけないので、態度としては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということで、態度については、品川アリーナ建設に反対することに私は賛成ですので、採択を求めたいと思います。一言。結局、ＪＲ東日本の開発を進め、大井町駅周辺の開発を加速させるために、貴重な区民の財産を開発業者の利益のために使うということは、あってはならないと思いますので、不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-049"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すということでお願いします。態度につきましては採択とさせてください。ただ、この陳情の内容でいうと、まだ何も決まっていない品川区庁舎の建て替えについて、アリーナを前提とするということについては反対ということですので、それについては生活者ネットワークも賛同いたしますので、採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":201,"id":"exchange-050"},{"speaker":"湯澤委員","kind":"意見","question":"継続でお願いしたいと思います。理由につきましては、現在新庁舎建設に向けての検討を進めている段階でありますので、敷地内に建設可能なのかも含めて、にぎわい施設等の検討を見守っていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":205,"id":"exchange-051"},{"speaker":"新妻副委員長","kind":"意見","question":"継続でお願いいたします。ただいま理事者の方からご説明をいただいたとおり、まだ議論が経過中であるという状況を踏まえ、公明党としてもその判断をさせていただきました。しかしながら、品川区議会公明党は、文化や芸術、にぎわい、またスポーツを否定するものではありませんので、またしっかり今後の庁舎機能検討委員会の状況を踏まえて、そこを見守っていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":206,"id":"exchange-052"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"継続でお願いいたします。理由としては、先ほどご説明があったようににぎわい施設は具体的な内容が決まっていないと。今後の検討にあたっては基本構想・基本計画策定委員会の中でいろいろ議論していただき、前向きにアリーナも検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、態度については、品川区庁舎建て替えにあたり品川アリーナ新設を求めることに、私は反対ですので、不採択ということになります。一言。時間をかけて一からやり直すべきだと述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-054"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いします。先ほどの意見に追加して申し上げますが、庁舎にアリーナを造るということは、３階、４階分までぶち抜かなければ造れないわけです。東京ドームぐらいの広さがあればまた別でしょうが、ここにアリーナを新設するなどという考え方は、私は完全に間違っていると思いますので、明確に不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-055"},{"speaker":"吉田委員","kind":"意見","question":"この陳情内容は、アリーナを造ってほしいというだけにとどまらない、土地区画整理事業の行く末も含めて、いろいろな政策議論が必要なことも含んでしまっているのです。民間事業者の積極活用も、どういう方向で積極活用するかというのは、かなり品川区としてきちんと議論する必要がある内容です。ですので、これについては明確に不採択とさせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":210,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":39453,"voices":215}},{"id":"r03-20210224-6","meetingId":"r03-cm02","date":"2021年2月24日","dateIso":"2021-02-24","committee":"区民委員会","time":"午前１０時００分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区民活動情報サイト「しながわすまいるネット」のリニューアル","agenda":"区民活動情報サイト「しながわすまいるネット」のリニューアル","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この５３４団体、登録団体のうちの企業と区民の活動の割合というのは、今すまいるネットを開くと、企業の社会貢献活動というので何団体か出てくるのですけれど、それが企業なのか、それともほかのところにも企業というか区内企業の活動が入っているのか、ちょっとその区民と企業の割合を教えてください。","respondent":"宮澤協働・国際担当課長","answer":"５３４団体のうち、企業は約６団体になっております。通常、このすまいるネットに関しましては、非営利目的での活動をしている団体となるのですけれども、企業においても社会貢献活動等を紹介する場合等に関しましては、登録でき、情報を発信できるような形になってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"こちらの部分の、今、そのすまいるネットのほうを見ると、その企業の社会貢献活動としては、すごく、１０件を超えている感じなのですけれど、団体としては６団体ということなのですか。工夫なども、その動画でということなのでしょうけれど、やり切れるのかなという思いがちょっとあるのですが、そこら辺はどう考えているのか伺います。","respondent":"宮澤協働・国際担当課長","answer":"ただその上で、入力の仕方がより分かりやすかったり、プレビューができたり、というような形で、分かりやすくはさせているところなのですが、それでも必ずしも説明会にご参加いただかなくてもできるような形で、マニュアルと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"くにば委員","kind":"意見","question":"１点が、先ほどご答弁がありました、アクセス件数が月７,０００件とのことなのですけれども、これ、サイト全体のことだと思うのですが、トップページのアクセス数であるとか、アクセスしているユニークユーザー数は分かりますか。","respondent":"宮澤協働・国際担当課長","answer":"先ほどの７,０００件というのは、トップページへのアクセスで、その他の細かいところに関しては把握していない状況です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"くにば委員","kind":"質問","question":"分かりました、ありがとうあります。サイトの全体の件数ではなくてトップページの件数ということで把握しました。こちらが、今いただいている資料の画像のほうのこのトップページと書いてあるものが、これが最終的なトップページのページと同一という認識でよろしいのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"開いていただきまして、左上のトップページという欄、新しいサイトのトップページの上側の部分になります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"そういったところへのアクセスがどういった形でできるようになっているのか、そこが結局使い勝手だと思うのです。実際これ、パイロット版のページはもう既にお試しになられたのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"すみません、説明がちょっと不十分で。チラシを開いていただいた、トップページが一番上の上部部分になりまして、そのままスクロールしていくと、下のイベントマップや各団体からの募集というのが表示されていくと。","voiceIndex":13,"id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"基本的にはトップページに集約されているという感じの概念でよろしいのですか。ここ、トップページ、イベントマップ、各団体からの募集、恐らくこの「各団体からの募集」とか「活動報告と連絡」というのが、さらにこのマッピング機能というふうに書いてあるところの下にあるのかなと思うのですが、これは全て、ではトップページに含まれているということでよろしいのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"そういう形では、トップページに全て含まれているという形になっています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"分かりました、ありがとうあります。そういうふうになっていないだろうかが非常に懸念がされます。例えば今、すまいるネットのほうであるコンテンツ、機能で、何か新しいサイトでなくなるものはありますか。例えばメールマガジン登録。メールマガジン機能はまだあるのでしょうか。ちょっとこのトップページを見ただけでは分からないので、教えてください。","respondent":"宮澤協働・国際担当課長","answer":"基本的に今まで使っていた内容というのは踏襲する形ではあるのですが、先ほど、デザインの話にもありましたが、デザインに合わせてちょっと形が変わっていたり、というところはあります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"今この新しいサイトを見る限りでは、その助成金の情報は一体どこから見ればいいのだろうというのも分からないと思いますし、例えば今、すまいるネットのほうで、今のそのすまいるネットのホームページをアクセス解析をすると、どこのページが実際によく見られているから、これはトップページのほうにもっていこう、であるとか、ここはもうほとんど見られていないから、もう下のほうの階層でいいよね、とか。","respondent":"宮澤協働・国際担当課長","answer":"先ほど区民活動助成に関する助成制度に関しても、募集時期等がありますので、その時期に合わせてきちんとこのイチオシ情報を発信していくと。併せて、例えば助成を受けて活動した団体の成果報告というのも、こういったイチオシ情報の中でお知らせしていく予定です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後にこのしながわすまいるネットですが、現在のサイトで何が一番使い勝手が悪かったとか、こういった部分をどうしても変えてほしいという部分、ずっと言われていたのはどんなところだったのでしょうか。団体一覧というところをクリックすると団体プロフィールのページで、そこではカテゴリーは指定できない。団体検索のところに行くと、地域が検索できない。","respondent":"宮澤協働・国際担当課長","answer":"旧サイトでの使い勝手の悪かった部分というところで、利用者からやはり一番大きく声があったのが、スマートフォンまたはタブレットでの最適表示化が対応していなかったというところで、活動をしている中で、今スマートフォンやタブレットで写真等を撮って情報を載せるにしても。","voiceIndex":21,"id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"すみません、最後もう１点だけ追加で伺いたいのが、これはホームページの更新であるとかの運営母体というのは今までと変わらないことになるのでしょうか。そこに関して、品川区のほうで助成金等で何かランニングコストがかかるのでしたでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"新しいサイトにつきましては、サイト運営をサーバー等を含めての維持管理等運営を委託する形を考えております。つきましては、情報の更新等に関しましては、その委託先の事業者のほうと我々、地域活動課のほうで協力しながらやっていくという形になっております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"今現在は、ＮＰＯ４団体がこれを運営されているかなと思うのですが、これは今後も変わらない、今おっしゃった委託される業者というのは、新しい、新規の業者ということで、今までそのページの更新を主に担当なさっていた、この運営委員会の４団体が引き続き行うということなのでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"しながわすまいるネット運営委員会のほうに関しましては、委託は令和２年度で終了予定です。新しく今度は、管理・維持および運営という形で業者のほうに委託をするという形を考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"松本委員","kind":"意見","question":"今回出していただいているのは一般の方が入ってくるときのトップページは出していただいているのですけれど、ログインした後のページというのはどういう変化があるのかというところをお願いいたします。","respondent":"宮澤協働・国際担当課長","answer":"旧サイト、また新サイトも共通しているのですが、各登録されている団体がログインした後のその作業というのは、それぞれの団体のプロフィールの更新であったりイベント等の情報発信という画面になってありますので。","voiceIndex":28,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"では例えば、サイトによっては登録している人、これは別に団体でなくても個人などでも同じだと思うのですけれども、ログインしたら、そのログイン、登録している人向けの情報が出てくるみたいなサイトがあると思うのですけれども、こちらのすまいるネットの場合は、旧もこれからの新というのもあまりそこは想定しておらず、基本的には、言い方は悪いかもしれないですが。","respondent":"宮澤協働・国際担当課長","answer":"おっしゃるとおりです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。以上要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほどスマートフォン表示対応等が利用者の方から結構多かったということで、今回、開設１０年を迎えて新しくするというところで、利用している方たちがより利用しやすい方法、というところで、どういった、アンケートではないですけれど、いろいろお声を聞きながら進めてきたのかなと思うので、どういったところがあって、それに基づいてこういう改善がされました。","respondent":"宮澤協働・国際担当課長","answer":"これは維持管理委託およびすまいるネット運営委員会への運営委託というのを含めた形で年間２７８万円だったのですが、これを今回一本化して委託する形で、約２３０万円程度という形で、ちょっと経費の見直しも併せて図ったところです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"委託の部分なのですが、３０万円安くなったというところだけなのでしょうか。今までやられていた方たちが運営したほうがいろいろ分かったりするのかなと。それともホームページを変えたことで、その委託で新しくつくったホームページ等を変えた業者がやったほうがいいからという理解なのでしょうか。今までやってきた人たちは今回で終わりということだったので、その辺の考え方を教えてください。","respondent":"宮澤協働・国際担当課長","answer":"委託の部分でございまして、今まですまいるネット運営委員会につきましては、区内のいわゆるＩＴといいますかデジタル系のＮＰＯ４団体で構成してございました。","voiceIndex":35,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"今あるすまいるネットだと、町会というと一覧がばーっと出てきて、ホームページがある、ないということだと思うのですが、２日前に町会連合会のホームページを新たにつくります、みたいなところがあったと思うのですけれど、それとの関係、例えばすまいるネットを新しくしたときに、町会検索とか、すまいるネットから。","respondent":"宮澤協働・国際担当課長","answer":"品川区町会・自治会連合会のホームページとの兼ね合いにつきましては、相互にリンクを貼るという形ですまいるネットを閲覧している方に関しても、町会・自治会の活動というのはこういう形だよ、とリンクを貼る形で、そちらのページと相互に連携していきたいと考えております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、リンクを貼って、町会・自治会連合会で、そちらでホームページに行くというのは分かったのですけれど、では検索などで、そこで例えば町会とかと入れても、バナーみたいなところに町会は特段なくて、検索で例えば、自分の住所を入れても、そこの町会などは検索で出てこないという認識でいいでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"町会・自治会を調べるという検索機能ではございませんでした。引き続き、すまいるネットのほうにも情報を載せたいという町会・自治会につきましては、情報をしっかり更新していっていただきたいというところで、そこは働きかけていくところです。","voiceIndex":39,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問","question":"は最後に、このホームページが新しくなって、今まで利用していた方たちも、入力はできるだけ以前と変わらないようにということで、利用しやすいままできるようにということ、これから、例えばこういう発信をしたときに新たに当然、登録したいという方たちも多く増えてくるのかなと思いますし、そういう人たちや団体が増えてくるのがこの一つの目的だと思うのですけれど。","respondent":"宮澤協働・国際担当課長","answer":"これからという部分になってきますが、例えば区内で活動するＮＰＯでは、子育て向けのイベント等を行っていたりというのもありますので、例えばターゲットを絞って、パパママ応援アプリというような形で、ターゲットを絞って周知活動等を行ったり、また。","voiceIndex":41,"id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"すみません、今大倉委員に確認していただいた部分、私も気になっていたところで、一昨日の委員会での連合町会のホームページとの関係性がどうなのかなと思ったのです。ＳＥＯの対策の次第だと思うのだけれども。大枠のリンクをお互いが貼るという部分のところと、それぞれの情報の細かく見たときの精査というところでは、どこまで支援ができるのかなという、この辺りについてのお考えがあれば教えてください。","respondent":"宮澤協働・国際担当課長","answer":"町会・自治会の情報に関して、先ほど、リンクを貼ると一言で説明しましたが、リンクの貼り方に関してもちょっと工夫をして、町会・自治会の活動に関してはこちらということで、いわゆるバナーのような形でワンクリックですぐリンクが貼れるような形であったり、また。","voiceIndex":45,"id":"exchange-020"},{"speaker":"つる副委員長","kind":"確認","question":"では確認で、ぜひその辺の整理、いろいろこういう紙媒体のチラシと同じような考え方なのかなと私は思っているのですけれど、どこか開くと古い情報で、こっちを開くと新しい情報で、あれ知らなかったということもままあると思うので、ぜひほかの団体への支援等、バランスを欠いてしまうといけないとは思うのですけれども、連合町会のホームページを担当している方と、くくりでは同じ部の中かと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"}]},{"id":"topic-02","title":"武蔵小山行政サービスコーナーの荏原第一地域センターへの機能統合","agenda":"武蔵小山行政サービスコーナーの荏原第一地域センターへの機能統合","exchanges":[{"speaker":"くにば委員","kind":"確認","question":"すみません、１点だけ確認させてください。今現在、武蔵小山創業支援センター４階にあるコーナーを閉所するということで、今使われているところの跡はどうなるのでしょうか。","respondent":"木村戸籍住民課長","answer":"創業支援センターの交流スペースが今隣接してあるので、そこを拡充、広げるようなイメージで考えています。","voiceIndex":53,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"武蔵小山の行政サービスコーナーが、改めてお伺いしますけれども、なくなってしまうということですね。それで、今度新しくできる荏原第一地域センターに統合されますよ、ということでいいのだと思うのですが、直近でいいので数字が分かれば、行政サービスコーナーの数、利用件数を教えていただけますか。","respondent":"木村戸籍住民課長","answer":"現在、サービスコーナーは３か所あります。大井町と目黒とこの武蔵小山の３か所です。こちらの武蔵小山につきましては、令和元年度の実績ですけれども、証明書の発行につきましては年間で約１万５,０００件。これは全体の発行件数からしますと３％ぐらいになります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"全体の３％とは、全体とは何ですか。それを教えてください。","respondent":"木村戸籍住民課長","answer":"失礼いたしました。証明交付を今行っておりますのが、区役所とそれから１３地域センター、それと３つのサービスコーナーとコンビニ交付となっておりまして、これのいわゆるトータルが全体という形です。","voiceIndex":58,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"１万５,０００件あったと私は思うのですが、それが荏原第一地域センターの機能統合で、統合されていくわけですよね。それに関しては、地域センター業務というか、受け入れられるからすると思うのですけれども、受け入れられる根拠というのはきちんとあると思うのですが、その辺はいかがでしょうか。","respondent":"木村戸籍住民課長","answer":"それから日曜日を開けるとか、火曜の夜もやるとかというような形でやりますと、今まで引っ越しの手続とか日曜日はできなかったのですけれどもできるようになると、またそれでお客様も来られるだろうということで、荏原第一地域センター側の体制も強化をするという。","voiceIndex":60,"id":"exchange-025"},{"speaker":"藤原委員","kind":"意見","question":"所管が地域センターだと違うので、所管は地活ですよね、答えられなければあれなのですけれど、ここは引っかかってしまうのですが、１万５,０００件あって、それをやっていた業務が荏原第一地域センターに行くわけですよね。人員配置とか、私はそんなに簡単ではないと個人的に思うのです。","respondent":"久保田地域振興部長","answer":"移行するに当たりまして、武蔵小山のほうのサービスコーナーの、例えば時間別の証明書の発行状況とか、また日曜開庁、火曜延長でどれぐらいの人が見込まれるかといったことの分析もした中で、例えば朝ですと、朝８時から８時半までサービスコーナーが開いていますけれども。","voiceIndex":62,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"部長の答弁で余計分からなくなってしまったので、というのは、朝１件か２件でした、という話だったではないですか。ただ、今の部長の答弁だと、１件か２件だし、統合できますよ、みたいなイメージが勝手に私はあるのだけれども、１万５,０００件近くがこう、ばんと移るわけだから、そこで大丈夫ですかと。","respondent":"久保田地域振興部長","answer":"いろいろとシミュレーションをやってきたのですけれども、確かに、武蔵小山サービスコーナーのほうで増える件数としては、年間にすると１万５,０００件増えてくるですけれども、例えばこれにつきましても。","voiceIndex":64,"id":"exchange-027"},{"speaker":"小芝委員","kind":"質問","question":"平日の時間帯はこれまでは７時まで、それが今度は５時までとなるということで、２時間営業時間が減っていくわけで、また土曜日はないというところで、平日の５時以降は別途案内をするということなのですけれども、こちらはこれも４番目の周知の方法でされるということの認識でよろしいのでしょうか。","respondent":"木村戸籍住民課長","answer":"そのとおりです。","voiceIndex":66,"id":"exchange-028"},{"speaker":"小芝委員","kind":"質問・要望","question":"要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"},{"speaker":"大倉委員","kind":"確認","question":"そこに加えて、先ほど藤原委員のほうからもありましたが、１万５,０００件がぽんと新たに来るのと、今懸念しているのはマイナンバー関連事務を行うということで、今区役所のほうでもやられているところでは、かなり人が来て混まれているところも、ちょっと広さとしての懸念点と、１万５,０００の数というところの懸念点があるかなと思っていて、先ほど来、部長のほうからいろいろ。","respondent":"久保田地域振興部長、木村戸籍住民課長","answer":"地域センターのほうの部分ですけれども、マイナンバーカードが増えることで、やはり事務量は増加するということですが、庁舎でもやっているように、例えば予約制を取り入れるとか、混まないような形をとって、また。今の点ではもう一つ、今まではかなり大きなスペースを用意しなければ、なかなか取扱いができないという形もあったのですけれども、今は機械もちょっと進歩という言い方は変ですが、コンパクトにできるような形になってきたので。","voiceIndex":69,"id":"exchange-030"},{"speaker":"大倉委員","kind":"質問","question":"なるほど、というふうに納得いたしました。より区民の方が利用しやすい状況になるのだろうなということで、その利用しやすくしてサービスを拡充していただいた中で、混乱が起きないようにと思って質問させていただいたので、大丈夫だということなので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"１点だけ。今、すみません、２度目だったのですけれど、部長が具体的に検討しているという中で、もしものすごく混んでしまったり、業務内容も増えるわけですから、というときに、その中の具体的な検討の中で、あの委託している方たちをまた、区で委託する人数を増やして、ここの荏原に置いていただけるという検討の中の一つに入れていただきたいと思っているので、その辺についてはいかがでしょうか。","respondent":"久保田地域振興部長","answer":"今回の職員の増強については、正規の職員のほかに会計年度職員とか再任用の職員等の人数も増やして非常勤の職員の人数等も増やして、対応していきたいというふうに考えているところです。","voiceIndex":73,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"確認","question":"ここにやはり、サービスコーナーがあったはずということで来る人も多いと思うので、その現地案内というのがどういうことなのか伺いたい。今サービスコーナーは、窓口委託ではなかったでしたか。大井町と武蔵小山の窓口は民間委託をされていたのではなかったかと思うので、ちょっとそこの確認をお願いします。","respondent":"木村戸籍住民課長","answer":"現地案内ですが、実際に移転、閉所した後につきましては、その創業支援センターのエリアという形になりまして、もちろんそれまでにはお知らせをしてはまいるのですけれど、そのつもりで来られた方については。","voiceIndex":75,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりこの案内のところはちょっと丁寧にやっていただきたいなというふうに私も思うのですけれども、それで、この業務が短く、全体として行政サービスコーナーとしてこれだけやった、今、表で示していただいているのですけれど、地域センターに統合した後の、その表の資料には拡充後というふうに書いてあるのですけれど、これで何で拡充なのかなというのは、ちょっと感じるのですが。","respondent":"久保田地域振興部長","answer":"今度は、荏原第一地域センターを火曜延長と日曜開庁することで、転入・転出もできますし、国保料とか納税の関係も受けることができるようになります。ですから、その意味では、私どもとしましては、荏原地区にとりましてはサービスの拡充になるというふうに考えているところです。","voiceIndex":77,"id":"exchange-034"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今、石田ちひろ委員が確認したところはちょっと私も気になるところで、内容は地域の方にとって、サービス低下になってしまったのではないかというイメージが先行してしまうとよろしくないのかなというところ。ただ１点指摘すれば、本庁舎の場合、ちょっと寂しいサインですよね。その全体としてサービスが低下するものではないんだよ、という。","respondent":"木村戸籍住民課長、久保田地域振興部長","answer":"今委員からお話しがありました、コンシェルジュ的なところという部分ですけれども、こちらも荏原第一地域センターと機能統合をする、荏原第一地域センターで行うことによって、いわゆる、今正直ご案内できない部分。ちょっと今は具体的なことはお話しできませんけれども、引き続き検討はしていきたいです。","voiceIndex":80,"id":"exchange-035"},{"speaker":"つる副委員長","kind":"意見","question":"なかなかそういう手続のときは人生の分岐点のときや節目に来られるケースが多くて、例えば人が亡くなるという、いろいろな地方自治体でお悔やみコーナーの設置が今進んでいますけれど、そういった生老病死のときに結構来られるケースが多くて、そういうときにやはりどうなのかなという、その地域センター内でのアウトリーチといいましょうか、どうされましたかとお声かけを、カウンターの外に出て。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-036"}]},{"id":"topic-03","title":"「品川区スポーツ推進計画（素案）」に対するパブリックコメントの実施結果","agenda":"「品川区スポーツ推進計画（素案）」に対するパブリックコメントの実施結果","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"素案に対してパブリックコメントを実施したわけですが、改めてパブリックコメントを実施した目的と、それと、使った予算、それと、１１人の方から意見、１７件頂戴したということで、行政として区としてありがたいですが、１１人１７件。特に１１人という意味で、この人数的なことを区としてはどういうふうに分析しているのか、教えてください。","respondent":"中元スポーツ推進課長","answer":"こちらまず、パブリックコメントにかかります予算ですが、こちら自体に関しては、区の媒体を使ってありますので、確かにこの書類等を整える職員自体の人件費などはかかっていますが、特にこれに関しての予算ということではなくて、全体を委託をしていますので。","voiceIndex":90,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"ただ、意見がなかったということは、逆に言うならば、品川区はよくやってくれているよと、このままでいいよと、素案これでいいよ、という思いの裏返しかもしれないので、意見がこの人数であることがいいとか悪いとかいう意味で言っているわけでは決してなく、逆に、認めてくださっている、すばらしい素案だということの裏返しであればいいのですけれども。","respondent":"中元スポーツ推進課長","answer":"私ども担当課といたしましても、公募で入られた委員ですとか、こちらで各専門家の方などで策定委員会を構成はしていますが、やはり区民の方に広く、案についてご意見を募ることが大切と考えていますので、そのような目的で実施させていただいているものです。","voiceIndex":92,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、ヒアリングも今回やったということで、前回報告ありましたか。ヒアリングの団体数というのを教えていただきたいのと、あとそこでの意見というのは、今回パブコメの１７件の意見、資料でいただいていますけれども、そうした団体の意見というのは、こういう形でまとめられているとは思うのですけれども、それもぜひ教えていただきたいなというふうに思うのですけれども、いかがでしょうか。","respondent":"中元スポーツ推進課長","answer":"ヒアリングの実施団体ですが、令和元年度の時点で１０団体、こちら、品川区身体障害者友和会、品川区手をつなぐ育成会をはじめとして、区立ですが児童センターの現場の方でありますとか、また地域スポーツクラブ、また。","voiceIndex":94,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり場の充実という意見が多かったということで、日頃スポーツに取り組まれている方とか、やれるならやりたいという方々も多くいると思うのですけれども、アンケートを取られていますが、障害者のところというのはやはりすごく、一般とは求めるものだったり支援だったりが全然違ってくると思いますので、リードも長くということでまとめていただいたということなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-040"},{"speaker":"小芝委員","kind":"質問","question":"それで、次のページをめくると、地域スポーツクラブの加入希望というのが１週間に１度未満、だから月に１回といった頻度でしかスポーツをしない、不定期実施層が７割に迫るということを知って驚いたのですが、こちらの加入希望というのがアンケートの調査結果ということで、全体の母数はどのくらいだったのでしょうか。","respondent":"中元スポーツ推進課長","answer":"全体のアンケートの数ですが、すみません、ちょっと今手元にすぐ出ないです。","voiceIndex":97,"id":"exchange-041"},{"speaker":"小芝委員","kind":"質問","question":"後で教えてください。分かりました。というのはやはり、こういった地域ごとのスポーツクラブの周知をやはりいろいろと進めてもらいたいなと思うのですけれども、そこら辺、今認識している課題について教えていただいてもよろしいでしょうか。","respondent":"中元スポーツ推進課長","answer":"ただやはり、結局そのリピーターの方は多いのですけれど、新たになかなか、その認知度が低いというところは本当に課題だと思っていますので、区といたしましても地域スポーツクラブを支援しながら今後も周知をしていくように努めたいと考えているところです。","voiceIndex":99,"id":"exchange-042"},{"speaker":"小芝委員","kind":"質問","question":"だけども一方で、人と一緒にスポーツをするということに対して、そういった希望があるのか、もしくは、いやむしろ自分の身体能力を高めていきたいという、それだけなのかちょっと分からないのですけれども、ぜひこういった、実際に品川区のほうも定期実施層の割合も多いので、ぜひそこら辺をリンクして結びつけていけたらいいなとは思うのですが、その辺ちょっとご所見を伺えればと思います。","respondent":"中元スポーツ推進課長","answer":"こちら、不定期実施層に関するアプローチのところですが、そちらのところがどうしても課題として捉えてありますので、いろいろな機会、いろいろな広報手段、また、その方々が取り組みやすいものをいろいろ、各自治体の先行事例などを研究して。","voiceIndex":101,"id":"exchange-043"},{"speaker":"小芝委員","kind":"質問","question":"民間の、例えばそういったちょっと先ほど出しました、ジムなどを利用されている方々をどうやって引っ張っていくか、誘致していくか、リンクづけていくかというのは、民間との体制がどうしても必要になってくると思うので、その辺はどのように考えますでしょうか。","respondent":"中元スポーツ推進課長","answer":"今、逆に民間のジムでもし活動されている方はできればそちらで継続していただけると、区といたしましてはその全ての方、住民の方を受け止められるスポーツ施設というのはなかなか、現状では実はそこまではできていないので、その辺のすみ分け。","voiceIndex":103,"id":"exchange-044"},{"speaker":"くにば委員","kind":"質問","question":"幾つか伺います。例えばシニアスポーツであったりとか、パラスポーツであったりとか、そういったものについてはどんどん推進していこうということで、ニュースポーツに多く取り入れているであるとか、あとは多くの世代の方々ができるスポーツ、障害者、健常者の方が一緒に楽しめるスポーツ、そういった様々な視点があると思うのですけれども、そういった導入に関してのポリシーであるとかをお教えください。","respondent":"中元スポーツ推進課長","answer":"ですので、区としても様々そのような、競技牲のあるスポーツだけではなくて、皆さんで勝敗にこだわらず楽しめるような、レクリエーションに近いようなものをニュースポーツという定義となっていますが、そういう気軽に楽しめるものというのは従来から取り組んでございまして。","voiceIndex":106,"id":"exchange-045"},{"speaker":"くにば委員","kind":"質問","question":"ご丁寧な答弁ありがとうございました。やはりそのニュースポーツが広がっていくというか、様々なニュースポーツ競技を取り入れていくことによって、まさにそのすそ野というのが広がる。そこの部分の課題が一番大きいのでしょうか。伺います。","respondent":"中元スポーツ推進課長","answer":"課題といいますか、やはり今既に結構飽和状態で教室をやっておりますので、場所の問題などもありますので、今もバウンドテニスであるとかノルディックウォーキングとか、そういうニュースポーツは実際やっておりますので、またこれに新たな種目を追加するというときには。","voiceIndex":108,"id":"exchange-046"},{"speaker":"くにば委員","kind":"質問・要望","question":"これが要望です。２つ目なのですけれども、４番目のパブコメです。もろもろ考え方があると思うので、その区長杯に関しての考え方と、あと現在行っている区長杯に関しての競技をお伺いします。","respondent":"中元スポーツ推進課長","answer":"区長杯という形ではなくて、例えばスポーツ推進委員の大会の一つとして、今実は、ソフトバレーボールの大会はやっているところがありますので、その辺のところで、区長杯ではなく地域スポーツクラブの交流大会の位置づけにするとか。","voiceIndex":110,"id":"exchange-047"},{"speaker":"くにば委員","kind":"質問","question":"その他の区長杯というふうに名前をつけている大会というのは、これはアンオフィシャルなのでしょうか。それともただ把握なさっていないだけなのでしょうか。そちらについてお教えください。","respondent":"中元スポーツ推進課長","answer":"私の説明をちょっと補足すると、区民大会で区長杯という形で出させていただいているのかと思います。ちょっとそこはすみませんが、手元で確認ができないのですけれども。","voiceIndex":112,"id":"exchange-048"},{"speaker":"くにば委員","kind":"質問・要望","question":"ではちょっと、今の部分、区民大会での区長杯の位置づけと、先ほどおっしゃった区長杯の位置づけ、重みであるとか、そこに関して補足説明いただきたいのですが。","respondent":"中元スポーツ推進課長","answer":"ちょっと今、確実なものが資料を手元に持っていないので申し訳ないのですけれども、区民大会自体が区長杯という位置づけになっているのかと、区民大会で優勝するとその区長杯としての位置づけで賞状やトロフィー。","voiceIndex":114,"id":"exchange-049"},{"speaker":"くにば委員","kind":"意見","question":"高校生、大学生でしたら学校が終わった後であるとか休みの日とかに指導しに恒常的に来られていたので、そこで層が厚くなっていたというのはあると思うのですけれども、やはり、昼間、ここにご指摘があるように、活動できる指導者の方はなかなか発掘が難しいのかなというふうに思う部分で、特に今回この昼間の指導者に関して何かお考えがあれば、今まで昼間の指導者が足りないという課題に対して。","respondent":"中元スポーツ推進課長","answer":"区として今まで取り組んでいるのは、今は実際に少年野球や少年サッカーを教えてくださっている方、また子どもたちのバレーボールの指導者の方、バスケットボールの指導者の方、この少年少女スポーツに関して指導者の方に１年に１度ぐらい、例えばプロ野球のＯＢの方など。","voiceIndex":116,"id":"exchange-050"},{"speaker":"くにば委員","kind":"質問","question":"じゃあそれだったらちょっとこの案件の仕事は一旦さておきでやりますよ、定期的であればやりますよ、という形でひとつの動機づけというか、どうしてもてこ入れの施策の一つの方法の考え方があるかなと思うのですけれども、そういった具体的に何か、昼間の指導者を増やす取組についてお考えが具体的なものがあれば伺いたいのですけれども。","respondent":"中元スポーツ推進課長","answer":"やはりそこは、区民の皆さんのボランティアのところでやっていただいているところが大きいです。その辺のところがなかなか、プロの方までというのも難しいところかなと思っています。","voiceIndex":118,"id":"exchange-051"},{"speaker":"くにば委員","kind":"質問・要望","question":"本日伺った３点、やはりそれぞれのスポーツの競技ごともあるのですけれども、品川区全体でのスポーツのすそ野を広げる、競技人口を広げる、ひいては区民の健康増進につながるという部分を具体的に、一つはニュースポーツ、新しいものを取り入れて興味関心が１つでも取っかかりが増えていただければという部分が１つ。はこちらの指導者です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":41421,"voices":133}},{"id":"r03-20210224-7","meetingId":"r03-cm02","date":"2021年2月24日","dateIso":"2021-02-24","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"もう一つは、この請願項目の第２項にある聴力検査の健診制度を作ってくださいということですけれども、前回、１１月３０日のこの厚生委員会の審議の中で、医師会との連絡会等の運用もありますので、そういったところからまた意見が出てくるようなことがあればお聞きするというような答弁を区のほうからいただいているのですが、その医師会のほうからも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"薬の処方を知らせるのと同じことをやっていけばいいだけのことで、それが十分にやられていないというだけのことだと思うのですけれども、その点いかがでしょうか。だから理由にならないと思うのですが、いかがでしょうか。その点もお伺いいたします。","respondent":"寺嶋福祉計画課長、高山健康課長","answer":"こちらも前回と重複しない範囲でお答えしますが、今委員からありましたように、まさに専門性の高い状況に関しましては、補聴器も専門性の高い医療機器であるということから。そういったことが非常に有効ではないかということで、いわゆる年齢を区切って対象を広げて一律に聴力検査を行うことによって、懸念される症状を見出していくといったことに関して。","voiceIndex":11,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"健診の話ですけれども、医師会の判断として何度も要望書が出ているのです。だから補助しないのだというのは筋違いではないかと私は申し上げているのですけれども、とにかく結果として装着されない状態になっているから補聴器に対する補助はしないのだというのは、筋違いとしか聞こえないのですけれども、その点、筋違いの説明しかされていないのではないかと思うのですが、いかがでしょうか。","respondent":"高山健康課長、寺嶋福祉計画課長","answer":"それを受けて、その要望されていることを全て予算化し、事業化してといったものではなくて、やはり医療の貢献・向上に現下においてどの事業の優先順位が高いかでありますとか。補聴器を購入したにもかかわらず使用しなくなったという理由につきまして、煩わしい、あまり役に立たないといったことが上位の理由を占めているということを先ほど申し上げたところですけれども、それについて。","voiceIndex":14,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"それは補聴器の使い方が分かっていないというだけのことであって、補聴器そのものが役に立たないということにはならないと思うのですけれども、それをいかにも補聴器が役に立たないものだと理解されているから、そういう話になるのではないでしょうか。それからもう一つ、こちらの早期健診のほうですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"早期健診のほうは、医師会の方も単に要望しているだけではなく、医学的な根拠を持っているからこそ何回も要望しているのであって、早期健診の必要がないと判断している区側の根拠というのは結局何なのでしょうか。医師会側が何度も要望しているにもかかわらず必要ないとされる根拠、その２点をお伺いいたします。","respondent":"寺嶋福祉計画課長、高山健康課長","answer":"それに対して専門機関の方が、しっかりとした正しい知識、理解を啓発していくことが重要だと言っているということについて、区も補聴器の有効性については否定するものではありませんと申し上げているところです。私からは後段の健診制度のお尋ねのほうのお答えですが、医師会が繰り返し要望している、医学的根拠に基づくものだということで、それを実現しない区側の根拠は何かというお尋ねだったかと思います。","voiceIndex":19,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"必要性が薄いという理由が私にはちょっと納得がいかないのですけれども。それから、補聴器が役に立つ立たないの話ですけれども、買われた人が役に立たないというのは、補聴器を買ってみたけれども役に立たないと感じられるのは、その補聴器の使い方に誤解があるからなのでしょう。そのことを前提にしたまま議論するのは、成り立たないのではないですか。","respondent":"高山健康課長、寺嶋福祉計画課長","answer":"先ほどのご説明が納得いかないということですけれども、繰り返しのお話となってしまいますが、高齢者の聴力低下は自覚ができ、またかかりつけの医師や家族など周囲の気づきもあることから。そういうことなので、まずは専門機関がしっかり正しい使い方の普及啓発に努めないと補聴器の利用が上がらないだろうというところでの説明を私としてはこの間ずっと一貫して申し上げてきたつもりです。","voiceIndex":22,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私が一般質問で２０１９年６月２７日に補聴器購入費の助成と健診制度についての質問をしているのですけれども、そのときにも、今、課長がおっしゃったように、高齢者の聴力低下というのは日常生活の中で何か聞こえにくくなっているなといった自覚ですとか、また家族など周囲の気づきもあるので、聴力検査を実施する考えはないとおっしゃっているのですけれども。","respondent":"高山健康課長","answer":"区が実施すべきいわゆる公的な立場で推進していく健診制度としましては、先ほどご説明いたしましたように、健康増進法などで定められているようながん検診、歯科健診など、そうしたいわゆる自治体として取組むことで。","voiceIndex":27,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"気づけるタイミングは様々あると。そういう加齢性難聴の特徴というのは自然に気づけるものだという認識は間違っていると私は思うのですけれども、改めてそこのところはどのように、だから健診は必要ない、早期発見も必要ないのだという立場を区としては取るということでしょうか。そういう答弁を繰り返されているのですけれども、それでいいのですかということをもう一回確認させてください。","respondent":"高山健康課長","answer":"先ほども申しましたように、周囲の気づきでありますとか医師などとの会話を通じて、何かしら懸念すべきものがあれば、やはり耳鼻科など専門の医師の判断をまずいただいて、その上で必要な器具などがあれば。","voiceIndex":29,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、医師会の先生が言われているのは、これは平成２７年ですけれども、私はもうずっと毎年やっていただきたいと思うのですけれども、耳鼻科の先生は区の財政のことも慮ってということになると思うのですけれども、とりあえずは６５歳以上の方を対象に５年おきに簡易な聴力検査の実施をお願いしたいということで要望を受けました。高齢化の進展に伴い、認知症の人はさらに増加する。","respondent":"高山健康課長、寺嶋福祉計画課長","answer":"この聴力検査にかかわらず、区で健診を制度化していくに当たっては、当然対象となる年齢層であるとか性別、それからかかる費用など。それとは別に、ここにつきましてコミュニケーションがいわゆる認知症の進みに影響があるということにつきましても、例えば各デイサービスであったり訪問介護等の中でもしっかりとしたコミュニケーションが図れるように。","voiceIndex":31,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だからこそ、次々と各区でも広がっているのではないですか。健康長寿。それは区も常々掲げていることではないですか。このことをぜひ認識していただきたいと思うのですけれども、いかがでしょうか。それと先ほど、ほかの国に比べて日本の補聴器の使用率は極端に少ないということで言われていましたけれども、その理由は、１つが補聴器が高すぎる。そういう認識はありますでしょうか。その仕組みがないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高齢期の聞こえの支援を考えるという学習会の講義を聞きました。こういうことがとても大事なことではないかと思うのですけれども、その点はどう考えられているでしょうか。これだけ認知症が問題になっているときですから、そして予防可能な最も大きなリスクがここにあると言われているわけですから、ここに関しても対応することが区の役割として求められているのではないかと思うのですが、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"今委員からご紹介いただきました慶應義塾大学の小川医師の情報につきましては、これだけでなく、区として認知症対策として様々な情報を取りまして、それぞれの専門家の知見に基づく貴重な情報ですので、可能な限り施策に生かせるように取組んでいるところです。","voiceIndex":37,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私が伺ったのは、そこでも言われているように、認知症のかなり大きなリスクになっているわけだから、認知症予防というところからも、認知症予防を掲げて“くるみ”プランとかでも取組んでいるわけですから、その品川区として、やはり難聴に対しての対応をすべきではないかということで伺ったので、その点についてお聞かせください。","respondent":"寺嶋福祉計画課長","answer":"初めの話に戻りますけれども、そういったことが補聴器の正しい使用についての普及啓発を専門家の方がしっかりやっていく必要があるという重要性を訴えているということで、区としては全く同じ認識を持っているところです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"意識も変わってくると思いますし、またそれがきっかけにもなると思いますので、ぜひ、今のところはというふうに言われているので、次々と各２３区で広がっていますので、これはぜひとも２３区でまた最後とならないうちに、品川区としても補聴器の補助をぜひともしていただくようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"前回も前々回も、もう何度も出ていますけれども、何も変わっていないですし、もう理由はそのままで、難聴に早期に気づき云々のところの区の健診制度というのは、例えばそれをすることによって命に関わるような、例えば血液の中の検査をすることによってこの人はこういう病気なのだとか、何の意識もなく調べてみたらこのがんが見つかりました、治療してくださいというようなものは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-014"}]},{"id":"topic-02","title":"令和３年陳情第３号、安全・安心の医療・介護の実現と国民のいのちと健康を守るための陳情","agenda":"令和３年陳情第３号、安全・安心の医療・介護の実現と国民のいのちと健康を守るための陳情","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やはりこれを教訓にしてさらに充実させて、いのち、安全、健康を守るというところでこれが求められていると思うので、私は皆様にもご意見をお聞かせいただきながら、委員会として国に対して意見書を出すという形でまとめていけたら一番いいという思いをしております。そのところで、改めて質問をしたいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ドクターが足りないということもお聞きしているのですけれども、その増員というのはないのか。それから、やはり公衆衛生が縮小されてきたというのが、今回問題としても浮かび上がったと思うのですが、そういう点では公衆衛生の拡充について、国や東京都などに区として、また全国市長会としてなど要望されていることがあれば、どのようなものがあるのかということも教えていただきたいと思います。","respondent":"高山健康課長、鈴木生活衛生課長","answer":"多くのものは、地方創生交付金を活用したりですとか、あるいはやはり区の一般財源を活用せざるを得ないもの、それからいわゆるその要素としましてガバメント・クラウドファンディングなどを活用したものもございまして。そのほかの国や都への要望につきましても、特別区全体で意見をまとめた上で、毎年度必要な項目について要望を上げているです。","voiceIndex":60,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回を通して、救急でもたらい回しになったり、手遅れで亡くなるとか、そういう事態も起きましたし、その中で改めて医療の現場で働くドクターや看護師も、ヨーロッパに比べて本当に少ないということも明らかになっていますので、そこのところをぜひ区としても国に上げていただきたいという思いをしているのですけれども、一緒になって医療や介護。","respondent":"高山健康課長、鈴木生活衛生課長","answer":"卑近な例といいますか、健康課などで対応している例で申しますと、例えば休日診療の継続に要する費用としまして、防護服の購入費用などで大体１,４００万円ほど。ただいま手元に詳細の資料を持っていませんが、基本的には新型コロナ対応のための医療関係の支援、それから経済関係の支援について、区で取組むときに必要な支援を国や都に要望を出したということで認識しております。","voiceIndex":63,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"以上で質問は終わりにしたいと思います。それで、ここに書かれていることは本当に当然だと思うのです。コロナ禍を通して、改めて医療や介護の充実というところは皆様と共通の思いになれるのではないかと思うのですけれども、委員会として意見書を国に上げていくということをぜひ提案させていただきたいのですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"今、確認させていただいたら、全く同じ文面をこの医労連のほうから衆議院の議長と参議院の議長のほうにこれから出されるのです。質問もすごくしにくいではないですか。先ほど言葉とか内容も選んで質問されていましたけれども、それはやはり無理筋の話だと私は思います。意見書を出せとも書いていないですから、そもそもそういう陳情ではないし、それはそう思うのが普通ではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-019"},{"speaker":"渡部委員","kind":"意見","question":"今、陳情に対する議論をしていて、この陳情をどうするかですので、それ以上も以下もございませんので、そこまでは。それをどうするかというのは、当然後ほど態度表明します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-020"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。担当課の説明にもありましたように、新型コロナウイルスの対応に関しては国、都、区でそれぞれ行っており、区独自で補うことも積極的に行っている状況です。これまでも区としてイレギュラーな事案を含めて適切に対応していただいていると思いますので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-021"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。区も、今取組まなければならないことはしっかりやっていただいていますし、逆に今回陳情で出ていることは公的病院云々ですとか保健所を増設しろとか、全然区として取り上げるべき問題でもございませんので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-022"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いいたします。コロナ禍で明らかになった様々な不十分な社会保障の体制について、地方自治体から声を挙げていくことが本当に大事だと思います。採択にしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。国および都に関わる内容があるということ、それから区が関わるところでは今回の補正、あるいは令和３年度の当初予算の中で織り込んでいると。そこの手前でも現行の予算の中でできることは実施されているということですので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-024"}]},{"id":"topic-03","title":"令和３年陳情第６号 八潮団地に風呂付シルバーセンターの整備を求める陳情","agenda":"令和３年陳情第６号 八潮団地に風呂付シルバーセンターの整備を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今の数字ですとやはり八潮が非常に高いのですけれども、そういう非常に高い八潮地区でかなり高齢化しているということに対して、特に高齢化に対する対策・対応というのはどういうものを取られているのでしょうか、あるいは取られていないのでしょうか。その点お伺いします。","respondent":"菅野高齢者地域支援課長","answer":"そういったことを考えますと、八潮地区全体の人口に対する既存施設の規模等を考えて、高齢者の施設が決して不足しているわけではないと認識しております。","voiceIndex":86,"id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"よく分からなかったのですけれども、今のお話は高齢者の人口数が少ないということなのですか。","respondent":"菅野高齢者地域支援課長","answer":"説明が足らず申し訳ございません。品川区全体の高齢者人口８万１,９２３人に対して、八潮地区の高齢者人口が４,２３９人ということで、区全体の高齢者人口から見ると、八潮地区の高齢者人口は少ないというご説明をさせていただいた次第です。","voiceIndex":88,"id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"その数字からして、八潮地区で特に対策を取る必要はないという話と理解してよろしいのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"先ほどもご説明させていただきましたが、地区内には全ての年代の方にご利用いただける活動の場として、八潮地域センターやこみゅにてぃぷらざ八潮がありますので、ぜひこちらの施設をご利用いただきまして、ふれあいの場、憩いの場、趣味、学習。","voiceIndex":90,"id":"exchange-027"},{"speaker":"おくの委員","kind":"質問・要望","question":"高齢者の方の共同の入浴施設、言ってみれば町場にある銭湯みたいなものだと私は思うのですけれども、高齢者の方のこういう銭湯みたいなものに対するご要望というのはかなり高いものがあると、私自身もそろそろ高齢者に足が届いているようなものですけれども、近所の高齢者の方のお話を伺っていてもかなり強いものがあると感じているのですけれども。","respondent":"菅野高齢者地域支援課長","answer":"八潮地区に入浴施設を作らないということにつきましては、現在の時点ではいろいろな要望を区民の皆様のニーズを基に検討していかなければいけないものだと考えていますので、現時点では考えておりませんということでお話しています。","voiceIndex":92,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは今まで何回も陳情で出されているものですけれども、そのときに、今後は、例えば「大規模な改修を行う機会などに必要な機能・設備について検討してまいります」ということで言われているのですけれども、大規模改修というときには、今回この陳情に出されているような入浴施設だったり、シルバーセンターやゆうゆうプラザのような機能も入れて、検討するということで捉えてよろしいのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"こちらの検討をするに当たりましては、地域にお住まいの方のニーズや区全体の施設の配置バランス等が重要になってくると思いますので、主管課と情報共有をしていきたいと考えております。","voiceIndex":94,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今回のショートステイ機能を特養ホームに移すというのではなくて、その校庭のところに新たに作る特養ホームにそういう機能が入れられるかどうかということを検討されるということなのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"八潮南特別養護老人ホームの増改築につきましては、特養ホームの定員増を目的として、来年度基本計画の検討に入るです。今の段階で分かっていることはそこまでです。","voiceIndex":96,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それはすごくいい機会なのではないかと思うのです。そこら辺の考え方も教えていただきたいのですが、そういうところで、この八潮南特養ホームの改修というか改めてその校庭に造るものに合わせて検討していただきたいということで書かれておりますので、その要望に応えていただきたいと思いますが、お願いします。","respondent":"菅野高齢者地域支援課長","answer":"しかしながら、現在区でも高齢化が進む中、超長寿社会に対応する視点を踏まえ、地域における共生社会の実現を目指しておりまして、ゆうゆうプラザにおける多世代交流など、楽しくやりがいを持って参加できるような施設の支援の充実を図っておりますので。","voiceIndex":98,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"築何年くらいというのも分からないですか。もし築何年ぐらいなのかということだけ分かったら教えていただきたいと思います。それから、八潮南特養ホームのほうは、そこにゆうゆうプラザを組み込むというところで検討していただきますように、要望させていただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"それからあと、こみゅにてぃぷらざ八潮に改修したのは、まだ１０年そこそこだったというように記憶しています。","voiceIndex":100,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっとこれは所管が違うまちづくりというところになるのかもしれないですけれども、分かる範囲で教えていただければと思います。","respondent":"菅野高齢者地域支援課長","answer":"今のご質問、八潮地区の将来像検討経費ということで、都市計画課のほうで予算を取って行っている事業だと認識しております。そちらはたしか平成３０年度末ぐらいに全世帯にアンケート調査をさせていただいたと聞いております。","voiceIndex":102,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。こういうご要望のお話は私もいただいていますし、東品川ゆうゆうプラザのお風呂で八潮の方にお会いすることもあります。そういう中でも、今、そういう話し合いを皆様で進めているというところですので、そこを尊重していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-034"},{"speaker":"渡部委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。前年度も３回ぐらいここで出ていたのですか。その辺から動きがないですし、今、担当課に聞いたところで確認が取れましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-035"}]},{"id":"topic-04","title":"介護・障害福祉サービス従事者に対するＰＣＲ検査の実施","agenda":"介護・障害福祉サービス従事者に対するＰＣＲ検査の実施","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここでは集中的実施計画を立てて、検査は遅くとも３月中までに実施してくださいという通知が出されたと思うのですけれども、この通知に基づいてやるということなのでしょうか。それと、それであれば集中的実施計画というのを立てるようにということでここで求められていると思うのですが、区としてこの集中的実施計画というのは立てられているか、その点についてもお聞かせください。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"昨年末に１回目を実施させていただきました。そのときは約４,０００人ということで、今回対象者数を増やしております。区として計画を立てるのかというお尋ねですが、それに関しましては感染症としての計画ですので、都が立てた後に現在区のほうでも立てております。","voiceIndex":117,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めて３,０００人ぐらい増えるわけですけれども、直接処遇者だけでなく、接する可能性のある方ということだと、例えば事務職の方ですとか運転手ですとか、そういうところにまで拡大されるということで、具体的にどういう方まで拡大されるのかということを教えていただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"それから財源につきましては、今回その通知を受けて行政検査として実施をいたします関係で、基本的には国のほうで財源の手当ては見込めるものと予定を立てているところです。","voiceIndex":120,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そのときのやり取りの中で、私はショートステイとかデイサービスもぜひやるべきなのではないかということで意見を申し上げたところだったのですけれども、そういうところでは特養ホームやグループホームの新規入所者だけではなくて、ショートステイの方も全てＰＣＲ検査をやってから毎回利用するという形になるのでしょうか。その点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"基本的に、原則としてショートステイの新規入所者の方に関しては、今検査をさせていただいているところですが、それは施設の状況にもよるところがありますので、必ずしも全て一律にという状況ではなく、その辺は施設の状況に応じて柔軟に対応させていただいているところです。","voiceIndex":124,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"これからはショートステイの場合も、各特養ホームによって検査する人としない人というのが特養ホームごとにちょっと違うみたいなことでいくのか、それとも品川区は統一で特養ホームの方にもやるし、それから新規入所者、ショートステイ、全ての特養ホームのところで全てやる方針ということなのか、その確認だけお願いします。","respondent":"宮尾高齢者福祉課長","answer":"各特養ホームで、東京都なりの補助金を使って独自にＰＣＲ検査をやっているところもあります。繰り返しになりますが、特に施設の実情、あるいは入所者の状況といったことを総合的に見て対応しているものと考えております。","voiceIndex":126,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"クラスターが発生しているということで、私が一般質問で伺ったときには、今年に入ってから医療機関で２例、介護施設で５カ所、保育園で３カ所というご答弁だったのですけれども、この介護施設というのはどのような種類のものなのか。デイサービスとかでも起こっているのか、それとも入所施設なのか、その類型だけ教えていただけないでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"入所施設、それから通所施設ともに発生しているという状況です。","voiceIndex":128,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということであれば、デイサービスの利用者に対してもＰＣＲ検査をやったほうがいいのではないかという思いは前からしているのですけれども、そこのところはする方針にはまだならないのでしょうか。その点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"は年度内に全ての施設の入所者、利用者、従事者に対して、全力で検査をしっかりとやっていきたいと考えています。","voiceIndex":130,"id":"exchange-041"}]},{"id":"topic-05","title":"を再度聴取いたします。 (2)国保財政健全化計画","agenda":"を再度聴取いたします。 (2)国保財政健全化計画","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それとこの法定外繰入金の削減予定額との関係がよく分からないのと、それからその法定外繰入金の削減予定額が、なぜ合わせて２億９,４５０万５,０００円になるのか。これでは足りなくないのかという思いをするのですけれども、法定外繰入金を毎年１％ずつ減らしていくということなので、これは減らす額だけが書いてあるので、毎年１％ずつの額という意味でこの額になるということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"赤字削減額のところで、まず第１年次に２億１,０００万円の赤字削減ができたですけれども、これは先ほど繰越金１６億円があったということでお話をさせていただいたところですけれども、こちらの数字は実際に法定外繰入金の部分で保険料の部分の削減額というのがございまして。","voiceIndex":138,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"難しいのでまた後でじっくり教えていただきたいとは思いますが、では法定外繰入金はその平成２８年度に１３億２,４００万円あって、平成３０年から４,９００万円ずつをずっと減らしていくということで考えて、それを令和２６年度くらいまでかけて１３億２,４００万円の赤字額を０にしていくという考え方でいいということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"今、副委員長が話されたことは理想ですけれども、実際には保険料の上昇、それと被保険者が毎年減少していることがありますので、実際に法定外繰入金について緩和率を１％減らして保険料を頂戴したとしましても、実際の年度になったときの被保険者がまず少なくなっていること。","voiceIndex":140,"id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もともと私は法定外繰入金をもっとたくさん出して、３５億円とか出していたわけですから、それで保険料を引き下げてきてたわけですから、それを高額療養費分を全部保険料で賄う仕組みにしたりとか、そういうふうに様々保険料に転嫁してきたという改悪の歴史がありますので、私は法定外繰入金を出しながら保険料を引き下げていただきたいと思っていますので。","respondent":"池田国保医療年金課長","answer":"令和３年度の保険料につきましては、緩和率９６％ということで保険料を計算させていただいているところでございまして、その分につきましては第４年次の部分で変わってくるとは思いますけれども、こちらの計画そのものが平成３０年度に出したものでございまして。","voiceIndex":142,"id":"exchange-044"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"鈴木ひろ子副委員長が一般質問しましたけれども、そのときに保健所での残業時間がすごかったという、１,２３９時間とか教えていただいたのですけれども、今現在そういう残業時間は大分解消されたのでしょうか。そこら辺をお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"引き続き常勤の職員については、定時に帰るという状況はなかなか難しい部分ではありますが、一時期の非常に夜中まで残っているという状態からは、今は解放されている状況です。","voiceIndex":149,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ教えてください。さっきのお話を聞く限りではないと思うのですけれども、そこら辺を聞かせてください。","respondent":"鷹箸保健予防課長","answer":"そこは早くなったのですが、ただ、そのことをまだご存じない方については連絡が来ないというふうに待っていた方もいらして、品川区電話相談窓口にいつ連絡が来るのだろうかというようなお問い合わせも数件はありましたけれども、事情をご説明して。","voiceIndex":151,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"質問の仕方が悪かったのですけれども、今回対応が変わったことによって、いずれにせよ再度ＰＣＲ検査に回ってくるということだから変わらないということですね。アクセスが早くなったということですね。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-047"}]},{"id":"topic-07","title":"ＨＰＶワクチンの区による情報提供","agenda":"ＨＰＶワクチンの区による情報提供","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"質問するかどうか迷ったのですけれども、たまたまうちの娘も中学校３年生で、周りの生徒たちが結構いっぱい受けているから私も受けたいというので、先々週、うちの妻はあまりお勧めではないのですけれども、予診票を３回分送っていただきました。ご本人というとまだそこまで発達していない子どもが判断できるか。詳細版は送らないのですよね。それは自分で探してくれということなのですか。","respondent":"鷹箸保健予防課長","answer":"２点目の詳細版は送らないのかということにつきまして、今回お送りするのはあくまでも概要版で、詳細版につきましては接種を希望された方に、区で作成しております両面刷りの説明文書とともにお送りするという予定にしています。","voiceIndex":164,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"専門家から見れば本当にいろいろなエビデンスがあるということもあるのですけれども、後でワクチンのお話、新型コロナウイルスのワクチンの話にも通じるので質問させてもらったのですけれども、やはりこういう機会はすごく大事だと私個人は思っていますし、あともう一つ言うと、保健所の対応がすごく早くて、ネットで申請したらもう次の日に送ってきたりするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-049"},{"speaker":"西村委員","kind":"質問・要望","question":"もう一つ、先ほどから言われています、このワクチン接種を検討する判断をするためのワクチンの有効性とか安全性が、本当に周りの母親たちからも分からない、不安だというお声が多い中で、このタイミングでよりしっかりと理解していただくことが大事かなと思っていまして、今後の検討段階でご検討いただければという要望でもあるのですが、現状、８年生にがん教育の推進授業をしていると思うのですけれども。","respondent":"鷹箸保健予防課長","answer":"がん教育については私の所管ではない部分になりますけれども、今までやっているがん教育については、その対象年齢も決まっていることと、個別の、例えば子宮頸がんについての教育とかということではなくて、がん全体についてお教えするという形で。","voiceIndex":167,"id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"すみません、もう一点、そのインターネット申請ができるということはどこまで周知されているのか、どのような方法で周知されているのか、教えていただけますか。","respondent":"鷹箸保健予防課長","answer":"ただ、毎年予防接種については１年の初めにお知らせをしたり、個別にはふだん、普通の予防接種ですとその接種時期の前に必ずお知らせをしているのですけれども、今後この新たな取組みについて、分かりやすい形で周知していく必要があるなと思いますので。","voiceIndex":169,"id":"exchange-051"}]},{"id":"topic-08","title":"新型コロナウイルスワクチン接種準備状況","agenda":"新型コロナウイルスワクチン接種準備状況","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"まだまだ調整中のところもたくさんあると思うのですけれども、会派からこれが分からないので聞いてきてほしいということで、幾つかお伺いをしたいと思います。４番のワクチンの種類というところで現在３種類がここに掲載されているのですが、これは接種したときに、本人にワクチンの種類というのが示されるのかどうか。まだ決まっていないかもしれませんが、今の３つ、教えていただけると助かります。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３点目、基礎疾患のある方ですが、区のほうで抽出することができませんので、基本的には自己申告という形になりますが、逆に基礎疾患のある方ですとかかりつけ医がおりますので、かかりつけ医の方に事前にご相談をいただくということで、こちらのほうからご案内しますので。","voiceIndex":176,"id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"前半の２問はいいのですけれども、最後のところで、これもまだ決まっていないのかもしれないですが、かかりつけ医と相談して、その後はどのタイミングで、予約のときにそれをかかりつけ医の人と相談したのだけれどもという形で申し上げるのか、それとも医師のほうから何かそういうことをやっていただけるのか、イメージ的に分からないところがあるので、ただこれはどうしても聞かれてしまうのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"かかりつけ医の先生が勧めるようでございましたら、実際に接種会場の予約をしていただいて、接種会場に行き、そこの最後に予診の先生がおりますので、そこで最終的なご判断をしていただくという形で現時点では考えております。","voiceIndex":178,"id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"しつこいようでごめんなさい。わかりました。ということは、接種券が届いて、自分はちょっと基礎的な疾患があってリスクが高いと思う方はかかりつけ医にご相談をして、あなたは早く受けたほうがいいよと言われれば電話とかウェブで予約をして、自分はそこで申告をするということでよろしいのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご説明で結構です。","voiceIndex":180,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"確認","question":"わかりました。最後にもう一回お願いします。ということは、そこで先ほど予診、会場で確認をすれば、優先的に受けられるということでいいのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点ではそのように考えております。","voiceIndex":182,"id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"初めてのことで、本当にたくさんの区民が対象だということで、区の皆様もご苦労が多いと思うのですけれども、なかなかイメージがつかない部分もたくさんありますのでちょっと伺いたいのは、新しくいただいた資料の６番の接種会場ですけれども、とりあえず４カ所、３カ所が４月からで、旧ひろまち保育園が５月以降ということですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点でのシミュレーションは以上のとおりです。最後に、医療機関についてですが、こちらは追加の資料のほうの２つめの米印に記載のとおり、現在医師会を含めて調整中ですので、こちらについては決まり次第また追ってご報告させていただきたいと考えております。","voiceIndex":185,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしますと、とりあえずは医師会と調整中ということで、そういうふうに医療機関でも何とかできないかということで医師会と調整していると考えていいのでしょうか。まだでしたら、いつ頃までにどういう形で作られるのかというのも教えていただきたいと思います。それから、これから様々な情報提供というのが必要になってくると思うのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今、ご質問いただいてあります医療機関については、現時点で調整を進めているというところで回答します。計画についてです。まさに現在作成中です。早急に作成しなければいけないと考えておりますので、作成しております。","voiceIndex":187,"id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に初めてのことでいろいろ細々と聞いてしまって申し訳ないのですけれども、コールセンター開設というのは、これは品川区としてのコールセンターを開設するということなのでしょうか。今のお話は東京都のコールセンターなのか、区としてもコールセンターを開設するということなのか。そしてそれはどういうところから確保するのか。そしてその見通しはできているのか、その点についてお聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"コールセンターの件ですが、３月１日に開設するのは品川区のコールセンターです。品川区民向けに開設いたします。同日広報に周知します。体制ですが、回線を１５本引いて体制を整えております。","voiceIndex":189,"id":"exchange-058"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"分かりました。そうですよね。１５本ということで分かりました。１５本に対しての体制というのは、どういう人が何人くらいの配置になるのか。その場合は大体１５分とか３０分様子を見るということが必要になってくると思うのですけれども、具体的に考えたらそういうのも結構体制をとるのが大変かなと思ったのですけれども、そこら辺の体制も、今の時点で決められているところがありましたら教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"コールセンターの件ですが、１５本というのは現時点で考えている数字でございまして、当然今後変動はある予定です。高齢者施設に関しましては現在関係所管を含めて調整を行っているところですので、こうするというものが現時点で確定しているものではございません。","voiceIndex":191,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"確認","question":"先ほどのコールセンターの話で思い出したのですけれども、それも聞いてきてくださいとうちの会派から言われたのですが、コールセンターのこの１５本の回線の中には、医療的な判断をしていただける方がいるということでいいのかどうか。先ほどのかかりつけ医ではないですけれども、医療的な質問をして答えられるのかどうかということが１つです。この２点を確認させてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"２点目、その他のワクチンとの兼ね合いですが、示されております。ほかのワクチンから１３日間を空けて、新型コロナウイルスのワクチンを打ちなさいということが、つい先日の自治体説明会でお話がありました。区のコールセンターの役割は、手引きの中にも書かれておりますけれども、事務的な予約であるとか、そういう関係の問い合わせということで、医療的なものについては都道府県がやるというのが原則でありますので。","voiceIndex":194,"id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"意見","question":"私からは接種情報の管理ですけれども、国のシステムがあると言われているのですが、これはどのような感じなのかということ、それと区のシステムとどうつないでいくのかということです。例の給付金のときの話ではありませんけれども、相当大変な状況になるのではないかと思っているのですが、その辺りのシステム等のいわゆる接種情報の管理等について、今分かっている範囲で結構ですのでお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"これはそれこそ今の委託業者のほうに区独自の予約システムの開発を依頼しているところでございまして、そのシステムと連動させることで区のほうに取り込む予定です。その取り込みの人員に関しては、委託業者等々も含めて現在対応を検討中です。","voiceIndex":199,"id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"品川区では数年前からＲＰＡで事務作業のスピードアップとその人員の削減を行っているのですが、ほかの自治体ではＲＰＡによってシステムを作って、今回のワクチン接種のいわゆる接種情報の管理をやっているところもあるのですが、現状としてそういったシステムは今委託業者がやられているというのですが、それぞれＲＰＡを品川区でやっている業者のシステムとは違うシステムなのかもしれませんけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"区の保健所でもともと使っているシステムを一部改修して取り込むという形です。その他、予約システムのほうとの連携は、区が作成するシステムについて現在連携を予定しているとご理解いただければと思います。","voiceIndex":201,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今回、今進行中のシステムでやられているということですので、ぜひ膨大な３５万人分の情報管理をして、さらにこの人は１回打った、２回打ったというのをやるのはものすごく大変だと思いますので、その辺ぜひ正確に、そしてスピーディーにできるような体制を要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"私もこれは聞いてきてほしいということで言われましたので伺いたいのですけれども、今医療機関の方から始まりましたけれども、その後医療施設で働く方々が３６０万人でしたか、されていくことになると思うのですけれども、介護従事者の方も仕事がかなり密に接するようになりますので、そういう点で優先しなくていいのかという声が地域の方から出ているということなのですけれども、この手引きを見ると。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"施設の従事者に関しましては、一緒に打てる方向で現在施設等と確認・調整中です。２点目、基礎疾患の方の重症化リスク等々を踏まえた接種順位に関しましては、これは全て国から示されておりますので、国から示されているとおり、区はそれに従って接種を進めていくです。","voiceIndex":204,"id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど１つお尋ねするのを忘れてしまったのですけれども、接種券にＯＣＲのラインが、厚生労働省のホームページに載っているのですけれども、それは先ほどの接種情報の管理の記録の入力には使えるのかということが１つ。それで、接種済証というのが来るわけですけれども、私は受けましたよというシールを貼ってもらうわけですね。それを見て、手で入力して管理していくのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"なので、現時点ではちょっと申し上げることができません。申し訳ありません。手入力にするかどうかということに関しても、何とかシステムでできないかということで、現在調整中ではありますが、タイムラグ等々のことを考えまして、どうするかというのも含めて現在調整中です。","voiceIndex":206,"id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3590#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":58608,"voices":223}},{"id":"r03-20210224-8","meetingId":"r03-cm02","date":"2021年2月24日","dateIso":"2021-02-24","committee":"建設委員会","time":"午前１０時００分～午後 ０時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"広町地区のまちづくり","agenda":"広町地区のまちづくり","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今後の予定のところで、３月下旬に関係権利者間でまちづくりに関する基本協定締結ということだったのですけれども、今、ご説明の中で、ＪＲをはじめとしたとあったのですが、この関係権利者がＪＲとほかにどこなのかというのをお知らせいただきたいと思います。","respondent":"多並都市開発課長","answer":"協定につきましては、主に２つの協定を結ぶ予定としています。１つは、このメインとなります土地区画整理事業に係る基本協定となります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"土地区画整理事業についてなのですけれども、すみません、勉強不足と、あと、探し切れておらず。区で示した手順というものが、区のホームページ等でも探せなかったので、その土地区画整理事業の手順をお知らせいただきたいと思います。","respondent":"多並都市開発課長","answer":"その認可した後に、換地と言いまして、土地を、お示しの図のような形で再編する計画がありまして、それを第三者の評価委員であるとか、公平性を担保しながら、換地計画を審査されながら定めて、それでおのおの最後、工事をやっていくということで、ただ、公共施設につきましては。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"土地区画整理事業では区も関わることから、区でも一緒に説明会を実施されるのかなということを思ったのですけれども、そこの確認と、あと、その説明会の中で一体何が説明されるのかといったところを確認させてください。事業計画等について説明されるのかといったところをご説明いただきたいと思います。","respondent":"多並都市開発課長","answer":"説明会の内容とも関わってくるのですけれども、説明会の内容としては、土地区画整理事業の概要と、あと、Ａ街区と先ほど言いましたけれども、ＪＲのほうが所有する予定の建築計画の概要ということで、２つの内容となっています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"その次に、２番目に説明会があって、そこで事業計画の原案や、測量・地質調査などについて、説明会を開いて地権者の皆さんに説明をということがあったのですけれども、今回の説明会では、事業計画等の説明ではなく、土地区画整理事業がどういったものかといった説明だということでよろしいですか。","respondent":"多並都市開発課長","answer":"具体的に、今のお話にあったような、一般の方が、要するに、今回の場合は関係者が、先ほど申したような企業ばかりの事業ですので、そういうことにならないのですけれども、一般的な、今のように住んでいる方がいらっしゃるような事業については、その後に案を説明して。","voiceIndex":12,"id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"今回は、その事業計画は示されないということで、議会等に事業計画が示されるのは、大体いつ頃になるのかといったところも確認させてください。","respondent":"多並都市開発課長","answer":"は都市計画決定をするのが来年度中の予定です。決定された後に、今度、認可を定めるまでに議会にご報告させていただいて、行っていきますので、現在来年度中を予定しています。そういった流れです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"確認なのですけれども、今回はＡ－１地区、Ａ－２地区のご説明ということで、ＪＲがまとめましたということのお話だと思うのですけれども、この取り決めの中で、もう土地の使い方は決まったということですよね。これから、事業、認可、いろいろあると思うのですけれども、これがもう決定だということでよろしいですか。","respondent":"多並都市開発課長","answer":"これまでも委員会の中で、利用区分ということで資料で説明させていただいていますけれども、今の、現時点の到達点としては、今回絵で描かせていただいた、このような形で区分する予定です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"まだまだ交渉半ばにあるのだというのであれば、例えば、品川区が土地を買ったりとかして、今、ＪＲのＡ－１地区、Ａ－２地区となっているけれども、例えばＡ－２地区のところを買うとか、自由にこちらが使わせてもらうとかというような、その融通性などはあるのですか、ないのですか。","respondent":"多並都市開発課長","answer":"ただ、これから進めていく中で、いろいろなことが起これば、またできないことではないのですけれども、方向としては、今お話ししたような方向で進めていく予定としております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"分かりました。やはり、ほかの土地はほかの土地なので、品川区は品川区の土地の中でいろいろ考えているよということは、けじめの合った形で区民の皆様方にも知っていただく必要があるのかなと思いますが、これからの周知の方法、今回はＪＲのほうが説明会をしますよということなのですけれども、品川区としてはどういう行動をとっていきますか。","respondent":"多並都市開発課長","answer":"３月の説明会も、区のほうも、土地区画整理事業という形で説明しますので、今、委員がご不安な点については、誤解が生じないように、よく説明させていただきたいと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今ももし、どこかの資料などであるのなら、そこも教えていただきたいですし、今後、そういった公表をしていただけたらと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"先ほど申しましたように、土地区画整理事業自体が区で初めて行う事業でもありますので、まず、その進め方については、説明会をこれから段階的に、３月にやる後に、次は都市計画手続きの中でも２回の説明会を、法令上もやる予定がありまして。","voiceIndex":23,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会についてなのですけれども、対象の方たちが限られているというか、対象区域というのが書かれてしまっているのですけれども、これ以外の方でも参加することは可能ですよねということを確認させてください。","respondent":"多並都市開発課長","answer":"もう１つの説明会の周知と、その対象者のところですけれども、広報しながわでも、３月１１日号でお知らせする予定で、広く周知することですので、もちろん、この範囲外の方も来ていただきたいと思っているところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"その際に、手話通訳者であったり、その辺の、情報弱者の方たちへの対応がどのようにされているのかという確認をさせてください。","respondent":"多並都市開発課長","answer":"手話通訳者の方につきましては、２回行う説明会、両日ともお越しいただいて、広報しながわであったり、また、配布する周知のビラ、ポスティングの中にも、手話通訳者がいらっしゃるということは記載させていただいて、情報をお伝えしたいと思っているところです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"視覚障害者の方の場合に、パワーポイント（のスライド）をそのまま流されると、そこが読めないということもあって、パワーポイント（のスライド）についてもきちんと説明を、口頭で言ってほしいといった声もあるのですけれども、そこの対応などもされますでしょうかということを確認させてください。","respondent":"多並都市開発課長","answer":"パワーポイント（のスライド）について、もちろん、手元にも資料を配付させていただいて、それに基づいてパワーポイント（のスライド）で詳しく説明するということになりますので、視覚障害者の方にも配慮するような形では、もちろん。","voiceIndex":29,"id":"exchange-012"},{"speaker":"のだて副委員長","kind":"質問","question":"今回、土地再編する中で、駅側にある区有地を現庁舎のほうに寄せてくるということですけれども、再編するにあたっての、価値は同等だということですけれども、そこの金額というのは幾らになるのか、伺いたいと思います。それで、今回、ＪＲの計画が、環境アセスメントの計画が発表されていますけれども、そこでの意見というのが、どういった意見があったのかということも併せて伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"のだて副委員長","kind":"質問","question":"金額のところは、具体的には事業計画で決まってくるということで、見込みもないということでしたけれども、大体の、同一になるという判断をされているわけですから、何かしらのつかみがあると思うのですけれども、それはいかがでしょうか。","respondent":"多並都市開発課長","answer":"土地の価格の、見込みというか、試算については、もちろん現在も共同検討でもしていますけれども、それについてはまだ公表するべきものではなくて、今後、適正な価格のもとに公表するべきものということですので、現時点で公表できるような価格がないと。","voiceIndex":35,"id":"exchange-014"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"既存商店街との関係で、そこは大きく商店街に影響が出ると思いますので、ぜひ考えていただきたいというふうに思います。それは、計画をやめることも含めて検討していただきたいと思います。高さのおおむね２倍という範囲になるということですが、これは最大の高さでいくと１１４ｍなので、２２４ｍの範囲が対象になるということでよろしいのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"説明会の周知の方法につきましては、広報しながわで周知するとともに、今のお話にありました計画の高さの予定のおおむね２倍の範囲ということで、約７,５００世帯の方々にポスティングで周知する予定です。","voiceIndex":37,"id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"基本協定なのですけれども、結ばれるのは、この説明会の後でいいですか。今後の予定で「３月下旬」としか書いていないのですけれども、前なのか後なのか、確認をさせてください。","respondent":"多並都市開発課長","answer":"現在の予定は、説明会の前に結べることで、しっかり説明会で説明させていただきたいとは思っているところです。","voiceIndex":40,"id":"exchange-016"}]},{"id":"topic-02","title":"（仮称）東五反田二丁目計画事業者による近隣説明会の開催","agenda":"（仮称）東五反田二丁目計画事業者による近隣説明会の開催","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"日野学園が。この日野学園の保護者に向けても、近隣に保育園もありますし、ぜひ事業者に、これらの保護者に向けての説明会に参加できるように求めてほしいのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今、委員からお話がありましたような保護者の関係については、個別に学校であったり保育園、幼稚園については説明させていただいて、事業はご理解いただきたいとは思っているところです。","voiceIndex":46,"id":"exchange-017"},{"speaker":"のだて副委員長","kind":"提案","question":"今回の計画というのが、地区計画を活用した検討を進めてきたということで、この地区計画のやり方と言うのですかね、市街地再開発事業などとは違うのか、どう違うのかというところなどについてご説明いただけたらと思います。","respondent":"多並都市開発課長","answer":"再開発というのは市街地再開発事業だけではなくて、いろいろな手法があるといつも説明させていただいているのですが、その中の１つになります。地区計画を定めて、その中で、再開発等促進区という地区を定めて、そこの中で行っていくことを予定しています。","voiceIndex":49,"id":"exchange-018"},{"speaker":"のだて副委員長","kind":"質問","question":"何となく、分かったような分からないような感じですが。素案ということですから、この北地区の計画もまだ決定したわけではないということだと思うのですが、そうした手続きのプロセスというのか、スケジュール感というのが分からないのですが、教えていただけますか。","respondent":"多並都市開発課長","answer":"ただ、具体的な整備計画については、今回、赤色で塗ったところについて定めているということになります。これを合わせて、都市計画として提案を受けて、来年度にその手続きに入っていくという計画で、今、進めているところであります。","voiceIndex":51,"id":"exchange-019"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、この全体の地区計画と個別の地区整備計画を同時に進めていっているということなのですね。分かりました。そうすると、今回の説明会では、この北地区の地区計画についても説明などをされるのでしょうか。そうであるならば、今回のこの建設委員会の報告でも、北地区の地区計画についても資料などの説明、報告があるべきではないかなと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"ただ、北地区全体の中で地区計画というのは、まだ具体的なところは定めませんけれども、これまでも事業者のほうで説明をしていますし、今回のこの内容についても、各地区を回りながら個別で説明させていただいているところもありますので、そういう流れでやっているです。","voiceIndex":53,"id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、この都市計画手続きに乗せることで、補助金はゼロということでしたので、容積率緩和が受けられるというメリットがあるかと思うのですが、ほかに利点やデメリットなどがあったら伺いたいのと、あと、今回の計画の総事業費などが出ていましたら伺いたいと思います。","respondent":"多並都市開発課長","answer":"容積率等の関係ですけれども、それ以外のお尋ねもありましたけれども、今回については準工業地域の３００％の容積の土地ですので、そこに対して、見直しを合わせて、空地だとか、今回、広場を造ることで、５２０％ですね、容積率ということで緩和する予定で考えております。","voiceIndex":55,"id":"exchange-021"}]},{"id":"topic-03","title":"その他のうち、(3)その他","agenda":"その他のうち、(3)その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"何日か前に、ユナイテッド航空のボーイング７７７ですか、エンジン損傷の事故があったことに関して、国土交通省等からの説明が、もし区にあったならお知らせいただきたいというのと、また、区の認識なども伺いたいのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そのプレスと同じ内容の説明も区のほうで受けてあります。基本的には、アメリカの連邦航空局に対し、本事案の原因究明および再発防止の実施を国として要請しているというところと、本事案に関する情報収集を現在行っているです。","voiceIndex":64,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"安全対策をとっていただきたいというのは要望したのかどうかというところを伺いたいと思います。海外から日本に乗り入れられるものを、この機種、ボーイング７７７を使わぬようにといった申入れはできないのかというところも確認させていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"それで、各国の飛行航空会社に対する指示というのは、今の私としての受け止めですが、それは各国でしっかり行っているのではないかですが、当然ながら、改めて、その辺の質問は当日も電話でのやり取りをしていますし、ただ、明確な答えは、そのときはいただいておりませんので。","voiceIndex":66,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"この事故発生後にも、このボーイング、同じ機種が飛んでいることについて、区民の方たちはとても不安に思っています。そういった声も届いておりますので、ぜひ区として、国にきちんと求めてほしいということと、あと、先ほど来、口頭でのやり取りがあったということなのですけれども、口頭だと、やはり形には残らないので、きちんと書面にて要望を提出してほしいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"それで、国として直ちにとるべきことについてはプレスがされている中で、しっかり安全対策、安全確認も情報収集も含めて行っていくですので、区としては、今後も様々な機会を捉えて国のほうには要望してまいりますが、適時適切、手法を使って要望していきたいです。","voiceIndex":68,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"改めてとなりますが、事故後に区民の方たちはとても不安に思っております。同じような事故が品川区の上空、品川区に限らず東京の上空で起こったら、もう人は絶対死んでいただろうという声も上がっていますし、国がやることはもうもちろんなのですけれども、ぜひ区としても、国にきちんと要望を書面で行っていただきたいと強く要望いたしますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"区としてはやることはやっていくといったことなのですけれども、今回の事故を受けて、区としてはどのように受け止めたのか。そして、区民の方たちが不安に思っている中で、やるべきことは、区としてきちんと国に対して要望を提出することなのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。では、区として、今回、要望を出すべきではないと判断した理由をお知らせください。","respondent":"鈴木都市計画課長","answer":"先ほどからご答弁申し上げているとおり、外国の損傷事象ということで、それは国としてしっかり連邦航空局に対して伝えてあるというところの報告もいただいておりますし、そうした意味で、あえて品川区として文書をもってという必要はないというふうに判断しています。","voiceIndex":75,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"自治体として、きちんと区民の命や生活を守る立場に立って、要望書をきちんと提出していただきたいと強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"だからやらなくていいのかというわけではなくて、私たちは、品川区民の皆様の生命を守るということが前提にあって、これについては、何か起きたらどう責任をとるのかということぐらい、強く言ってもいいのではないですか。何か、「いやあ、ほかの国のことだから、国がやることだから」というのは、あまりにも危機管理がなされていないのではないかと思うのですが、いかがですか。","respondent":"鈴木都市計画課長","answer":"その意味で、危機管理というお尋ねもございましたが、危機管理を含めて徹底していただくのは、これは当然国が行っている、航空事業に関してはですね、国にしっかり危機管理を行っていただくというのが区としての受け止めですので、そうしたところでは、常々。","voiceIndex":79,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、国に対してしっかりした答えを求める。そして、品川区は、やはりホームページも何でも、書面を出した、そして、国のほうからの何かの返答が来れば、それをきちんと伝えるということをしておいたほうがいいのではないでしょうか。口頭だけではなくて。品川区は、もろに上空を飛んでいるではないですか。だから、それについてはきちんとした国の考えを求めていくべきだと思います。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今回の事象について、国のほうではプレスで、先ほどご説明したとおり、区のほうとしても説明を受けておりますし、国としてもこうした措置をとっていると。連邦航空局のほうには再発防止等も求めている中で、情報収集も行っているというところで聞いております。","voiceIndex":81,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"押し問答になりますので最後にいたしますが、やはり、返答は求めていただきたいと思います。田中委員と一緒ですけれども、しっかりとした文書でのお答えをもらっていただきたいです。「言いましたよね」の範疇ではなくて、きちんと、こういう責任をとります、これはこういう考えをもってやりますというようなことを、しっかり文書でいただくように努力していただくように強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"確認","question":"私もプレス発表は見ました。これは、それで安全確認をしますと。これはボーイング社がどういうふうにするか、また、日本もどういう、具体的に調査をして安全確認をするかと、私は細かいことは知らないけれども、だけど、必ずそれはやりますということですよね。日本国中。それをどうしていくかというのは、品川区もほかのところも同じ条件なので、いつ起きるか分からない。私はそれで十分だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-032"},{"speaker":"のだて副委員長","kind":"質問","question":"１点だけお聞きしたいのですが、今回、ＡＮＡとＪＡＬについては、同じエンジンを搭載したものは停止をしたということですが、ほかの航空会社で所有しているところはないのか、そういったところはどうなっているのかということを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-033"},{"speaker":"のだて副委員長","kind":"意見","question":"そうしたもとで、この都心の上を低空で飛んでくるこの羽田新ルートというのは、やはり中止すべきだというふうに思うのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-034"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"中止を求めるべきではないかと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"安全対策の徹底を含めて、様々な取組は、事業主体である国のほうでしっかりとっていただくと。区としては、安全対策を含めた取組を徹底していただく、さらにやっていただくというのを求めていくというのは、今後もしっかりやっていきたいです。","voiceIndex":92,"id":"exchange-035"}]},{"id":"topic-04","title":"安全性確保対策を検討するバス停留所","agenda":"安全性確保対策を検討するバス停留所","exchanges":[{"speaker":"田中委員","kind":"意見","question":"今、もう区はバス事業者と検討を始めているということだったのですけれども、その検討の中には、やはり、バス停の位置をずらすなどのことが含まれるのかといったところや、その安全対策をしていく大体のスケジュールというのが、もしあればお知らせいただければと思います。","respondent":"稲田土木管理課長","answer":"この計画の予定ですけれども、私どもとしましては、安全に関わることですので、全体計画をいつまでというふうには立ててはおりませんけれども、できるだけ早い段階で対応できればなというふうに思って進めております。ただ、バス停をずらすと、これは地先の人が影響するのです。","voiceIndex":100,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"今、ずらすとかという話が出ていますけれども、この道は民家が並んでいるので、民家の前を乗り降りするのですよね。あまりよろしくないというか、反対者はいるのだろうなと、非常に思います。移動しようと思っても、移動する場所がない。ですので、それをどういうふうに考えられるのかなということと、それと、電柱がありますよね。電柱が邪魔なのですよ。どうしても。その辺はどうなのですか。","respondent":"稲田土木管理課長","answer":"将来的に、滝王子通りが拡幅されてというときには、また適切なバス停の配置とか、そういうのは考えていきながらやっていきたいというふうに思っておりますので、まずは安全性のためということを考えて取り組んでいきたいと思います。","voiceIndex":103,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"安全性という意味で言うと、このＡ、Ｂ、Ｃランクだけでは安全性がどうかというのは分からないと思うのですよ。この滝王子通りは本当に狭いので。逆に、この道にあるから、そこでの安全確保がとられているという可能性もあるのですよね。その辺も総合的に判断してやっていただきたい。これ、必ずやらなければいけないのでしょうか。何かしなければいけないということですか。","respondent":"稲田土木管理課長","answer":"私どもとしましては、再度言いますけれども、こういうバス停が挙げられているということにおきましては、やはり、何らかの形で対応はとっていきたいというふうに思っております。いろいろな状況を把握、考えながら今後もやっていきたいと思います。","voiceIndex":105,"id":"exchange-038"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この２２４箇所が公表されたということで、スピード感という意味で、この品川区内の２箇所というのはいつ頃になるのかというのが、大体のところで、どういうイメージを持っていらっしゃるのか、伺いたいと思います。それと、先ほどからいろいろ意見が出ておりますが、住民の理解を得て、やはり場所などそういったことも含めて進めていただきたいと思うのですが、いかがでしょうか。","respondent":"稲田土木管理課長","answer":"そういう意味では、区もこの２箇所をやっていこうということでご説明したとおりなのですけれども、区といたしましては、できる限り早い段階で解決していきたい。","voiceIndex":108,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは早急に対応しようということなので、それは国も、東京都も、今、２２４箇所を調査してやりましょうということなのだから、それは早急に対応していただきたいと思っています。歩道が確保されている。その辺の感覚は区もお持ちだと思うのだけれども、その辺のところだけ、はっきり、やはりどういうのが安全だというのは、基準を持っていらっしゃると思うのだけれども、その辺は教えていただきたい。","respondent":"稲田土木管理課長","answer":"ただ、何せ狭いところにおいてはそういうことも難しいようなところも。そういうところで、なかなか、一方が立てば一方が立たないという状況はありますが、これは現場の状況をよく把握しながら、警察にも相談しながら、対応していきたいというふうに思っております。","voiceIndex":111,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはやっていただいていると、もちろん思っているのだけれども、そういうことをしっかり踏まえていただいてやらないと、一概にそういうふうに言えないではないですか。だから、変な話、コミュニティバスの話も昨日やったけれども、必ずそういうことがあったときに、必ずバス停はできるわけではないですか。そういうことも踏まえていただいて、安全対策をしていただきたいということだけお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"桐ケ谷通り、ここは今、報告事項の中で、バス停ということですけれども、桐ケ谷通りは全体的に、入り口から入り口までが、要は、かむろ坂へ行く道とバイパスになって、通りが多いのですよ。その割には歩道が段差があって、狭い。もう旧年来ずっと安全対策をやっているとは思うのですけれども、改めてどのような安全対策をこの辺は講じているのか、教えてください。","respondent":"稲田土木管理課長","answer":"今後、いろいろな対策等、考えられるところもまだあろうかとは思いますが、その辺、やはり状況を見て、今後もやっていきたいというところです。","voiceIndex":115,"id":"exchange-042"},{"speaker":"大沢委員","kind":"質問・要望","question":"このバス停の安全対策もさることながら、道路自体の安全性のほうが一番重要だと思うので、ここのところは不断の見直し、あるいは注目をしながら。その割には、通行する歩道が狭くて、滝王子通りと同じように、電柱に挟まれて狭くなってしまっているところもあるので、そこのところは常に意識、注目しながら、ここのところの安全性ということの見地から講じていただきたいと思います。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"},{"speaker":"若林委員","kind":"確認","question":"その方向で、区と事業者がこれから対策を作っていくのかというところの確認を１つ。一番最後のＡ、Ｂ、Ｃランクの別添資料があって、Ｂランクの文章に、「Ａランク以外でバス、バスがバス停留所に停車した」と続いているのですけれども、この「バスがバス停留所に停車した際に」というのは、後ろの文章がつながるのですが、最初の読点の前の「バス」というのは、どういうふうに理解したらいいのでしょうか。","respondent":"稲田土木管理課長","answer":"判定の優先基準は、バス前後が何ｍとか、そういう話がこの別添資料に書いてあるところですが、なかなかそういう。上ですね。「バス、バスが停留所に」……。要らないかもしれないです。要するに、この範囲内にバスが止まっているところはだめですよということです。","voiceIndex":119,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問","question":"前段のほうは、国から状況が指摘されているけれども、区と事業者で協議をして、この状況が解消されなくても、それに代わる安全対策も含めてということで、今の答弁で理解をしました。国が作成した資料でしょうか。区が作成したのだとしたら、明確にこの、今の指摘した、「バス、」のところが、意味がないのであれば、公式資料ですので、修正等が要るのかなと思ったのですが。","respondent":"稲田土木管理課長","answer":"この資料ですが、絵は区が作成したものですけれども、文言的には国がホームページで発表しているものをそのまま持ってきております〔同日後刻に「区の転記間違いである」と答弁訂正あり〕。","voiceIndex":123,"id":"exchange-045"},{"speaker":"若林委員","kind":"質問","question":"国が作成した文章ということであれば、申し訳ないのですけれども、そういう指摘が議会からありましたよと、それで説明がもし何かあるのだったら、また教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-046"}]},{"id":"topic-05","title":"自転車等駐車場における交通系ＩＣカード決済の試験導入","agenda":"自転車等駐車場における交通系ＩＣカード決済の試験導入","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それで、一応今回は試験導入ということなのですけれども、どういう評価だったらこれが本導入になるのか。それと、多分、そのときの質問の際に、品川区の負担額が出てきてしまうのですという話があったので、どのぐらいの負担として支払うことになってしまうのか、教えてください。","respondent":"川口交通安全担当課長","answer":"２点のご質問をいただいたと思います。１つ目なのですけれども、おおむね、全体の利用者の半数、約５割以上のＩＣカードの利用があれば、これは導入を前向きに検討してもいいのではないかというふうに考えております。","voiceIndex":130,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"５割以上ということなのですが、これは周知されれば、これから当然の動きになるのだろうなというふうに思っております。ただ、１つ分からなかったのが、手数料のところで、３.７５円、区のほうの負担はありませんよということなのですが、ただ、そうすると、指定管理者のほうが負担するのかなというふうに、少し疑問なのですけれども。どういう仕組みになっているのでしょうか。","respondent":"川口交通安全担当課長","answer":"その指定管理者のほうで、一旦その金額に、さらに指定管理料がありますので、そこの中で、要は払った分で、また区の歳入に落ちてくるという形です。","voiceIndex":132,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"要は、負担が、区はいいのですけれども、結局、１５０円かかっているわけではないですか。１５０円の儲け分が、今、指定管理者のほうに入っているわけでしょう。でも、またこれで３.７５円というのが引かれるということになってしまうのですか。そうすると、指定管理者のほうは、儲けが下がってしまうということですかね。その辺の仕組みが少し理解できないのです。","respondent":"川口交通安全担当課長","answer":"要は利益分としての考え方というのは、そこの指定管理料の中で考えられるというところですので、直接、指定管理者がその部分で見込んでいる金額ですので、あらかじめそこはそれしか入らないというのを了解の上でやっていることですので。","voiceIndex":134,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"区のほうはいいのです。区のほうは変わらないと思っているのですけれども、心配しているのは、指定管理者のほうの利益が下がってしまうのではないのかなと。だから、指定管理者のほうは（現金支払いでの）１５０円のほうがいいわけではないですか。だけど、手数料をそこから取るということは、指定管理者等の儲けというか利益が下がるのではないですかという話。どういうことなのでしょう。","respondent":"川口交通安全担当課長","answer":"説明が足りず申し訳ありません。委員ご指摘のとおりです。その分を見込んで、そこを対応しています。","voiceIndex":136,"id":"exchange-050"},{"speaker":"田中委員","kind":"確認","question":"現金の対応はしませんというふうになったら困るなというところを確認したいというのと、そこのところで、関連で気になるのが、もし停電時などというのは、自転車がもう取り出せなくなってしまったりなどするのですかというところを確認したく、お願いします。","respondent":"川口交通安全担当課長","answer":"２点目の停電時の対応ですけれども、こちらのときには、アナログになってしまいますけれども、指定管理者の対応している警備員等で、それぞれの具体的な、例えば機器の対応で、一時的に料金的なもののロック等を解除しまして、自転車の出し入れなど。","voiceIndex":139,"id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけど、とりあえず試験導入だからサービスでいいですよと言っているのかと、大分違うではないですか。本格導入して全部やりますと言ったら、品川区の対応としては、指定管理料に２.５％上乗せして払わなければならないのですか。だけどこれ、全部になったら、２.５％取られているわけだから、全部やったら、今度、指定管理の変更をやるときに、区としては指定管理料が２.５％増えるのですか。","respondent":"川口交通安全担当課長","answer":"今後、利用の状況、これは今、試験導入の段階ですから、当然、今の段階でということではないのですけれども、結果的にはそのような形で上乗せをしなければ、当然、委員ご指摘のとおり、指定管理者のほうの収益の部分にもつながってきますので。","voiceIndex":142,"id":"exchange-052"}]},{"id":"topic-06","title":"目黒川安全航行啓発活動の実施","agenda":"目黒川安全航行啓発活動の実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これは５回目ということなのですけれども、どのぐらいマナー等の注意をしてという、注意喚起をした件数とか、あと、非常に悪質だとか、そういうケースはあるのかどうかお聞きしたいのですけれども。","respondent":"松本河川下水道課長","answer":"平成２９年から実施をしておりますが、そのときから、区に対して、例えば、観光船のアナウンスがちょっとうるさいであるとか、少し離れた場所で水上オートバイが暴走しているというような苦情は寄せられていますが、実際にこの啓発活動の中で注意をするということはございません。","voiceIndex":150,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"これも、始めた当初も、具体的に、ひどい、マナーの悪いというような話を少し受けていたような気がしたのですけれども。２７日、２８日、２日間だけということなのですが、これは通常、継続的にすることはもうないのですか。この２日間だけなのでしょうか。何かほかに、ずっと監視をしていくなどということはあるのでしょうか。","respondent":"松本河川下水道課長","answer":"通常につきましては、警備ということは特段はしてございませんが、このガイドマップをいろいろな団体等に配布をして、マナーを守っていただきたいということは、継続して周知をしています。","voiceIndex":152,"id":"exchange-054"},{"speaker":"西本委員","kind":"意見","question":"始まったきっかけがそうだったと思うのですよね。水上オートバイなどの問題があってということから始まって、始めてから非常に効果があったという、そういう認識だったので、それが継続されているのだなというふうに思っております。ですので、安全を確保しながら、近隣の方々の迷惑にならない形で楽しんでいただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"何かそのたびに改善、当初より改善と言いますか、工夫して今回５回目、当初とはこういうところがこういうふうに変わってきていますと、こういう課題が解消されたので、こういうことはもうしませんとか、逆に、こういう課題がまた見えてきたので、当初やっていなかったこういうことをやりますとか、そういう団体の中での、委員会の中での声とか、そういうのがあったらお聞かせいただきたいのが１つ。","respondent":"松本河川下水道課長","answer":"併せて、資料の１枚目にあります専用旗やステッカーの申請につきましては、今まで窓口で実施してございましたが、電子申請でもできるような形で、昨年度からそういった取組等を行って、改善できるところは逐次改善するようなことで取組を行っているところです。","voiceIndex":156,"id":"exchange-056"},{"speaker":"若林委員","kind":"質問・要望","question":"もう１回確認です。今のご答弁で、山本橋とおっしゃっていましたか。私が見ているのが違うのかな。ああ、すみません、違う地図を見ていました。了解しました。では、全体で言うと、まだ十幾つあるのですよね。毎年、都等の力も借りながら、やられているということで、引き続き頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"確認","question":"これはもう、ここでここを通らないと危ないと、相手もプロで大分分かってきているからいいのだけれども、もっと活用するのなら、これはスポットを切っていって、それはいつも水流の問題、雨が多く降ったときにどうのこうのという話があって、なかなかこれが改善できないというのが、あと、水をもっときれいにしようという話のときも、必ずこういうことが出てくるのだけれども、これは。","respondent":"松本河川下水道課長","answer":"ほかの措置をしてからでないと、こういった撤去はできないのかなというふうに考えてありますが、そういうことで、そこは厳しいというふうに考えてあります。","voiceIndex":160,"id":"exchange-058"}]},{"id":"topic-07","title":"品川区ミニ防災フェア２０２１","agenda":"品川区ミニ防災フェア２０２１","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"今年は残念だなというふうに思いますけれども、防災サッカーイベントとあって、何でサッカーなのでしょうか。ほかのスポーツでもいいわけですよね。何でここであえてサッカーなのでしょうかというのが、非常に疑問になるところなので、教えていただきたいと思います。","respondent":"中島防災課長","answer":"今回、サッカーというものを最終的には選ばせていただいたのですけれども、まず、やはりいろいろな、あまり防災への関心が比較的薄いというか、関心を持たれない若い世代、お子さん世代に関心を持っていただけるように、何かできないかなというところから考えまして、その中で。","voiceIndex":166,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"サッカーイベントというのは初めてという認識でよろしいでしょうか。このイベントのイメージをいろいろ挙げてあるのですが、これ、あまりサッカーと関係ないというか、何でもできますよね。いろいろなスポーツに該当すると思うのですよ。こればかりやると、何でサッカーなのという、やはり疑問が湧いてしまうので、その説明もしっかりしていただきたいなと思うのですが、いかがでしょうか。","respondent":"中島防災課長","answer":"この防災サッカーというのは、防災課の事業としては初めて行わせていただくところなのですけれども、例えば区内ですと、２０２０年に台場小学校で行われたりとか、あと、２０１９年のしながわ水辺の観光フェスタとか、そういうところでも実施の実績があるということから。","voiceIndex":168,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"第１回目ということで、いろいろ学ぶところが多くあると思うので、そこを学んでいただいて、ほかのスポーツも絡めてやっていくという形で、ぜひやっていただきたい。サッカーばかりというと、そればかりではないので。品川区の中で頑張っている子どもたちには、いろいろな競技があるので、それも含めて今後展開していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-061"},{"speaker":"大沢委員","kind":"質問","question":"先ほど、サッカーには、（啓発の）効果があるということで課長の発言がありましたけれども、その辺は何かの基準をもって、きちんと検証された結果をご発言なされているのか、教えてください。","respondent":"中島防災課長","answer":"ですので、効果というのは、実際、今回、併せて検証するところですが、やはり、単に防災というところで、今まで防災訓練とか、そういうものを中心に取り組んでいたところなのですけれども、ほかのイベントですね、今回、サッカーを選ばせていただいたのですけれども。","voiceIndex":171,"id":"exchange-062"},{"speaker":"大沢委員","kind":"質問","question":"効果検証というのは当たり前のことで、発言の中で、今言ったように、非常に効果があるようなことを、サッカーということでおっしゃっていて、そこというのは、あくまでも課長の今までやっている感覚に基づいて言っていることなので、効果がある・なしに言及するというのは、ちょっと浅はかではないですか〔同日後刻に「判断をするには適当ではないのではなかろうか」と発言訂正あり〕。","respondent":"中島防災課長","answer":"失礼いたしました。しっかりと、感覚に基づかない形で。なかなか効果検証は、一言で言うと簡単ですけれども、実際は難しいところですが、皆さんの反響などをしっかりつかんでまいりたいと思います。","voiceIndex":173,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁の、謝金はお幾らなのでしょうか。謝金。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"７５万円全部のことですか。それとも、その中の一部として、この運営費の中に謝金も入っているという形ですか。金額を教えてください。","respondent":"中島防災課長","answer":"今、７５万円弱の中のうち、２０万円の内訳といたしまして諸経費があります。その２０万円の諸経費の内訳が、輸送に係る費用、アルバイトに係る費用、あと、ゲストの謝礼、あと、イベントの保険、コロナ対策用品等が含まれているものです。","voiceIndex":182,"id":"exchange-065"}]},{"id":"topic-08","title":"再び、(3)その他","agenda":"再び、(3)その他","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"先ほどの、私の防災課長に対する話の中で「浅はか」というような不適切な表現を使いましたので、そこのところ、「判断をするには適当ではないのではなかろうか」というような文言に修正をさせていただいて、お詫びをして訂正します。申し訳ありませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":43703,"voices":195}}]);
